```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>
#include <stdlib.h>

typedef struct {
    EVP_CIPHER_CTX* ctx;
    int ivSize;
} EncryptionContext;

// Function to initialize encryption context
EncryptionContext initEncryption(const char *key, const char *mode) {
    // Initialize OpenSSL encryption and decryption contexts
    EVP_CIPHER_CTX* encryptCtx = EVP_CIPHER_CTX_new();

    // Select cipher mode based on provided input
    const EVP_CIPHER* (*cipher)() = 0;
    if (!strcmp(mode, "CBC")) {
        cipher = EVP_aes_128_cbc;
    } else if (!strcmp(mode, "CFB")) {
        cipher = EVP_aes_128_cfb;
    } else if (!strcmp(mode, "OFB")) {
        cipher = EVP_aes_128_ofb;
    } else if (!strcmp(mode, "CTR")) {
        cipher = EVP_aes_128_ctr;
    } else {
        // Invalid mode
        exit(-1);
    }

    // Initialize the encryption context
    int ivSize = -1;
    if (!EVP_EncryptInit(encryptCtx, cipher(), (const unsigned char*)key, NULL)) {
        EVP_CIPHER_CTX_free(encryptCtx);
        exit(-1);
    }

    // Get the IV size
    if (!EVP_CIPHER_CTX_ctrl(encryptCtx, EVP_CTRL_GET_IVLEN, 0, &ivSize)) {
        EVP_CIPHER_CTX_free(encryptCtx);
        exit(-1);
    }

    EncryptionContext ctx = {encryptCtx, ivSize};
    return ctx;
}
```

