use std::fs;
use std::path::Path;
use std::sync::Arc;
use std::thread;
use std::time::Instant;
use failure::Error;
use log::info;

// Define a struct to hold your file processing configuration.
pub struct FileProcessorConfig {
    pub exclusions: Vec<String>,
}

impl Default for FileProcessorConfig {
    fn default() -> Self {
        Self {
            exclusions: vec![".git", ".DS_Store"].into_iter().map(|s| s.to_string()).collect(),
        }
    }
}

// Define your file processor struct.
pub struct FileProcessor<'a> {
    config: Arc<FileProcessorConfig>,
    root_path: &'a Path,
}

impl<'a> FileProcessor<'a> {
    pub fn new(config: FileProcessorConfig, root_path: &Path) -> Self {
        Self {
            config: Arc::new(config),
            root_path,
        }
    }

    // Start processing files.
    pub fn process(&self) -> Result<(), Error> {
        let start = Instant::now();
        info![start];
        self.process_dir(self.root_path)?;
        let duration = start.elapsed().as_secs_f32();
        info![duration];
        Ok(())
    }

    // Recursive function to process directories.
    fn process_dir(&self, dir: &Path) -> Result<(), Error> {
        for entry in fs::read_dir(dir)? {
            let entry = entry?;
            let path = entry.path();

            if path.is_file() {
                // Process your file here.
                self.process_file(&path)?;
            } else if path.is_dir() && !self.excludes(&path) {
                // Recursively process subdirectories.
                self.process_dir(&path)?;
            }
        }
        Ok(())
    }

    // File processing goes here.
    fn process_file(&self, path: &Path) -> Result<(), Error> {
        // Process the file here. You can use LLVM IR code generation library to do that.
        let _ = fs::read(path)?;

        Ok(())
    }

    // Check if a file or directory should be excluded.
    fn excludes(&self, path: &Path) -> bool {
        self.config.exclusions.iter().any(|ext|{
            let ext = format![".{}", ext];
            path.extension().unwrap_or("").to_string() == ext
        })
    }
}
```
