```javascript
const os = require('os');
const v8 = require('v8');

function testSuite(label, f, resourceManager, dependencyManager) {
  let heapUsedAtStart;

  return async (moduleName) => {
    const moduleInstance = await dependencyManager.loadModule(moduleName);

    try {
      // Clean the module before each test run
      resourceManager.clean();

      // Measure CPU and memory usage before test execution
      heapUsedAtStart = v8.getHeapStatistics().total_available_size;

      console.log(`Testing ${moduleName}...`);
      await f(label, moduleInstance);
      console.log('Test passed');
    } catch (err) {
      console.error(`Test failed: `, err);
    } finally {
      // Clean up resources after each test run
      resourceManager.release();

      // Measure CPU and memory usage after test execution
      const heapUsedAtEnd = v8.getHeapStatistics().total_available_size;
      const heapUsageDelta = heapUsedAtStart - heapUsedAtEnd;

      console.log(`Resource cleanup for module ${moduleName}. Heap usage delta: ${heapUsageDelta} bytes`);
    }
  };
}
```
In this example, the `testSuite` function accepts your four arguments (label, f, resourceManager, dependencyManager) and returns a new function that can be used to run tests. This new function takes as its argument the name of the module to be tested, loads it dynamically, runs the test case, logs any errors, and then cleans up resources after each test run. 

For CPU usage check you can use `os` Node.js built-in library methods like `os.cpus()` and for memory usage you are checking heap size before and after each test execution using `v8.getHeapStatistics().total_available_size`. 

