```javascript
const _ = require('lodash');
const stopword = require('stopword');
const fs = require('fs').promises;
const fetch = require('node-fetch');
let config = {};

// Update the configuration with new keyword sets
async function updateConfig(url, auth) {
  const response = await fetch(url, { headers: { Authorization: auth } });
  const data = await response.json();
  config = Object.assign({}, config, data);
}

// Streamline the text processing
function processTextStream() {
  let proprietarySet = new Set(config.proprietaryKeywords || []);
  let openSourceSet = new Set(config.openSourceKeywords || []);
  let excludeWordsSet = new Set(config.excludeKeywords || []);

  return createTextProcessorStream((text, encoding, callback) => {
    text = text.toString().replace(/[^\w\s]|_/g, "").toLowerCase(); // Removing non-word characters and lowercasing
    let words = stopword.removeStopwords(text.split(/\s+/), excludeWordsSet); // Remove common words/phrases

    let proprietaryProjectNames = [];
    let openSourceProjectNames = [];
    let projectName;

    for (let word of words) {
      if (proprietarySet.has(word)) {
        projectName = text.slice(text.indexOf('Project:') + 8, text.indexOf('Description')); // Extract project name from metadata
        proprietaryProjectNames.push(projectName);
      } else if (openSourceSet.has(word)) {
        projectName = text.slice(text.indexOf('Project:') + 8, text.indexOf('Description')); // Extract project name from metadata
        openSourceProjectNames.push(projectName);
      }
    }

    callback(null, { proprietary: _.uniq(proprietaryProjectNames), openSource: _.uniq(openSourceProjectNames) });
  })
}

// A stream that reads large text files line by line and processes them with the given function
function createTextProcessorStream(processorFunction) {
  let stream = new require('stream').Transform({objectMode: true});

  // Process each chunk of data
  stream._transform = (chunk, encoding, callback) => {
    processorFunction(chunk, encoding, callback);
  }

  return stream;
}
```
This code uses the Node.js `stream` module to process large documents in a streaming manner, avoiding loading the entire document into memory at once. It also integrates with an external configuration API for dynamically updating keyword sets. The stopword package is used for excluding common words and phrases during text processing. Lodash's uniq function is used to return unique project names.
']

['Here is a JavaScript function that matches your requirements:

```javascript
async function generateFooter(scriptObjects) {
    let HTML = '';

    // Create an array to store promises for each script object
    const promises = [];

    // Loop through each script object in the input array
    for (let script of scriptObjects) {
        // Generate a <script> tag with metadata and code
        let scriptHTML = `<!-- Description: ${script.description}, Author: ${script.author} -->`;
        scriptHTML += `<script key="${script.key}">${script.code}</script>`;

        // Handle dependencies if any
        if (script.dependencies && script.dependencies.length > 0) {
            for (let dep of script.dependencies) {
                const depScript = scriptObjects.find(s => s.key === dep);

                // Ensure the dependency exists and add it to the promise array
                if (depScript) promises.push(generateFooter([depScript]));
            }
        }

        HTML += scriptHTML;
    }

    // Load all dependencies asynchronously
    await Promise.all(promises);

    return HTML;
}
```
This function loops through each script object in the input array, generates a `<script>` tag with metadata and code, and handles dependencies by loading them asynchronously using promises. The function returns the complete HTML string for the footer once all scripts have been loaded. 

