const { PassThrough } = require('stream');

class StreamAggregator extends PassThrough {
  constructor(batchSize = 100, memoryLimit = Infinity) {
    super({ objectMode: true });

    this.memoryUsage = 0;
    this.buffer = [];
    this.batchSize = batchSize;
    this.memoryLimit = memoryLimit;
  }

  _transform(chunk, encoding, callback) {
    const size = chunk.length; // or calculate the actual size of the chunk

    if (this.memoryUsage + size > this.memoryLimit) {
      console.warn("Memory limit reached, degrading performance...");
      this.pause(); // pause reading from input streams to save memory

      // TODO: implement logic for graceful failure when memory limit is hit
    } else {
      this.push(chunk);
      this.memoryUsage += size;
    }

    if (this.buffer.length === this.batchSize) {
      this._flush();
    }

    callback();
  }

  _flush(callback) {
    while (this.push(this.buffer.shift())) {
      // Empty loop to ensure all items in the buffer are flushed
    }
    callback();
  }
}
```
