["Here is a possible JavaScript solution using Mutation Observer API for handling dynamic changes in DOM:

```javascript
function findMatchingElements(selector) {
    if (!selector || typeof selector !== 'string') return [];

    const results = Array.from(document.querySelectorAll(selector));
    const observer = new MutationObserver((mutationsList, observer) => {
        for (const mut of mutationsList) {
            switch (mut.type) {
                case 'childList':
                    if (!mut.addedNodes || !mut.addedNodes.length) break;
                    for (let i = 0; i < mut.addedNodes.length; i++) {
                        const added = Array.from(mut.addedNodes[i].querySelectorAll(selector));
                        results.push(...added);
                    }
                    break;
                case 'attributes':
                case 'characterData':
                    if (mut.target && mut.target.matches(selector)) {
                        const index = results.indexOf(mut.target);
                        if (index !== -1) results.splice(index, 1);
                    }
                    break;
            }
        }
    });

    observer.observe(document.body, { childList: true, subtree: true, attributes: true, characterData: true });

    return results;
}
```

This function uses Mutation Observer to watch for changes in the DOM including added nodes and changed attributes or text. It only adds new elements that match the selector and removes those that no longer do from the result set. This ensures constant memory usage and doesn't cause infinite loops, making it efficient even when dealing with large document fragments.
"]

