let scriptCache = [];

function jsonp(url, callback) {
  const scriptElement = document.createElement('script');
  scriptElement.src = url;
  scriptElement.async = true;
  scriptElement.onload = () => {
    // Removes the element from body after loading.
    scriptElement.parentNode.removeChild(scriptElement);
  };
  scriptElement.onerror = (err) => {
    callback(new Error('Failed to load ' + url + '. Reason: ' + err));
  }
  document.body.appendChild(scriptElement);
}

function dynamicScriptLoad(url, version){
  return new Promise((resolve, reject) => {
      if (scriptCache[url]) {
        resolve(`Script ${url} already exists in cache`);
      } else {
        jsonp(url + `?v=${version}`, (err, data) => {
          if (err) {
            console.error(err);
            reject(err);
          } else {
            scriptCache[url] = true;
            resolve('Script '+ url + ' loaded');
          }
        });
      }
  });
}

