    public void setMetadataServiceUrl(String url) {
        this.metadataServiceUrl = url;
    }

    private Bitmap fetchBitmapFromServiceAndCache(String key) throws Exception {
        URL serviceUrl = new URL(this.metadataServiceUrl + "/validate?theme=" + URLEncoder.encode(key, "UTF-8"));

        for (int i = 0; i < 3; i++) {
            try {
                HttpURLConnection conn = (HttpURLConnection) serviceUrl.openConnection();
                conn.setRequestMethod("GET");

                if (conn.getResponseCode() == HttpURLConnection.HTTP_OK) {
                    BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream()));
                    String inputLine;
                    StringBuilder response = new StringBuilder();

                    while ((inputLine = in.readLine()) != null) {
                        response.append(inputLine);
                    }
                    in.close();

                    if (response.toString().equals("Valid")) {
                        return ImageIO.read(Paths.get(key).toUri().toURL());
                    } else {
                        throw new Exception("Invalid theme: " + key);
                    }
                }
            } catch (IOException e) {
                Thread.sleep((long) Math.pow(2, i) * 1000); // exponential backoff
            }
        }

        throw new RuntimeException("Metadata service unavailable after retries");
    }

    private void removeFromSecondaryStorage(String key) {
        try {
            Files.delete(Paths.get("/path/to/secondary/storage/" + key));
        } catch (IOException e) {
            System.err.println("Failed to delete from secondary storage: " + e);
        }
    }

    public Bitmap getBitmap(String key) throws ExecutionException {
        try {
            return cache.get(key);
        } catch (RuntimeException e) {
            System.err.println("Failed to retrieve bitmap: " + e);
            throw e;
        }
    }
}
```

This code uses the Guava library for its caching and LoadingCache utility, which is designed to handle all aspects mentioned in the problem statement. The `fetchBitmapFromServiceAndCache` method validates the theme using an external service before caching it, while the `removeFromSecondaryStorage` method handles eviction of themes from secondary storage when they are removed from the primary cache.

