        try {
            $config = $this->cache->get('yamlConfig');
            if ($config === null) {
                $config = Yaml::parseFile($this->yamlPath);
                $this->cache->set('yamlConfig', $config, strtotime('+1 hour')); // Cache for 1 hour
            }
            $this->applyConfig($config);
        } catch (Exception $e) {
            $this->logger->error('Failed to load YAML config: ' . $e->getMessage());
            throw new Exception("Failed to load YAML config.");
