  if (!envPath) throw new Error('Environment Variable is not set');

  privateKey = fs.readFileSync(`${envPath}/privatekey.pem`);
  certificate = fs.readFileSync(`${envPath}/certificate.pem`);
} catch (error) {
  console.log('Error reading certificates:', error.message);
}

class DataCollector {
  constructor() {
    this.dataQueue = [];
    this.isPaused = false;
  }

  addData(data) {
    if (!this.isPaused) {
      this.dataQueue.push(data);
    } else {
      console.log('Data collection is paused');
    }
  }

  pause() {
    this.isPaused = true;
  }

  resume() {
    this.isPaused = false;
  }

  clearData() {
    this.dataQueue = [];
  }
}

function generatePEMCertificate(collector) {
  let dataString = '';
  for (let i = 0; i < collector.dataQueue.length; i++) {
    // Assuming the queue contains objects with 'toPEM' method
    const pemCertificate = collector.dataQueue[i].toPEM();

    if (cache[pemCertificate]) {
      dataString += cache[pemCertificate];
    } else {
      // Assuming we are using crypto library to generate PEM certificate
      const newPemCertificate = crypto.generatePEMCertificate(privateKey, certificate, collector.dataQueue[i]);

      dataString += newPemCertificate;
      cache[pemCertificate] = newPemCertificate;
    }
  }

  return dataString;
}
```
