public class RandomValueGenerator
{
    private float minValue;
    private float maxValue;

    private static readonly Random rand = new Random();
    [ThreadStatic] 
    private static Random localRand;

    public RandomValueGenerator(int? seed = null)
    {
        if (seed.HasValue)
            rand = new Random(seed.Value);
    }

    private float GetRandomFloatInternal(float min, float max)
    {
        return UnityEngine.Random.Range(min, max);
    }

    public void SetRange(float minValue, float maxValue)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GetRandomFloat()
    {
        return GetRandomFloatInternal(this.minValue, this.maxValue);
    }

    private int GetRandomIntInternal(int min, int max)
    {
        if (localRand == null)
        {
            lock (rand)
                localRand = new Random(rand.Next());
        }

        return localRand.Next(min, max);
    }

    public int GetRandomInt()
    {
        var min = Mathf.CeilToInt(this.minValue);
        var max = Mathf.FloorToInt(this.maxValue) + 1; // Inclusive-Inclusive conversion

        return GetRandomIntInternal(min, max);
    }

    public override string ToString()
    {
        return $"Min: {this.minValue}, Max: {this.maxValue}";
    }
}
