#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *key;
    char *value;
} config_item;

typedef struct {
    pthread_mutex_t mutex;
    int count;
    config_item **items;
} configuration;

static configuration *config = NULL;

configuration* load_configuration(const char *file) {
    FILE *fp = fopen(file, "r");
    if (fp == NULL) {
        perror("Failed to open file");
        return NULL;
    }

    configuration *conf = malloc(sizeof(configuration));
    conf->count = 0;
    conf->items = malloc(1024 * sizeof(config_item*)); // Start with a reasonable size

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (line[0] == '#' || line[0] == '\n') continue; // Ignore comments and empty lines

        config_item *item = malloc(sizeof(config_item));

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");
        if (key == NULL || value == NULL) {
            free(item); // Malformed entry
            continue;
        }

        item->key = malloc(strlen(key) + 1);
        strcpy(item->key, key);

        item->value = malloc(strlen(value) + 1);
        strcpy(item->value, value);

        conf->items[conf->count++] = item;
    }

    fclose(fp);

    // Resize the items array if necessary
    if (conf->count >= 1024) {
        conf->items = realloc(conf->items, conf->count * sizeof(config_item*));
    }

    pthread_mutex_init(&conf->mutex, NULL);

    return conf;
}

void free_configuration(configuration *conf) {
    for (int i = 0; i < conf->count; i++) {
        free(conf->items[i]->key);
        free(conf->items[i]->value);
        free(conf->items[i]);
    }

    free(conf->items);
    pthread_mutex_destroy(&conf->mutex);
    free(conf);
}
```
