    public int SamplesPerPixel { get; set; }
    public int ExtraSamplesCount { get; set; }
    public string MD5Hash { get; set; }
}

public class ProcessTIFFFileService
{
    private const string RemoteConfigUrl = "http://example.com/config"; // replace with your remote config URL
    private HttpClient _httpClient;
    private SemaphoreSlim _semaphore;

    public ProcessTIFFFileService()
    {
        _httpClient = new HttpClient();
        _semaphore = new SemaphoreSlim(1, 1);
    }

    public async Task<TIFFImageInfo> ProcessTIFFFileAsync(string filePath)
    {
        using var stream = File.OpenRead(filePath);
        return await ProcessTIFFStreamAsync(stream);
    }

    private async Task<TIFFImageInfo> ProcessTIFFStreamAsync(Stream stream, CancellationToken cancellationToken = default)
    {
        // parse TIFF file here and extract metadata
        var imageInfo = new TIFFImageInfo();

        if (imageInfo.BitsPerSample != 1 && imageInfo.BitsPerSample != 2 && imageInfo.BitsPerSample != 4 
            && imageInfo.BitsPerSample != 8 && imageInfo.BitsPerSample != 16)
        {
            throw new ArgumentException("Unsupported bits per sample");
        }

        using var md5 = MD5.Create();
        var hashBytes = await md5.ComputeHashAsync(stream, cancellationToken);
        imageInfo.MD5Hash = BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();

        return imageInfo;
    }

    public async Task<TIFFImageInfo> ProcessFileWithRemoteConfigAsync(string filePath)
    {
        // Acquire semaphore to prevent concurrent downloads
        await _semaphore.WaitAsync();
        try
        {
            var response = await _httpClient.GetStringAsync(RemoteConfigUrl);

            // Parse and update local config with the response from remote server
            UpdateLocalConfig(response);
        }
        finally
        {
            _semaphore.Release();
        }

        return await ProcessTIFFFileAsync(filePath);
    }

    private void UpdateLocalConfig(string config) 
    {
        // Implement update logic
    }
}
```
