['Here is a sample C code solution based on your requirements.

```c
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define MAX_BUFFER_SIZE 512
#define MAX_FILENAME_LEN 256
#define MAX_SEGMENTS 100

char buffer[MAX_BUFFER_SIZE * MAX_SEGMENTS];
int currentSegment = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void processFilename(const char* filename, const char* extension) {
    pthread_mutex_lock(&mutex);

    int len = strlen(filename);
    if (len > MAX_BUFFER_SIZE - strlen(extension)) {
        // File name too large to fit in a single segment. Split it across segments.
        for (int i = 0; i < len; i += MAX_BUFFER_SIZE - strlen(extension) - 1) {
            char* ptr = buffer + currentSegment * MAX_BUFFER_SIZE;

            int remaining = len - i;
            int copySize = (remaining > MAX_BUFFER_SIZE - strlen(extension) - 1) ? 
                            MAX_BUFFER_SIZE - strlen(extension) - 1 : remaining;

            memcpy(ptr, filename + i, copySize);
            ptr[copySize] = '\0';

            sprintf(ptr + copySize, "%d-%s", copySize, extension);
            currentSegment++;
        }
    } else {
        char* ptr = buffer + currentSegment * MAX_BUFFER_SIZE;

        strncpy(ptr, filename, len);
        ptr[len] = '\0';

        sprintf(ptr + len, "%d-%s", len, extension);

        if (++currentSegment >= MAX_SEGMENTS) {
            currentSegment = 0;
        }
    }

    pthread_mutex_unlock(&mutex);
}
```
This code uses mutexes to ensure that the shared buffer is accessed safely by multiple threads. It also splits filenames across segments if they exceed the maximum segment size, and handles cases where a filename could fit within a single segment but would not fit in the remaining space in the current segment. 

Note: This solution assumes that the caller will ensure that `extension` is a valid string with enough room for digits and hyphen before calling this function. It also doesn't include error checking for invalid inputs or buffer overflows, which would be necessary in a production environment.
']

