```c
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

int background_command(char* command, char** env) {
    time_t start_time;
    pid_t child_pid = fork();

    if (child_pid < 0) return 0; // Fork failed

    if (child_pid == 0) { // Child process
        execle("/bin/sh", "sh", "-c", command, NULL, env);

        // If exec returns, there was an error
        fprintf(stderr, "Failed to execute command: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    } 

    // Parent process
    start_time = time(NULL);
    printf("Started child process with PID %d at %ld\n", child_pid, start_time);

    signal(SIGTERM, [](int signum) {
        pid_t child_pid;
        int status;

        // Send SIGTERM to all child processes
        while ((child_pid = waitpid(-1, &status, WNOHANG)) > 0) {} 

        exit(EXIT_SUCCESS);
    });

    return 1;
}
```
Please note that this function does not include all of the functionality required. For example, it doesn't manage a concurrency limit or log rolling beyond the last 100 entries. It also doesn't handle commands with spaces in their arguments properly because execle requires an array of strings as its arguments. It's recommended that this function be expanded into a complete background process management library for more complex requirements.
']

