import java.io.*;
import java.util.*;
import org.apache.commons.exec.*;
import org.apache.log4j.*;

public class ShellCommandExecutor {
    private static final Logger logger = Logger.getLogger(ShellCommandExecutor.class);

    private Map<String, String> rolePermissions;

    public ShellCommandExecutor() {
        // Load roles and permissions from external configuration file
        this.rolePermissions = new HashMap<>(); 
        // TODO: implement loading roles and permissions
    }

    public void executeShellCommand(String userRole, String command) throws Exception {
        if (!isAuthorized(userRole, command)) {
            throw new SecurityException("User is not authorized to run this command.");
        }

        logger.info(String.format("Executing command: %s", command));

        CommandLine cmdLine = CommandLine.parse(command);
        DefaultExecutor executor = new DefaultExecutor();
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        PumpStreamHandler streamHandler = new PumpStreamHandler(outputStream, System.err);
        executor.setStreamHandler(streamHandler);

        try {
            int exitCode = executor.execute(cmdLine);

            logger.info(String.format("Command '%s' exited with code: %d", command, exitCode));
            logger.info(String.format("Output of command: %s", outputStream.toString()));
        } catch (ExecuteException e) {
            logger.error(e);
            throw new Exception(String.format("Failed to execute shell command '%s'. Reason: %s", 
                    command, e.getMessage()), e);
        }
    }

    private boolean isAuthorized(String userRole, String command) {
        // Check if user role has permission to run the command
        return this.rolePermissions.getOrDefault(userRole, "").contains(command);
    }
}
```

