["Here is a simple example of how you might implement this functionality using JavaScript's Promises to handle asynchronous operations:

```javascript
function loadScript(url, options) {
  return new Promise((resolve, reject) => {
    let script = document.createElement('script');
    script.src = url;

    if (options && options.crossOrigin) {
      script.setAttribute('crossorigin', 'anonymous');
    }

    // Local caching mechanism
    const cachedScriptIndex = window._cachedScriptsRegistry 
                            ? window._cachedScriptsRegistry.indexOf(url) 
                            : -1;

    if (window._cachedScriptsRegistry && cachedScriptIndex > -1) {
      // Script is already cached, resolve immediately
      resolve();
    } else {
      script.onload = () => {
        if (!options || !options.noCache) {
          // Cache script for future calls
          window._cachedScriptsRegistry = window._cachedScriptsRegistry 
                                            ? [...window._cachedScriptsRegistry, url]
                                            : [url];
        }

        resolve();
      };

      script.onerror = (err) => reject(new Error(`Failed to load script from ${url}. ${err}`));
    }

    document.body.appendChild(script);
  });
}
```
