import com.google.common.cache.*;
import org.apache.commons.codec.digest.DigestUtils;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.TimeUnit;

public class HashUtil {
    private final Logger logger = LogManager.getLogger(HashUtil.class);
    private LoadingCache<String, String> cache;
    private YourDataSource dataSource; // replace with your own implementation of data source interface

    public HashUtil() {
        this.cache = CacheBuilder.newBuilder()
                .maximumSize(10_000)
                .expireAfterWrite(2, TimeUnit.HOURS)
                .build(new CacheLoader<String, String>(){
                    @Override
                    public String load(String input) throws Exception {
                        try{
                            return DigestUtils.md5Hex(input);
                        } catch (Exception e){
                            logger.error("Error while generating hash for " + input, e);
                            throw e;
                        }
                    }
                });
    }

    public String generateHash(String input) throws HashInputException {
        if (input == null || input.isEmpty()) {
            throw new HashInputException("Invalid input: Input string cannot be null or empty.");
        }

        try{
            return cache.get(input);
        } catch (ExecutionException e){
            logger.error("Error while generating hash for " + input, e);
            throw new RuntimeException(e.getCause());
        }
    }

    public void setDataSource(YourDataSource dataSource) {
        this.dataSource = dataSource;
    }

    // Enable/Disable cache as needed
    public void enableCache() {
       this.cache = CacheBuilder.newBuilder()... // create a new cache if not enabled yet
    }

    public void disableCache() {
        this.cache = null; // set to null to effectively disable caching
    }
}
``` 
