```go
package main

import (
    "log"
    "net/http"
    "time"

    "github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
    ReadBufferSize:  1024,
    WriteBufferSize: 1024,
}

func handler(w http.ResponseWriter, r *http.Request) {
    conn, err := upgrader.Upgrade(w, r, nil)
    if err != nil {
        log.Println("Failed to upgrade connection:", err)
        return
    }

    for {
        time.Sleep(time.Second)
        if err = conn.WriteMessage(websocket.TextMessage, []byte("heartbeat")); err != nil {
            log.Println("Failed to send heartbeat:", err)
            return
        }
    }
}

func main() {
    http.HandleFunc("/ws", handler)

    log.Fatal(http.ListenAndServe("localhost:8080", nil))
}
``` 

This is a simplified example and does not cover all the aspects of your request, but it should give you a starting point for building more complex systems. It includes setting up a WebSocket server in Go, which sends a heartbeat message every second to any connected clients.
