['```csharp
using System;
using System.Collections.Concurrent;
using System.Threading;

public class ValueGenerator
{
    private static readonly ConcurrentBag<Random> RandomPool = new ConcurrentBag<Random>();
    private int _minValue;
    private int _maxValue;

    public ValueGenerator(int minValue, int maxValue)
    {
        if (minValue > maxValue) throw new ArgumentOutOfRangeException("Minimum value must be less than or equal to maximum value.");
        this._minValue = minValue;
        this._maxValue = maxValue;
    }

    private Random GetRandomInstance()
    {
        if (!RandomPool.TryTake(out var random))
            random = new Random((int)DateTime.Now.Ticks & (int)Thread.CurrentThread.ManagedThreadId);

        return random;
    }

    private void ReleaseRandomInstance(Random random)
    {
        if (random != null)
            RandomPool.Add(random);
    }

    public float GenerateFloat()
    {
        var random = GetRandomInstance();

        try
        {
            return (float)(_minValue + random.NextDouble() * (_maxValue - _minValue));
        }
        finally
        {
            ReleaseRandomInstance(random);
        }
    }

    public int GenerateInt()
    {
        var random = GetRandomInstance();

        try
        {
            return random.Next(_minValue, _maxValue + 1);
        }
        finally
        {
            ReleaseRandomInstance(random);
        }
    }

    public decimal GenerateDecimal()
    {
        var random = GetRandomInstance();

        try
        {
            return (decimal)(_minValue + random.NextDouble() * (_maxValue - _minValue));
        }
        finally
        {
            ReleaseRandomInstance(random);
        }
    }

    public override string ToString()
    {
        return $"Range: [{this._minValue}, {this._maxValue}]";
    }
}
```
