#include <sys/wait.h>
#include <openssl/sha.h>
#include <string.h>

// Compute checksum function
char *computeChecksum(const char* input, const int len) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)input, len, hash);

    static char outputBuffer[65]; // 2 chars per byte + null terminator
    for(int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        sprintf(outputBuffer + (i * 2), "%02x", hash[i]);
    }
    outputBuffer[64] = 0; // null terminator

    return outputBuffer;
}

// Execute command function
int executeCommandInSeparateProcess(const char* command, int timeout) {
    pid_t processId = fork();

    if (processId == 0) { // Child process
        execl("/bin/sh", "sh", "-c", command, NULL);

        return -1; // If child fails to execute
    } else if (processId > 0) { // Parent process
        int status = 0;
        waitpid(processId, &status, WNOHANG | WUNTRACED); // Wait for process completion without blocking

        sleep(timeout); // Wait for specified timeout

        if (WIFEXITED(status)) { // Check if process exited normally
            return WEXITSTATUS(status); // Return the exit status of the child process
        } else {
            kill(processId, SIGTERM); // Terminate child process gracefully on timeout

            return -2; // If process did not complete within the specified timeout
        }
    } else {
        return -3; // If parent fails to fork a new process
    }
}
```
