#include "datastructure.h"

#define MAX_RECORDS 1024
static _Atomic(Record*) records[MAX_RECORDS];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize() {
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; ++i) {
        records[i] = NULL;
    }
