    Record* r = malloc(sizeof(Record));
    if (!r) return NULL;

    r->key = key;
    r->value = value;

    return r;
}

void addRecord(_Atomic(Record*) *data, Record* r) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (atomic_load(&data[i]) == NULL) {
            atomic_store(&data[i], r);
            break;
        }
