    pthread_mutex_unlock(&mutex);
}

void updateRecord(Record* data, int index, Record* new_record) {
    if (index < MAX_RECORDS && atomic_load(&data[index]) != NULL) {
        pthread_mutex_lock(&mutex);
        free(atomic_load(&data[index]));
        atomic_store(&data[index], new_record);
