```c
#include <stdlib.h>
#include <dlfcn.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    const char* name;
    void (*hash_function)(const unsigned char*, size_t, unsigned char*);
} hash_struct;

void load_hash_module(const char *path, hash_struct **modules, int *num_modules) {
    void *handle = dlopen(path, RTLD_LAZY);

    if (!handle) {
        fprintf(stderr, "Failed to load module %s: %s\n", path, dlerror());
        return;
    }

    // Assuming the loaded library exposes a function pointer named 'get_hash'
    hash_struct* (*get_hash)() = dlsym(handle, "get_hash");
    char *error = dlerror();
    if (error != NULL) {
        fprintf(stderr, "Failed to get symbol 'get_hash' from module %s: %s\n", path, error);
        return;
    }

    hash_struct* new_module = (*get_hash)();
    if (!new_module) {
        fprintf(stderr, "Failed to get hash function pointer from module %s.\n", path);
        return;
    }

    modules[(*num_modules)++] = new_module;
}

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
hash_struct **modules = NULL;  // Hash struct pointers are stored here.
int num_modules = 0;           // Number of loaded modules.

