```c
#include <stdio.h>
#include <unistd.h>
#include <pthread.h>

typedef struct {
    char destination; // 'f': file, 'c': console, 'n': network
    int threshold;
} Config;

void *logging_service(void *arg) {
    Config *config = (Config *) arg;
    FILE *logFile;

    if(config->destination == 'f') logFile = fopen("log.txt", "a");

    while(1){
        double load, memoryUsage, cpuUtilization;

        // Get system stats
        sysinfo(&si);
        load = 1.0 - ((double) si.loads[0] / (65536.0 * _SC_NPROCESSORS_CONF));
        memoryUsage = (double)(si.totalram - si.freeram)/si.totalram;
        cpuUtilization = 1.0 - ((double) si.idle/(si.idle + si.user + si.sys));

        // Adjust logging frequency based on system stats
        int sleepTime = (load > 0.8 || memoryUsage > 0.9 || cpuUtilization > 0.9)? 5 : 1;

        // Log if threshold is met
        if(config->threshold <= load) {
            char logMessage[256];
            snprintf(logMessage, sizeof logMessage, "Load: %f Memory Usage: %f CPU Utilization: %f\n", 
                     load, memoryUsage, cpuUtilization);

            if(config->destination == 'c') printf("%s", logMessage);
            else if(config->destination == 'f') fprintf(logFile,"%s", logMessage);
            // Here we would normally send logs to a network destination
        }

        sleep(sleepTime);
    } 

    return NULL;
}

int main() {
    Config config = {'c', 0.7};

    pthread_t thread_id;
    printf("\n Creating a new thread \n");
    int ret = pthread_create(&thread_id, NULL, logging_service, &config);

    if(ret != 0) {
        perror("Thread creation failed\n");
        return 1;
    }

    sleep(20);

    printf("\n Terminating the thread \n");
    pthread_cancel(thread_id);

    return 0;
}
```
