However, I can give you an overview on how to approach it. Here's some rough pseudocode:

```c
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>
#include <unistd.h>
#include <mysql/mysql.h>
#define MAX_SEMAPHORES 10

// Global variables for connection pool
MYSQL *conn_pool[MAX_SEMAPHORES];
int num_connections = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* acquire_connection(void* arg) {
    pthread_mutex_lock(&lock); // Lock to ensure thread safety when acquiring a connection
    while (num_connections >= MAX_SEMAPHORES) {
        sleep(1); // Wait if no connections are available. You might want to use condition variables for more efficient handling of this scenario.
    }
    MYSQL *conn = mysql_init(NULL); 
    conn_pool[num_connections++] = conn;
    pthread_mutex_unlock(&lock); // Release lock
    return conn;
}

void release_connection(MYSQL* conn) {
    pthread_mutex_lock(&lock); // Lock to ensure thread safety when releasing a connection
    for (int i = 0; i < num_connections; ++i) {
        if (conn == conn_pool[i]) {
            mysql_close(conn); 
            for (int j = i; j < num_connections - 1; ++j) { // Shift remaining connections to fill the spot.
                conn_pool[j] = conn_pool[j+1];
            }
            --num_connections;
        }
    }
    pthread_mutex_unlock(&lock); // Release lock
}

// Function for managing semaphores
sem_t* create_semaphore(const char *prefix) {
    static int id = 0; 
    char name[50];
    sprintf(name, "%s-%d", prefix, id++); // Create unique semaphore name.
    return sem_open(name, O_CREAT, 0644, 1); // Open a new named semaphore with initial value of 1 (unlocked).
}

// Function for executing SQL query and retrieving employee details
