void updateElement(size_t index, const NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&(array.mutex));
    if (index >= array.length) {
        // Handle error, index out of bounds
        return;
    }

    memcpy(&(array.array[index]), element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&(array.mutex));
}

void removeElement(size_t index) {
    pthread_mutex_lock(&(array.mutex));
    if (index >= array.length) {
        // Handle error, index out of bounds
        return;
    }

    if (index < array.length - 1) {
        memmove(&(array.array[index]), &(array.array[index + 1]), sizeof(NFAPI_CRC_INDICATION_PDU_T) * (array.length - index));
