NFAPI_CRC_INDICATION_PDU_T* get_structures(int N, int seed) {
    if (N <= 0) {
        return NULL;
    }

    // Allocate memory for the structures
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
