['Here is a basic implementation of your requirements in C# using ADO.NET for database operations and System.Security.Cryptography for hashing operation. Please note that this example assumes you have an existing connection to the database and you already have installed necessary dependencies (System, System.Data and System.Security.Cryptography namespaces). 

Please adapt these snippets according to your specific needs.

```csharp
using System;
using System.Collections.Generic;
using System.Text;
using System.Data;
using System.Data.SqlClient;
using System.Security.Cryptography;

public class DatabaseUtil
{
    public static IDataReader CreateParameterizedCommand(IDbConnection conn, string sql, List<object> parameters)
    {
        try
        {
            using (var command = conn.CreateCommand())
            {
                command.CommandText = sql;

                for (int i = 0; i < parameters.Count; i++)
                {
                    var parameter = command.CreateParameter();
                    parameter.Value = parameters[i];
                    command.Parameters.Add(parameter);
                }

                if (conn.State != ConnectionState.Open) conn.Open();

                return command.ExecuteReader(CommandBehavior.CloseConnection);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error creating parameterized command: " + ex.Message);
            throw;
        }
    }

    public static string ComputeMD5Hash(string input)
    {
        try
        {
            using (var md5 = MD5.Create())
            {
                var bytes = Encoding.ASCII.GetBytes(input);
                var hashBytes = md5.ComputeHash(bytes);

                var sb = new StringBuilder();
                for (int i = 0; i < hashBytes.Length; i++)
                {
                    sb.Append(hashBytes[i].ToString("X2"));
                }
                return sb.ToString();
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error computing MD5 hash: " + ex.Message);
            throw;
        }
    }
}
``` 

To optimize for large volumes of data, you might consider streaming the input string into the `MD5` class instead of reading it all into memory at once. But this approach is a bit more complex and may not be worthwhile depending on your specific use case. 

