    let handles = (0..16)
        .map(|_|  {
            let shared_vec = Arc::clone(&shared_vec);
            thread::spawn(move || process_file(&shared_vec))
        })
        .collect::<Vec<_>>();

    for handle in handles {
        handle.join().unwrap();
    }
}

fn get_files(dir: &str, settings: &Settings, files: &mut Vec<PathBuf>) {
    if let Ok(entries) = fs::read_dir(dir) {
        for entry in entries.filter_map(Result::ok){
            if entry.path().is_file() && matches(&entry.path(), settings) {
                files.push(entry.path());
            } else if entry.path().is_dir(){
                get_files(&entry.path().to_str().unwrap(), settings, files);
            }
        }
    }
}

fn matches(path: &PathBuf, settings: &Settings) -> bool {
    for ext in &settings.file_extensions{
       if path.extension().unwrap() == format![".{}", ext] { return true; }
    }
    false
}

