```c
#include <stdio.h>
#include <string.h>
#include <zlib.h>  /* For compression, assuming zlib library is installed */

void process_binary_file(int argc, char *argv[]) {
    if (argc != 6) {
        printf("Usage: %s input output rules extension compress\n", argv[0]);
        return;
    }

    char *input = argv[1];
    char *output_base = argv[2];  /* Base name of the output file */
    char *rules = argv[3];
    char extension = argv[4][0];  /* Extension character to append */
    int compress = atoi(argv[5]);  /* Convert command-line argument to integer */

    FILE *fin = fopen(input, "rb");
    if (fin == NULL) {
        printf("Failed to open input file.\n");
        return;
    }

    /* Determine the size of the input file and allocate memory for it. */
    fseek(fin, 0, SEEK_END);
    long size = ftell(fin);
    rewind(fin);

    char *buffer = malloc(size);
    if (buffer == NULL) {
        printf("Failed to allocate memory for buffer.\n");
        fclose(fin);
        return;
    }

    /* Read the entire file into memory. */
    size_t bytesRead = fread(buffer, 1, size, fin);
    if (bytesRead != size) {
        printf("Failed to read input file.\n");
        free(buffer);
        fclose(fin);
        return;
    }

    /* Apply transformation rules. */
    transform_buffer(rules, buffer, bytesRead);  // Assuming such a function exists

    /* Construct the new filename based on base name, extension, and compression indicator. */
    char output[1024];
    snprintf(output, sizeof(output), "%s%lu.%c", output_base, size / (compress ? 1024 : 1), compress ? 'z' : extension);

    FILE *fout = fopen(output, "wb");
    if (fout == NULL) {
        printf("Failed to open output file.\n");
        free(buffer);
        fclose(fin);
        return;
    }

    /* Write the modified data to the output file. */
    if (compress) {
        compress_and_write(buffer, bytesRead, fout);  // Assuming such a function exists
    } else {
        fwrite(buffer, 1, bytesRead, fout);
    }

    free(buffer);
    fclose(fin);
    fclose(fout);
}
```

The actual implementation would be significantly more complex and could vary greatly depending on the specifics of the transformations, file systems, and compression methods used. It is important to note that the above example does not include any error checking for simplicity's sake but in a real-world scenario you should always check the return values of functions that can fail.
