['Here's a simplified C function with basic functionalities to manage application logs. The implementation doesn't cover all the aspects of your requirements such as concurrent access from multiple threads, potential performance bottlenecks and disk I/O during flush operations etc., but it should give you an idea of how to start implementing these features:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int level; // DEBUG, INFO, WARN, ERROR etc.
    char* message; 
} LogEntry;

// A simple queue implementation
typedef struct QueueNode {
    LogEntry* logEntry;
    struct QueueNode* next;
} QueueNode;

QueueNode* front = NULL;
QueueNode* rear = NULL;
pthread_mutex_t lock; // For thread safety
int maxSize = 50;  // Maximum size of the queue
const char *filename = "log.txt";

void enqueue(LogEntry* log) {
    QueueNode* newNode = (QueueNode*)malloc(sizeof(QueueNode));
    if (!newNode) return;

    newNode->logEntry = log;
    newNode->next = NULL;

    pthread_mutex_lock(&lock); // Lock the queue before modifying it
    if (rear == NULL) {
        front = rear = newNode;
    } else {
        rear->next = newNode;
        rear = newNode;
    }

    // Flush logs to a file when the queue size reaches maxSize
    if (queueSize() >= maxSize) {
        flushLogs();
    }
    pthread_mutex_unlock(&lock);  // Unlock the queue after modifying it
}

void dequeue() {
    pthread_mutex_lock(&lock);  // Lock the queue before modifying it
    if (front == NULL) return;

    QueueNode* temp = front;
    front = front->next;

    if (front == NULL) rear = NULL;
    free(temp->logEntry->message); // Free the memory allocated for message string
    free(temp->logEntry); // Free the memory allocated for LogEntry structure
    free(temp);  // Free the memory allocated for QueueNode structure

    pthread_mutex_unlock(&lock);  // Unlock the queue after modifying it
}

int queueSize() {
    int count = 0;
    QueueNode* temp = front;
    while (temp) {
        temp = temp->next;
        count++;
    }
    return count;
}

void flushLogs() {
    FILE *file = fopen(filename, "a");  // Open the file in append mode

    if (file == NULL) {
        printf("Error opening file!\n");
        exit(1);
    }

    while (front != NULL) {
        fprintf(file, "[%d] %s\n", front->logEntry->level, front->logEntry->message);  // Write the log entry to file
        dequeue();  // Remove it from queue after writing
    }

    fclose(file);  // Close the file
}
```

This code doesn't handle unexpected log sizes and frequency spikes. You would need a more complex mechanism to deal with these scenarios, such as using dynamic memory allocation for logs instead of a fixed-size array or implementing a log rotation strategy that switches between different files or uses different techniques like compressing old logs.
Also, it doesn't handle thread safety for concurrent access. To handle multiple threads, you would need to use mutex locks or other synchronization primitives to ensure safe concurrent access.
Please note that this code is a starting point and needs further modifications and improvements according to your exact requirements. The logging queue design and flush operations are very basic for the purpose of simplicity and clarity. A more robust, optimized and thread-safe system would require a much more complex implementation.
']

