import com.google.common.hash.Hashing;
import com.google.common.util.concurrent.Futures;
import com.google.common.util.concurrent.ListenableFuture;
import com.google.common.util.concurrent.ListeningExecutorService;
import com.google.common.util.concurrent.MoreExecutors;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;

public class MD5HashService {
    private final ListeningExecutorService service = MoreExecutors.listeningDecorator(Executors.newFixedThreadPool(10));
    private Map<String, String> hashMap = new ConcurrentHashMap<>();

    public ListenableFuture<Void> processStrings(List<String> strings) {
        List<ListenableFuture<?>> futures = new ArrayList<>();

        for (String s : strings) {
            futures.add(service.submit(() -> hashMap.put(s, Hashing.md5().hashString(s, StandardCharsets.UTF_8).toString())));
        }

        return Futures.allAsList(futures);
    }

    public Map<String, String> getHashMap() {
        return hashMap;
    }
}
```
