using System;
using Newtonsoft.Json;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Primitives;
using Microsoft.Extensions.Logging;
using System.IO;

public class ConfigurationSettings
{
    public int TileSize { get; set; }
    public int WorldWidth { get; set; }
    public int WorldHeight { get; set; }
    public int CameraSpeed { get; set; }
}

class Program
{
    private static readonly ILogger _logger = new LoggerFactory().CreateLogger<Program>();
    private static MemoryCache _cache = new MemoryCache(new MemoryCacheOptions());
    private static ConfigurationSettings _settings = new ConfigurationSettings();
    private static TileServiceAPI _tileService = new TileServiceAPI();

    public async Task MainAsync()
    {
        // Load initial configuration settings
        await LoadConfigurations();

        var changeToken = _cache.GetChangeToken("config");
        changeToken.RegisterChangeCallback(async state =>
        {
            Console.WriteLine("Configuration has changed, reloading...");
            await LoadConfigurations();
        }, "config");
    }

    private async Task LoadConfigurations()
    {
        try
        {
            // Read the configuration file content
            string jsonContent = File.ReadAllText("appsettings.json");

            // Deserialize the JSON into a ConfigurationSettings object
            _settings = JsonConvert.DeserializeObject<ConfigurationSettings>(jsonContent);

            // Set the configuration cache with no expiration time (auto-expire on change)
            _cache.Set("config", _settings, new MemoryCacheEntryOptions { Priority = CacheItemPriority.NeverRemove });
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }

    private async Task<Tile> GetTileDataAsync(int x, int y)
    {
        string cacheKey = $"tile_{x}_{y}";

        if (!_cache.TryGetValue(cacheKey, out Tile tile))
        {
            try
            {
                // Fetch the tile data from the external API
                tile = await _tileService.FetchTileAsync(x, y);

                // Cache the fetched tile data with a sliding expiration time of 1 hour
                var cacheEntryOptions = new MemoryCacheEntryOptions()
                    .SetSlidingExpiration(TimeSpan.FromHours(1));

                _cache.Set(cacheKey, tile, cacheEntryOptions);
            }
            catch (Exception ex)
            {
                // Handle network failures and retries up to 3 times
                for (int i = 0; i < 2; ++i)
                {
                    await Task.Delay(1000);
                    try
                    {
                        tile = await _tileService.FetchTileAsync(x, y);
                        if (tile != null) break; // Successful fetch
                    }
                    catch { }
                }

                // Log an error after 3 failed attempts
                _logger.LogError("Failed to fetch tile data after multiple retries.");
            }
        }

        return tile;
    }
}
```
Please note that in a real world scenario, `TileServiceAPI` and its method `FetchTileAsync` should be implemented based on your specific use case. The error handling strategy for network failures and logging mechanism can be further fine-tuned as per the requirements. Also, please handle the caching strategies (expiration time, sliding expiration time) and configuration changes based on your business needs. This is a simplified example to give you an idea about how to tackle such scenarios.
