import org.apache.commons.codec.digest.DigestUtils;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpPut;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.FileInputStream;
import java.io.IOException;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class FileProcessor {
    private static final Logger logger = LoggerFactory.getLogger(FileProcessor.class);
    private CloseableHttpClient httpclient = HttpClients.createDefault();

    public Map<String, String> processFilesAndUpdateResource(List<Path> filePaths, String resourceId) {
        int concurrencyLevel = 4; // adjust according to your needs

        List<CompletableFuture<Optional<Map.Entry<String, String>>>> futures = new ArrayList<>();

        ExecutorService executorService = Executors.newFixedThreadPool(concurrencyLevel);

        for (Path file : filePaths) {
            if (!Files.isDirectory(file)) {
                CompletableFuture<Optional<Map.Entry<String, String>>> future = CompletableFuture
                        .supplyAsync(() -> computeFileHash(file), executorService)
                        .exceptionally(ex -> handleException(file, ex));

                futures.add(future);
            }
        }

        Map<String, String> fileHashes = futures.stream()
                .map(CompletableFuture::join)
                .filter(Optional::isPresent)
                .map(Optional::get)
                .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));

        updateResource(resourceId, fileHashes);

        executorService.shutdown();
        return fileHashes;
    }

    private Optional<Map.Entry<String, String>> computeFileHash(Path file) {
        if (file.getFileName().toString().equals("temp")) {
            return Optional.empty();
        }

        try (Stream<String> lines = Files.lines(file)) {
            String content = lines.collect(Collectors.joining("\n"));
            String md5Hash = DigestUtils.md5Hex(content);

            return Optional.of(new AbstractMap.SimpleEntry<>(file.toString(), md5Hash));
        } catch (IOException e) {
            throw new RuntimeException("Failed to read file: " + file, e);
        }
    }

    private void updateResource(String resourceId, Map<String, String> hashes) {
        HttpPut putRequest = new HttpPut("http://example.com/resource/" + resourceId);

        try (CloseableHttpResponse response = httpclient.execute(putRequest)) {
            if (response.getStatusLine().getStatusCode() != 200) {
                throw new RuntimeException("Failed to update the resource: " + resourceId);
            }

            // parse response and get updated resource details
        } catch (IOException e) {
            logger.error("Error updating resource", e);
        }
    }

    private Optional<Map.Entry<String, String>> handleException(Path file, Throwable t) {
        logger.warn("Failed to process file: " + file, t);

        return Optional.empty();
    }
}
```
This code uses a fixed thread pool of 4 for asynchronous processing of the files. You may need to adjust this number according to your specific needs and the capabilities of the underlying hardware or network infrastructure. The `computeFileHash` method reads each file into memory, which might not be optimal for very large files. If performance is a concern, consider using more efficient methods to read and hash large files.
']

