    public StateLoader(ExternalDependencyManager externalDependencyManager) {
        this.externalDependencyManager = externalDependencyManager;
    }

    // Use CompletableFuture to load state asynchronously
    public CompletableFuture<State> loadAsync(String pathOrUrl) {
        return CompletableFuture.supplyAsync(() -> {
            if (isValidPathOrUrl(pathOrUrl)) {
                externalDependencyManager.checkAvailabilityAndPermissions(pathOrUrl);

                // Load from remote URL or local file system
                if (externalDependencyManager.isRemoteResource(pathOrUrl)) {
                    return loadFromUrl(pathOrUrl);
                } else {
                    return loadFromFileSystem(Paths.get(pathOrUrl));
                }
            } else {
                return getDefaultState();
            }
        });
    }

    private boolean isValidPathOrUrl(String pathOrUrl) {
        // Implement your own validation logic here
        return true;
    }

    private State loadFromUrl(String url) {
