            URLConnection connection = new URL(url).openConnection();

            // Handle the response from the server
            // This could be deserialized XML, JSON, etc. based on your requirements
            byte[] data = connection.getInputStream().readAllBytes();

            return State.fromByteArray(data);  // Assuming there's a static method for this
        } catch (IOException e) {
            throw new RuntimeException("Failed to load state from URL", e);
        }
    }

    private State loadFromFileSystem(Path path) {
