['Here is a simplified example of what your code might look like based on the requirements you provided:

```java
import java.util.*;
import java.security.*;
import java.util.concurrent.*;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class MD5Service {
    private final static Logger logger = LogManager.getLogger(MD5Service.class);

    private ConcurrentHashMap<String, String> hashMap = new ConcurrentHashMap<>();

    public void processData(List<byte[]> data) {
        ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        for (byte[] bytes : data) {
            executorService.submit(() -> {
                try {
                    String hash = computeMD5Hash(bytes);
                    hashMap.put(Arrays.toString(bytes), hash);

                    logger.info("Processed hash: " + hash);
                } catch (Exception e) {
                    logger.error("Failed to process data", e);
                }
            });
        }

        executorService.shutdown();
    }

    private String computeMD5Hash(byte[] bytes) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] digest = md.digest(bytes);

        return Arrays.toString(digest);
    }

    public String getHash(byte[] bytes) {
        return hashMap.getOrDefault(Arrays.toString(bytes), "Not found");
    }
}
```
