        executor = Executors.newFixedThreadPool(serverAddresses.length);
        servers = new ConcurrentHashMap<>();

        try {
            selector = Selector.open();
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Failed to open selector", e);
        }
