        for (String address : serverAddresses) {
            executor.execute(() -> connectToServer(address));
        }

        new Thread(this::handleConnections).start();
    }

    private void connectToServer(String address) {
        try {
            ServerSocketChannel channel = ServerSocketChannel.open();
            channel.configureBlocking(false);

            String[] parts = address.split(":");
            InetSocketAddress socketAddress = new InetSocketAddress(parts[0], Integer.parseInt(parts[1]));
            channel.socket().bind(socketAddress);

            Server server = new Server(address, channel);
            servers.put(address, server);
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Failed to connect to server: " + address, e);
        }
    }

    private void handleConnections() {
