use std::time::Duration;
use hyper::client::{HttpConnector, Http};
use tokio::net::TcpStream;
use tokio::sync::Mutex;
use std::collections::HashMap;
use futures_util::future::{timeout, Timeout};

pub struct ClientPool {
    connector: Mutex<HttpConnector<Http>>,
}

impl ClientPool {
    pub fn new() -> Self {
        Self {
            connector: Mutex::new(Http::default_connector()),
        }
    }

    // This function is async and returns a future.
    pub async fn get(&self, url: &str) -> Result<Vec<u8>, Box<dyn std::error::Error>> {
        let client = HttpConnector::new(4).map_err(|e| format![ "Failed to create HTTP connector: {}" , e])?;

        let response = timeout(Duration::from_secs(5), client.get(url)).await.unwrap().expect("request failed");
        let bytes = hyper::body::to_bytes(response.into_body()).await.unwrap();

        Ok(bytes)
    }
}
