function updateClinicStatus(int $clinicId, string $newStatus, string $ipAddress, int $timeout = 5, int $retryAttempts = 3) {
    $conn = DriverManager::getConnection([ // using Doctrine DBAL connection pooling
        'driver' => 'pdo_mysql', 
        'host' => 'localhost', 
        'dbname' => 'mydb', 
        'user' => 'user', 
        'password' => 'secret', 
        'pooling' => true, // enable connection pooling
    ]);

    $result = ['success' => false, 'clinicData' => null, 'message' => ''];

    try {
        $retryCounter = 0;
        do {
            try {
                $conn->beginTransaction();

                // Update clinic status and last modified date/IP
                $sql = "UPDATE clinics 
                        SET status = ?, ip_address = INET_ATON(?), last_modified = NOW()
                        WHERE id = ?";
                $stmt = $conn->prepare($sql);
                $stmt->bindValue(1, $newStatus);
                $stmt->bindValue(2, $ipAddress);
                $stmt->bindValue(3, $clinicId);

                $rowsUpdated = $stmt->execute();
                if ($rowsUpdated > 0) { // successfully updated the record
                    $result['success'] = true;
                    // fetch updated clinic data
                    $sql = "SELECT * FROM clinics WHERE id = ?";
                    $stmt = $conn->prepare($sql);
                    $stmt->bindValue(1, $clinicId);
                    $row = $stmt->fetch();
                    $result['clinicData'] = $row;
                } else {
                    throw new Exception('No rows were updated.');
                }

                $conn->commit();
            } catch (\Exception $e) {
                $retryCounter++;
                if ($retryCounter > $retryAttempts) {
                    $result['message'] = 'Failed to update clinic after '.$retryAttempts.' attempts: '.$e->getMessage();
                    break;
                } else {
                    sleep(5); // delay before retrying
                }
            }
        } while (true);

    } catch (\Exception $e) { // log any other exceptions that occur
        $conn->rollBack();
        $result['message'] = 'An error occurred: '.$e->getMessage();
    } finally {
        $conn->close(); // close the connection
        return $result; 
    }
}
