        SSL_CTX_use_PrivateKey_file(*ctx, "certificate.pem", SSL_FILETYPE_PEM) <= 0 ) {
        ERR_print_errors_fp(stderr);
        return -1; // Error code
    }

    // Resolve the hostname to an IP address
    unsigned char addr[4];
    int ret = res_query(request.hostname, C_INET, T_A, addr, sizeof(addr));
    if (ret < 0) {
        perror("Failed to resolve hostname");
        return -2; // Error code
    }

    // Compare the resolved IP address with a known whitelist
    // If not in the whitelist, return an error
    if (!is_ip_in_whitelist(addr)) {
        printf("IP address not in whitelist\n");
        return -3; // Error code
    }

    // Implement DNS cache to reduce network latency and external service load
    resolve_hostname_and_cache(request.hostname);

    return 0; // Success code
}
```

