#include <unordered_map>
#include <queue>
#include <condition_variable>
#include <chrono>
// Include necessary dependencies

std::mutex eventQueueMutex;
std::condition_variable queueConditionVariable;

struct Event {
    int id;
    double impactScore;
};

class EventHandler {
private:
    std::unordered_map<int, double> performanceMetrics; // Assume this is fetched from external service.
    std::priority_queue<Event> eventQueue;

public:
    void processEvents() {
        while (true) {
            std::unique_lock<std::mutex> lock(eventQueueMutex);

            // Wait until queue has events or timeout occurs.
            if (!queueConditionVariable.wait_for(lock, 
                std::chrono::seconds(1), [this] { return !eventQueue.empty(); })) {
                    continue; // If no event after a minute, skip to next iteration.
            }

            Event highestImpactEvent = processEvent(eventQueue.top());
            performanceMetrics[highestImpactEvent.id] += highestImpactEvent.impactScore;
            eventQueue.pop();
        }
    }

    // Implement this function based on your requirement for impact score calculation
    Event processEvent(const Event& event) {

        // Example: impact score = priority / frequency within the last minute
        double impactScore = event.impactScore * performanceMetrics[event.id]; 
        return {event.id, impactScore};
    }

    void addEvent(const Event& event) {
        std::lock_guard<std::mutex> lock(eventQueueMutex);
        eventQueue.push(event);
        queueConditionVariable.notify_one(); // Notify one thread waiting on condition variable if there is any
    }

};
```
This code uses a priority queue to store events and std::condition_variable for signaling between threads. The priority_queue is automatically sorted based on the impact score of the events, so the highest impact event will always be at the top. The `processEvents()` function continuously processes events until no more events are available or a minute has passed.
']

