    info->bitsPerSample = (uint16_t) TIFFScanlineSize(tif)/width;  // assuming samples are packed tightly and each sample is 1 byte.
    info->samplesPerPixel = 1;  // TIFF does not typically store multi-sample data in a way that would support extracting more than one sample per pixel.
    info->compressionMethod = TIFFGetFieldDefault(tif, TIFFTAG_COMPRESSION);

    switch (info->compressionMethod) {
        case COMPRESSION_NONE:
            // no decompression required; use image size directly.
            info->decompressedSize = width * height * info->bitsPerSample / 8;
            break;

        case COMPRESSION_PACKBITS:
