struct cipher_context {
    EVP_CIPHER_CTX *ctx;
};

void free_cipher_context(struct cipher_context **cipher) {
    if (*cipher != NULL) {
        EVP_CIPHER_CTX_free((*cipher)->ctx);
        free(*cipher);
        *cipher = NULL;
    }
}

int initialize_aes256gcm(const char *password, struct cipher_context **cipher) {
    int rv = 0;
    size_t outlen;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];

    *cipher = malloc(sizeof(struct cipher_context));
    if (*cipher == NULL) {
        return -1;  // error: failed to allocate memory for cipher context.
    }

    /* Initialize the EVP context */
    (*cipher)->ctx = EVP_CIPHER_CTX_new();
    if ((*cipher)->ctx == NULL) {
        free_cipher_context(cipher);
        return -1;  // error: failed to create new cipher context.
    }

    /* Derive key using HKDF */
    EVP_PKEY_CTX *pctx = EVP_PKEY_CTX_new_id(EVP_PKEY_HKDF, NULL);
    if (1 != EVP_PKEY_derive_init(pctx) ||
        1 != EVP_PKEY_CTX_hkdf_mode(pctx, EVP_PKEY_OP_DERIVE) ||
        1 != EVP_PKEY_CTX_set_hkdf_md(pctx, EVP_sha256()) ||
        1 != EVP_PKEY_derive(pctx, key, &outlen)) {
        free_cipher_context(cipher);
        return -1;  // error: failed to derive key.
    }

    /* Set the IV length and cipher */
    if (1 != EVP_EncryptInit_ex((*cipher)->ctx, EVP_aes_256_gcm(), NULL, key, iv)) {
        free_cipher_context(cipher);
        return -1;  // error: failed to initialize cipher context.
    }

    /* Clean up */
    EVP_PKEY_CTX_free(pctx);
    OPENSSL_cleanse(key, sizeof(key));

    return rv;
}
