import java.io.*;
import java.nio.file.*;
import java.util.concurrent.locks.ReentrantLock;

public class Main {
    private static final String INPUT_FILE = "input.txt";
    private static final String OUTPUT_FILE = "output.txt";
    private static final String BACKUP_DIR = "/backup/";
    private static final String LOG_FILE = "log.txt";
    private static ReentrantLock lock = new ReentrantLock();

    public static void main(String[] args) {
        try {
            // 1. Move input file to backup if it exists
            Files.move(Paths.get(INPUT_FILE), Paths.get(BACKUP_DIR, INPUT_FILE));
        } catch (NoSuchFileException ignored) {
        } catch (IOException e) {
            e.printStackTrace();
        }

        // 2. Create output file with default permissions if it does not exist
        try {
            Files.createIfNotExists(Paths.get(OUTPUT_FILE));
        } catch (IOException e) {
            e.printStackTrace();
        }

        // 3. Redirect stdout and stderr to log file, ensuring thread safety with locking
        try {
            FileOutputStream out = new FileOutputStream(LOG_FILE);
            System.setOut(new PrintStream(out));
            System.setErr(new PrintStream(out));
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        }

        // 4. Execute shell command and retry up to three times in case of transient errors
        for (int i = 0; i < 3; i++) {
            try {
                Process process = Runtime.getRuntime().exec("cmd /c process_output.txt");
                int exitCode = process.waitFor();
                if (exitCode != 0) throw new Exception("Non-zero exit status: " + exitCode);
                break;
            } catch (Exception e) {
                System.err.println(e.getMessage());
            } finally {
                // 5. Release resources promptly to minimize resource contention
                try {
                    if (process != null) process.destroy();
                } catch (Throwable ignored) {
                }
            }
        }

        // Ensure proper release of lock and stream resources
        finally {
            System.setOut(System.out);
            System.setErr(System.err);
            if (lock != null && lock.isHeldByCurrentThread()) lock.unlock();
        }
    }
}
```
