using System;
using System.Security.Cryptography;
using System.Text;
using System.Collections.Concurrent;
using System.Linq;

public class DynamicHashFunction {
    private ConcurrentDictionary<string, HashAlgorithm> hashCache = new ConcurrentDictionary<string, HashAlgorithm>();

    public byte[] ComputeHash(string algorithmName, string input) {
        // Try to get the hash function from the cache
        if (!hashCache.TryGetValue(algorithmName, out var hashFunction)) {
            try {
                // If not in cache, create a new one and add it to the cache
                hashFunction = HashAlgorithm.Create(algorithmName);
                if (hashFunction == null) {
                    throw new ArgumentException("Invalid algorithm name");
                }
                hashCache[algorithmName] = hashFunction;
            } catch (CryptographicException ex) {
                Console.WriteLine($"Failed to create HashAlgorithm: {ex}");
                return null;
            }
        }

        try {
            // Compute the hash with the given function and input string
            var inputBytes = Encoding.UTF8.GetBytes(input);
            return hashFunction.ComputeHash(inputBytes);
        } catch (CryptographicException ex) {
            Console.WriteLine($"Failed to compute hash: {ex}");
            return null;
        }
    }
}
```
