import java.io.*;
import java.lang.reflect.Constructor;
import java.util.concurrent.ConcurrentHashMap;

public class CustomDeserializer {
    private static final ConcurrentHashMap<String, Class> cache = new ConcurrentHashMap<>();

    public Object deserialize(byte[] data) throws Exception {
        try (ByteArrayInputStream bis = new ByteArrayInputStream(data);
             ObjectInput in = new ObjectInputStream(bis)) {
            String className = (String)in.readObject();
            Class<?> clazz = getClassByName(className);

            Constructor<?> ctor = clazz.getConstructor();
            Object obj = ctor.newInstance();
            in.readFully((byte[]) clazz.getMethod("serialize").invoke(obj));

            // Validate the object here if necessary 

            return obj;
        } catch (Exception e) {
            logError("Deserialization failed: " + e);
            throw new RuntimeException("Failed to deserialize data", e);
        }
    }

    private Class<?> getClassByName(String className) throws Exception {
        if (!cache.containsKey(className)) {
            cache.putIfAbsent(className, Class.forName(className));
        }
        return cache.get(className);
    }

    private void logError(String message) {
        // Use existing logging utility 
        // ExistingModule.logError(message);
    }
}
```
