["```javascript
const fs = require('fs');
const path = require('path');
const fetch = require('node-fetch');
const sharp = require('sharp');

// Configurable options
const config = {
  imageFormats: ['jpg', 'png'],
  outputDir: './output/'
};

class JobManager {
  constructor(options) {
    this.config = Object.assign({}, config, options);
    if (!fs.existsSync(this.config.outputDir)) {
      fs.mkdirSync(this.config.outputDir, { recursive: true });
    }
  }

  async runJob(urls) {
    const results = { originalUrls: [], processedImages: [] };
    for (const url of urls) {
      try {
        // Fetch the media file from URL.
        const response = await fetch(url);
        if (!response.ok) throw new Error('Failed to download');

        // Read and identify the type of media.
        const buffer = await response.buffer();
        const format = await sharp(buffer).metadata().then(({format}) => format);

        if (this.config.imageFormats.includes(format)) {
          // If it's an image, convert to grayscale and store in output directory.
          const outputPath = path.join(this.config.outputDir, `${Date.now()}.${format}`);
          await sharp(buffer).grayscale().toFile(outputPath);
          results.processedImages.push(outputPath);
        } 

        // Log the original URLs even if they are not processed.
        results.originalUrls.push(url);
      } catch (error) {
        console.log('An error occurred: ', error);
      }
    }
    return Promise.resolve(results);
  }
}
```
