#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <wchar.h>
#include <locale.h>

void process_filename(const char *src, char* dst) {
    // Get the length of the source filename before processing
    size_t len = strlen(src);

    if (len > 256) {
        // If the length is more than 256 characters, dynamically allocate memory for src.
        char *dyn_src = malloc(len + 1);

        if (!dyn_src) {
            // Handle error case where allocation fails
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }

        strcpy(dyn_src, src);
        len = wcslen((wchar_t*) dyn_src);  // get the number of wide characters for UTF-8 encoded strings.

        free(dyn_src);
    }

    // Construct a new filename with the format "filename-length.extension"
    const char* dot = strrchr(src, '.');  // find the last occurrence of '.' in src
    if (!dot) {
        snprintf(dst, 512, "%s-%zu", src, len);  // no extension case
    } else {
        size_t extlen = strlen(dot + 1);
        snprintf(dst, 512, "%.*s-%zu.%.*s", (int)(dot - src), src, len, (int)extlen, dot + 1);  // filename with extension case
    }
}
```

