typedef struct {
    sem_t* sem;
    char name[128]; // assuming names are less than 127 characters long
} Semaphore;

Semaphore** initSemaphores(int num, int value) {
    Semaphore** semPool = malloc(sizeof(Semaphore*) * num);
    for (int i = 0; i < num; ++i) {
        Semaphore* sem = malloc(sizeof(Semaphore));
        strncpy(sem->name, "default", sizeof(sem->name)); // replace with your naming convention
        sem_init(&sem->sem, 0, value);
        semPool[i] = sem;
    }
    return semPool;
}

void freeSemaphores(Semaphore** pool, int num) {
    for (int i = 0; i < num; ++i) {
        sem_destroy(&pool[i]->sem);
        free(pool[i]);
    }
    free(pool);
}
```
