['Due to constraints, I will be showing a simplified implementation of this task in C using linked lists as data structures and POSIX threads (pthreads) for thread safety. 

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>  // For inet_pton function to convert IP address from text to binary format

typedef struct packet {
    char protocol[10];  // Assume protocol type as string (e.g., "TCP", "UDP")
    in_addr_t sourceIP;  // Use in_addr_t for IP address storage
    in_addr_t destinationIP;
    size_t payloadSize;  // Size of payload in bytes
    void* payload;
    struct packet *next;
} Packet;

// Global variables
Packet *packets = NULL;  // Start of linked list representing dynamic array
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;  // Mutex to manage access to the packet list

void insertPacket(char* protocol, char* sourceIP, char* destinationIP, void* payload, size_t payloadSize) {
    pthread_mutex_lock(&mutex);  // Lock mutex before accessing shared data

    Packet *newPacket = (Packet*)malloc(sizeof(Packet));
    strncpy(newPacket->protocol, protocol, sizeof(newPacket->protocol) - 1);
    inet_pton(AF_INET, sourceIP, &newPacket->sourceIP);
    inet_pton(AF_INET, destinationIP, &newPacket->destinationIP);
    newPacket->payloadSize = payloadSize;
    newPacket->payload = malloc(payloadSize);  // Allocate memory for payload data
    memcpy(newPacket->payload, payload, payloadSize);  // Copy the actual payload data into our structure

    newPacket->next = packets;  // Insert at beginning of list
    packets = newPacket;

    pthread_mutex_unlock(&mutex);  // Unlock mutex after modifying shared data
}

void deletePacket(char* sourceIP, char* destinationIP) {
    pthread_mutex_lock(&mutex);

    Packet *prev = NULL;
    Packet *curr = packets;
    in_addr_t sIP, dIP;
    inet_pton(AF_INET, sourceIP, &sIP);
    inet_pton(AF_INET, destinationIP, &dIP);

    while (curr != NULL) {
        if (curr->sourceIP == sIP && curr->destinationIP == dIP) {  // If found match, delete it
            if (prev == NULL) {  // If deleting the first packet in list
                packets = curr->next;
            } else {
                prev->next = curr->next;
            }

            free(curr->payload);  // Free memory occupied by payload data
            free(curr);
        }

        prev = curr;
        curr = curr->next;
    }

    pthread_mutex_unlock(&mutex);
}

Packet* getPacket(char* sourceIP, char* destinationIP) {
    in_addr_t sIP, dIP;
    inet_pton(AF_INET, sourceIP, &sIP);
    inet_pton(AF_INET, destinationIP, &dIP);

    pthread_mutex_lock(&mutex);

    Packet *curr = packets;
    while (curr != NULL) {
        if (curr->sourceIP == sIP && curr->destinationIP == dIP) {  // If found match, return it
            pthread_mutex_unlock(&mutex);
            return curr;
        }

        curr = curr->next;
    }

    pthread_mutex_unlock(&mutex);

    return NULL;  // Return NULL if not found
}
```

This is a simplified implementation of handling network packets as custom data structures in C with thread safety. In real-world scenarios, additional considerations such as performance tuning, memory management, error handling, and more will be necessary. Moreover, the code above doesn't handle overlapping source/destination IP addresses or checksum verification. 

Additionally, you may need to add suitable logic to handle packets with overlapping IP addresses by merging them into a single entry, based on your requirement. For checking integrity of packet header before processing, it depends upon the type of checksum you are using for each protocol (like TCP/UDP), in which case you would have to calculate checksum and compare it with received checksum.
']

