void initializeIntArray(int* arr, size_t size, int start, int end) {
    srand((unsigned int)time(NULL));  // Seed the random number generator
    for (size_t i = 0; i < size; i++) {
        bool isDistinct;
        do {
            arr[i] = rand() % (end - start + 1) + start;

            isDistinct = true;
            for (size_t j = 0; j < i; j++) {
                if (arr[j] == arr[i]) {
