['Here is an example C code implementing the described task. This code does not handle data fetching from external sources like databases or files as it's out of scope for this problem. However, handling allocation failures is done using a while loop until there are no more retries left. It also handles memory deallocation in calling function to avoid leaks. 

```c
#include <stdlib.h>
#include <string.h>
#include <time.h>
#define MAX_RETRIES 5

typedef struct {
    long* offset;
    int key;
    int refCount;
} record;

record* allocateRecords(int numOfElements) {
    srand(time(NULL)); // seed the random number generator
    if (numOfElements > 1000 || numOfElements <= 0) {
        printf("Error: Invalid input. Number of elements must be between 1 and 1000.\n");
        return NULL;
    }

    long* offsets = calloc(numOfElements, sizeof(long));
    if (offsets == NULL) {
        printf("Failed to allocate memory for 'offsets' array.\n");
        return NULL;
    }

    int* keys = calloc(numOfElements, sizeof(int));
    if (keys == NULL) {
        free(offsets);
        printf("Failed to allocate memory for 'keys' array.\n");
        return NULL;
    }

    record* records = malloc(numOfElements * sizeof(record));
    if (records == NULL) {
        free(offsets);
        free(keys);
        printf("Failed to allocate memory for 'records' array.\n");
        return NULL;
    }

    int retries = MAX_RETRIES;
    for (int i = 0; i < numOfElements; ++i) {
        records[i].offset = &offsets[i];
        do {
            if(retries == 0){
                // Reduce the size of array and continue with smaller array
                --numOfElements; 
                ++i;
                retries = MAX_RETRIES;
            }
            int key = rand() % 1000; // generate a random key between 0 and 999

            if (keys[key] == 0) { // check if the generated key is unique
                records[i].key = key;
                keys[key] = 1; // mark the key as used
                retries = MAX_RETRIES; // reset retries for next iteration
            } else {
                --retries;  // decrement retries if generated key is not unique
            }
        } while (keys[records[i].key] != 0); // retry until a unique key is generated
    }

    free(keys); // We don't need the keys array anymore
    return records; // Return allocated record structure
}
```
This code assumes that memory allocation will always succeed. In a real-world scenario, more sophisticated error handling and recovery mechanisms should be implemented to ensure robustness of this function. Furthermore, the external integration with data source is out of scope for this problem and not covered in the provided solution. 
