} NetworkPacketHeader;

typedef struct {
    NetworkPacketHeader **packets;
    size_t capacity;
    size_t length;
} DynamicArray;

DynamicArray* initialize(size_t initialSize) {
    // Allocate memory for the array.
    DynamicArray *array = malloc(sizeof(DynamicPacket));
    if (!array) return NULL;

    // Allocate memory for the packets themselves.
    array->packets = calloc(initialSize, sizeof(NetworkPacketHeader*));
    if (!array->packets) {
        free(array);
        return NULL;
    }

    // Set initial values.
    array->capacity = initialSize;
    array->length = 0;

    return array;
}

void insert(DynamicArray *array, NetworkPacketHeader *packet) {
    // If we're out of space, allocate more.
    if (array->length >= array->capacity) {
        size_t newCapacity = array->capacity * 2;
        array->packets = realloc(array->packets, sizeof(NetworkPacketHeader*) * newCapacity);
        // If allocation failed, just return without doing anything.
        if (!array->packets) return;
        array->capacity = newCapacity;
    }

    // Add the packet at the end of the array and increment length.
    array->packets[array->length] = packet;
    array->length++;
}

