    arr.data = (NFAPI_CRC_INDICATION_PDU_T*) malloc(initialSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return arr;
}

void destroy(DynamicArray* arr) {
    pthread_mutex_destroy(&arr->lock);
    free(arr->data);
}

void addElement(DynamicArray* arr, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&arr->lock);
    if (arr->count == arr->capacity) {
        arr->data = reallocarray(arr->data, arr->capacity * 2, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        arr->capacity *= 2;
    }
    arr->data[arr->count++] = element;
    pthread_mutex_unlock(&arr->lock);
}

void removeElementByTag(DynamicArray* arr, int tag) {
    pthread_mutex_lock(&arr->lock);
    for (size_t i = 0; i < arr->count; ++i) {
        if (arr->data[i].RX_UE_INFORMATION_TAG == tag) {
            memmove(arr->data + i, arr->data + i + 1, (arr->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            --arr->count;
            break;
        }
    }
    pthread_mutex_unlock(&arr->lock);
}

