typedef struct event {
    time_t timestamp;
    int type;
    char *uid;
} Event;

// Hash table for storing UIDs
typedef struct hash_table {
    pthread_mutex_t lock;
    Event **events;
    size_t count;
    size_t capacity;
} HashTable;

HashTable* create_hash_table(size_t capacity) {
    HashTable *ht = malloc(sizeof(HashTable));
    ht->count = 0;
    ht->capacity = capacity;
    ht->events = calloc(capacity, sizeof(Event*));
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void insert(HashTable *ht, Event *e) {
    if ((double)(ht->count / ht->capacity) > LOAD_FACTOR) {
        printf("Warning: Hash table is approaching full capacity!\n");
        // Resize and rehash the hash table here
    }

    pthread_mutex_lock(&ht->lock);
    size_t index = hash(e->uid);
    while (ht->events[index] != NULL) {
        if (++index == ht->capacity) {
            index = 0;
        }
    }
    ht->events[index] = e;
    pthread_mutex_unlock(&ht->lock);
}

Event* find(HashTable *ht, char *uid) {
    size_t index = hash(uid);

    pthread_mutex_lock(&ht->lock);
    while (ht->events[index] != NULL) {
        if (strcmp(ht->events[index]->uid, uid) == 0) {
            break;
        }

        if (++index == ht->capacity) {
            index = 0;
        }
    }

    Event *e = ht->events[index];
    pthread_mutex_unlock(&ht->lock);
    return e;
}
```
