["Here's an example implementation in C with POSIX Threads (pthread) for handling concurrency:

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long *offset;
    int key;
    int refCount;
} record;

#define MAX_RECORDS 1024
record records[MAX_RECORDS];
int numRecords = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to generate unique keys
int genKey() {
    int key;
    pthread_mutex_lock(&mutex);
    do {
        key = rand() % 1001; // Key range: 0 - 1000
    } while(isDuplicateKey(key));
    pthread_mutex_unlock(&mutex);
    return key;
}

// Function to check if a key is already in use
int isDuplicateKey(int key) {
    for (int i = 0; i < numRecords; ++i) {
        if (records[i].key == key) {
            return 1; // Duplicate found
        }
    }
    return 0; // No duplicate found
}

// Function to add a record
record* addRecord() {
    pthread_mutex_lock(&mutex);

    if (numRecords >= MAX_RECORDS) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Array is full
    }

    int key = genKey();
    long *offset = malloc(sizeof(long));
    if (offset == NULL) {
        pthread_mutex_unlock(&mutex);
        return NULL; // Allocation failure
    }

    record newRecord;
    newRecord.offset = offset;
    newRecord.key = key;
    newRecord.refCount = 0;

    records[numRecords] = newRecord;
    numRecords++;

    pthread_mutex_unlock(&mutex);
    return &records[numRecords-1]; // Return the newly added record
}

// Function to update a record's reference count (for concurrency)
void updateRefCount(record *r, int delta) {
    pthread_mutex_lock(&mutex);
    r->refCount += delta;
    pthread_mutex_unlock(&mutex);
}
```
This is a basic implementation and can be extended as per the requirements. Also, please note that error handling should be added to this code to handle possible errors like memory allocation failures etc. Also, consider using more efficient data structures for managing unique keys if efficiency is important.
