pthread_mutex_t uniqueSetMutex = PTHREAD_MUTEX_INITIALIZER;
int uniqueSet[UNIQUE_SET_SIZE];  // For checking uniqueness
size_t allocations = 0;  // Total allocated records
size_t allocationLimit = 1024 * 1024;  // Limit to prevent memory exhaustion

void* createRecord(long data, int key) {
    if (key < MIN_KEY || key > MAX_KEY) return NULL;

    pthread_mutex_lock(&uniqueSetMutex);
    if (uniqueSet[key - MIN_KEY]) {  // Check for uniqueness among all records
        pthread_mutex_unlock(&uniqueSetMutex);
        return NULL;
    }
    uniqueSet[key - MIN_KEY] = 1;
    pthread_mutex_unlock(&uniqueSetMutex);

    Record* r = malloc(sizeof(Record));
    if (!r) return NULL;  // Handle memory allocation failure

    long* ldata = malloc(sizeof(long));
    if (!ldata) {
        free(r);
        return NULL;
    }
    *ldata = data;

    r->data = ldata;
    r->key = key;
    r->refcount = 1;  // Initial reference count is 1

    pthread_mutex_lock(&uniqueSetMutex);
    allocations++;
    if (allocations >= allocationLimit) {  // Handle resource constraints
        allocationLimit *= 2;  // Retry with increased limit
        allocations /= 2;  // Halve the number of records for each allocation retry
    }
    pthread_mutex_unlock(&uniqueSetMutex);

    return r;
}

int generateRandomKey() {
    srand(time(NULL));
    int key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;  // Random number between MIN_KEY and MAX_KEY
    pthread_mutex_lock(&uniqueSetMutex);
    while (uniqueSet[key - MIN_KEY]) {  // Ensure uniqueness
        key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
    }
    uniqueSet[key - MIN_KEY] = 1;
    pthread_mutex_unlock(&uniqueSetMutex);
    return key;
}

xmlXPathObjectPtr getFirstElementByName(const char* docname, const char* element) {
    xmlDocPtr doc = xmlParseFile(docname);  // Parse XML document
    if (!doc) return NULL;  // Handle parse failure

    xmlNodeSetPtr nodeset = xmlXPathEvalExpression((xmlChar*)element, doc->children);  // Find elements by name using XPath
    if (!nodeset || !nodeset->nodeTab || nodeset->nodeNr <= 0) {  // Handle no element or multiple elements found
        return NULL;
    }

    return xmlXPathNodeSetCreate(nodeset->nodeTab[0]);  // Return the first matched element
}
```

This function creates a new `record` with the given data and key. It ensures that the key is within the specified range and unique among all records. If allocation fails or if system resources are limited, it retries with increased limit or throws an error message. 

The second function generates random keys ensuring uniqueness. The third function parses an XML document using XPath and returns the first element that matches a given name. It handles parse failure, no element found, and multiple elements found by name.
"]

