#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

typedef struct {
    // fields for the record data structure go here
} Record;

typedef struct DataArrays {
    long* offsetArray;
    int* keyArray;
    Record** records;
    size_t arraySize;
    bool performanceMonitoringEnabled;
    pthread_mutex_t mutex;
} DataArrays;

#define MAX_THRESHOLD 1024 // maximum allowable threshold

// Global variables for the data arrays and their sizes
DataArrays dataArrays;
size_t offsetArraySize, keyArraySize, recordArraySize;

// Allocate memory for the data structures
void allocMemory(size_t size) {
    pthread_mutex_init(&dataArrays.mutex, NULL);

    if (offsetArraySize + size <= MAX_THRESHOLD) {
        offsetArraySize += size;
        long* tmp = realloc(dataArrays.offsetArray, offsetArraySize * sizeof(long));
        if (tmp != NULL) dataArrays.offsetArray = tmp;
    }

    if (keyArraySize + size <= MAX_THRESHOLD) {
        keyArraySize += size;
        int* tmp = realloc(dataArrays.keyArray, keyArraySize * sizeof(int));
        if (tmp != NULL) dataArrays.keyArray = tmp;
    }

    if (recordArraySize + size <= MAX_THRESHOLD) {
        recordArraySize += size;
        Record** tmp = realloc(dataArrays.records, recordArraySize * sizeof(Record*));
        if (tmp != NULL) dataArrays.records = tmp;
    }
}

// Set a value in the record array
void setValueInRecords(size_t index, Record* record) {
    clock_t startTime = clock();

    // Critical section to avoid race conditions
    pthread_mutex_lock(&dataArrays.mutex);

    if (index >= dataArrays.arraySize) allocMemory(MAX_THRESHOLD);

    dataArrays.records[index] = record;

    if (dataArrays.performanceMonitoringEnabled) {
        clock_t endTime = clock();
        double timeTaken = ((double)(endTime - startTime)) / CLOCKS_PER_SEC;
        printf("Setting record value took %f seconds.\n", timeTaken);
    }

    pthread_mutex_unlock(&dataArrays.mutex);
}

// Free allocated memory to prevent memory leaks
void freeMemory() {
    // Ensure all threads have finished accessing the data before freeing it
    pthread_mutex_lock(&dataArrays.mutex);

    for (size_t i = 0; i < recordArraySize; ++i) {
        if (dataArrays.records[i] != NULL) free(dataArrays.records[i]);
    }

    free(dataArrays.offsetArray);
    free(dataArrays.keyArray);
    free(dataArrays.records);

    pthread_mutex_unlock(&dataArrays.mutex);
}
```

