#include <iostream>
#include <random>
#include <fstream>
#include <mutex>
#include <thread>

namespace myNamespace {

class DataStore {
private:
    struct Node {
        int value1;
        int value2;
        Node* next;

        Node(int v1, int v2) : value1(v1), value2(v2), next(nullptr){}
    };

    static std::mt19937 generator_;
    static std::mutex mutex_generator_;
    static constexpr size_t MAX_RECORDS = 10000; // change to a suitable value based on the use case.
    Node* head = nullptr;
    size_t size = 0;
    std::mutex mtx_; // for thread safety 

public:
    DataStore() {
        std::lock_guard<std::mutex> lock(mutex_generator_);
        std::uniform_int_distribution<> distr(0, INT32_MAX);

        Node* prev = nullptr;
        for (size_t i = 0; i < MAX_RECORDS; ++i) {
            if (!head) {
                head = new Node(distr(generator_), distr(generator_));
                prev = head;
            } else {
                Node* newNode = new Node(distr(generator_), distr(generator_));
                prev->next = newNode;
                prev = newNode;
            }
        }
    }

    ~DataStore() {
        while (head) {
            Node* next = head->next;
            delete head;
            head = next;
        }
    }

    void addRecord(int value1, int value2) {
        std::lock_guard<std::mutex> lock(mtx_); // for thread safety 
        if (size == MAX_RECORDS) resize();

        Node* newNode = new Node(value1, value2);
        if (!head) head = newNode;
        else {
            Node* curr = head;
            while (curr->next) curr = curr->next;
            curr->next = newNode;
        }
    }

    void resize() {
        MAX_RECORDS *= 2; // double the maximum records 

        std::lock_guard<std::mutex> lock(mtx_); // for thread safety 
        Node* curr = head;
        while (curr) {
            if (size > MAX_RECORDS) {
                Node* next = curr->next;
                delete curr;
                curr = next;
            } else {
                curr = curr->next;
            }
        }
    }

    void serializeToFile(const std::string& fileName) {
        // Code for serialization goes here. 
    }

    void deserializeFromFile(const std::string& fileName) {
        // Code for de-serialization goes here. Make sure to validate the data before using it.
    }
};
}
