    }
    offsets[size] = off;
    keys[size] = key;
    records[size] = rec;
    size++;
    pthread_mutex_unlock(&lock);
}

void deallocate() {
    clock_t start, end;
    double cpu_time_used;

    start = clock();
    free(offsets);
    free(keys);
    for (size_t i = 0; i < size; ++i) {
        free(records[i]);
    }
    free(records);
    end = clock();

    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
    printf("Time taken for deallocation: %f seconds\n", cpu_time_used);
}
```
The above code handles dynamic memory allocation and deallocation under operational constraints. It uses mutex locks to ensure thread safety during concurrent allocations. A logging mechanism is also provided to monitor the performance of memory operations. 

