int generate_data(long **offsets, size_t *offsetSize, int **keys, size_t *keySize, Record **records, size_t *recordSize, unsigned int seed, const char* filename) {
    srand(seed);  // Seed the random number generator

    FILE *file = fopen(filename, "r");
