        int key = rand() % INT_MAX; // Generate a random key

        while (linearSearch(*keys, *keySize, key) != -1) {
            key = rand() % INT_MAX; // Ensure uniqueness of keys
        }

        *keys = realloc(*keys, (*keySize + 1) * sizeof **keys);
        (*keys)[*keySize] = key;  // Store generated key
        (*keySize)++;
    }

