        int value = rand() % INT_MAX;  // Generate a random integer value

        while (linearSearchRecords(*records, *recordSize, value) != -1) {
            value = rand() % INT_MAX; // Ensure uniqueness of records
        }

        (*records)[i].value = value;  // Store generated record value
    }

    fclose(file);

    return bundleSize;
}

int linearSearch(const int *array, size_t size, int target) {
    for (size_t i = 0; i < size; ++i) {
        if (array[i] == target)
            return i;
    }

    return -1;  // Not found
}

int linearSearchRecords(const Record *records, size_t size, int target) {
    for (size_t i = 0; i < size; ++i) {
        if (records[i].value == target)
            return i;
    }

    return -1;  // Not found
}
