#include <pthread.h>
#include <stdio.h>
#include <unistd.h>

typedef struct NetworkStats {
    int packet_count;
    int byte_count;
    float error_rate;
    time_t timestamp;
    struct NetworkStats *next;
} NetworkStats;

NetworkStats *head = NULL;
pthread_mutex_t lock;

void insert(int packet_count, int byte_count, float error_rate) {
    pthread_mutex_lock(&lock);

    NetworkStats *newNode = (NetworkStats*) malloc(sizeof(NetworkStats));
    newNode->packet_count = packet_count;
    newNode->byte_count = byte_count;
    newNode->error_rate = error_rate;
    newNode->timestamp = time(NULL);

    if (head == NULL) {
        head = newNode;
    } else {
        NetworkStats *lastNode = head;
        while (lastNode->next != NULL) 
            lastNode = lastNode->next;

        lastNode->next = newNode;
    }

    pthread_mutex_unlock(&lock);
