import java.util.concurrent.*;
import javax.xml.bind.DatatypeConverter;

public class HashService {
    private ExecutorService executor = Executors.newFixedThreadPool(10);  // Adjust according to your need
    private ConcurrentHashMap<String, String> hashMap = new ConcurrentHashMap<>();

    public void computeHashes(Collection<String> strings) {
        for (String str : strings) {
            executor.submit(() -> {
                try {
                    MessageDigest md = MessageDigest.getInstance("MD5");
                    md.update(str.getBytes());
                    byte[] digest = md.digest();
                    String myHash = DatatypeConverter.printHexBinary(digest);

