pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int retry_count[MAX_UE] = {0};

NFAPI_CRC_INDICATION_PDU_T *initialize_list(int size) {
    srand(time(NULL));   // initialize random seed

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);

    for (int i = 0; i < size; i++) {
        int rnti, retries = 0;

        do {
            pthread_mutex_lock(&mutex);  // lock mutex before checking and incrementing retry count

            if(retry_count[rnti] >= MAX_RETRIES) {
                printf("Failed to generate a unique RNTI for %d attempts, exiting...\n", retries);
                exit(-1);  // or handle error in a different way as per requirement
            }

            rnti = rand() % MAX_UE;  // generate random number between 0 and MAX_UE - 1
            retry_count[rnti]++;

            pthread_mutex_unlock(&mutex);  // unlock mutex after checking and incrementing retry count

            retries++;
        } while(retry_count[rnti] >= MAX_RETRIES);   // repeat until a unique RNTI is found or max retries are reached

        list[i].RX_UE_INFORMATION_TAG = i;  // set fields of the struct
        list[i].RNTI = rnti;
        list[i].CRC_INDICATION_REL8_TAG = 0;  // initialize as per requirement
    }

    return list;
}
