#include <pthread.h>

typedef struct {
    int timestamp;
    char event_type[20];
    void *payload; // can be of any type, depending on the use case
} TrafficEvent;

TrafficEvent* events = NULL;
size_t capacity = 0;
size_t size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize(size_t initialCapacity) {
    events = (TrafficEvent*) malloc(initialCapacity * sizeof(TrafficEvent));
    if (events == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(-1);
    }
    capacity = initialCapacity;
}

void add_event(TrafficEvent event) {
    pthread_mutex_lock(&mutex);

    if (size >= capacity) { // resize the array when full
        size_t newCapacity = 2 * capacity;
        TrafficEvent* newEvents = realloc(events, newCapacity * sizeof(TrafficEvent));

        if (newEvents == NULL) {
            fprintf(stderr, "Failed to resize memory\n");
            pthread_mutex_unlock(&mutex);
            return;
        }

        capacity = newCapacity;
        events = newEvents;
    }

    events[size++] = event; // add the event at the end of array

    pthread_mutex_unlock(&mutex);
}

void iterate_and_print() {
    for(int i = 0; i < size; ++i) {
        printf("Event: %d, Type: %s\n", events[i].timestamp, events[i].event_type); // assuming payload is not printed
    }
}
