            for (int i = 0; i < capacity; i++) {
                if (hashTable[i].ip && strcmp(hashTable[i].ip, buffer) == 0) {  // IP address already in hash table.
                    hashTable[i].count++;
                    found = 1;
                    break;
                }
            }
            if (!found) {
                if (count == capacity) {
                    capacity *= 2;
                    ip_entry* temp = realloc(hashTable, capacity * sizeof(ip_entry));
                    if (temp == NULL) {
                        fprintf(stderr, "Memory allocation failed\n");
                        exit(EXIT_FAILURE);
                    }
                    hashTable = temp;
                }
                hashTable[count].ip = strdup(buffer);  // Add new IP address to hash table.
                hashTable[count++].count = 1;
            }
        } else {
            fprintf(stderr, "Invalid IP: %s\n", buffer);
        }
    }

    qsort(hashTable, count, sizeof(ip_entry), compareIpEntries);  // Sort hash table.

    return hashTable;
}
```

