// Function to process a single file
IntegerList processFile(FILE *file) {
    IntegerList result = {NULL, 0};
    if (file == NULL) return result; // If file is invalid, return empty list

    int number;
    while (fscanf(file, "%d", &number) == 1) {
        if (number < 0 || number > INT_MAX) continue; // Validate the range of integers

        result.numbers = realloc(result.numbers, sizeof(*result.numbers) * (result.count + 1));
        result.numbers[result.count++] = number;
    }

    return result;
}

// Function to process multiple files
void processFiles(int num_files, FILE* files[]) {
    IntegerList totalResult = {NULL, 0}; // Initialize the total result structure

    for (int i = 0; i < num_files; ++i) {
        IntegerList fileResult = processFile(files[i]); // Process each file individually

        if (fileResult.numbers != NULL && fileResult.count > 0) {
            totalResult.numbers = realloc(totalResult.numbers, sizeof(*totalResult.numbers) * (totalResult.count + fileResult.count));
            memcpy(&totalResult.numbers[totalResult.count], fileResult.numbers, sizeof(*fileResult.numbers) * fileResult.count);
            totalResult.count += fileResult.count;

            free(fileResult.numbers); // Free the memory used by individual result after combining
        }
    }

    // Find the maximum number in all files and print it with total count
    int max_number = INT_MIN;
    for (size_t i = 0; i < totalResult.count; ++i) {
        if (totalResult.numbers[i] > max_number) {
            max_number = totalResult.numbers[i];
        }
    }

    printf("Largest integer found: %d\n", max_number);
    printf("Total valid integers: %zu\n", totalResult.count);

    free(totalResult.numbers); // Free the memory used by total result after use
}
