void allocateMemory(int size, void **pointer) {
    if ((*pointer = malloc(size)) == NULL) {
        fprintf(stderr, "Insufficient memory");
        exit(EXIT_FAILURE);
    }
    memset(*pointer, 0, size);
}

void deallocateMemory(void **pointer) {
    free(*pointer);
    *pointer = NULL; // Prevent dangling pointer
}

Shape* allocateShapesAndInitializeData(int shapeCount, int pointArraySize, int charArraySize) {
    Shape *shapes;
    Point *points;
    char *chars;

    allocateMemory(shapeCount * sizeof(Shape), (void**)&shapes); // Allocate shapes array memory

    // For each shape in the array
    for (int i = 0; i < shapeCount; ++i) {
        switch (shapes[i].type_id) {
            case 1: // Points
                allocateMemory(pointArraySize * sizeof(Point), (void**)&points);
                shapes[i].data = points;
                break;

            case 2: // Chars
                allocateMemory(charArraySize * sizeof(char), (void**)&chars);
                shapes[i].data = chars;
                break;

            default:
                fprintf(stderr, "Invalid type_id");
