```C
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    char *CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node *head = NULL;

void insert(int tag, unsigned int rnti) {
    srand(time(0)); // initialize random seed

    Node *new_node = (Node*) malloc(sizeof(Node));
    if(new_node == NULL) return; // handle memory allocation failure gracefully

    new_node->data.RX_UE_INFORMATION_TAG = tag;
    new_node->data.RNTI = rnti;
    new_node->data.CRC_INDICATION_REL8_TAG = (char *) malloc(10 * sizeof(char)); // assuming CRC is a string of length 10
    if(new_node->data.CRC_INDICATION_REL8_TAG == NULL) return; // handle memory allocation failure gracefully

    for(int i = 0; i < 10; i++) {
        new_node->data.CRC_INDICATION_REL8_TAG[i] = 'a' + (rand() % 26); // generate a random CRC flag
    }

    pthread_mutex_lock(&lock);
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&lock);
}

void delete() {
    pthread_mutex_lock(&lock);

    if(head == NULL) return; // nothing to delete

    Node *temp = head;
    head = head->next;

    free(temp->data.CRC_INDICATION_REL8_TAG);
    free(temp);

    pthread_mutex_unlock(&lock);
}

void destroy() {
    while (head != NULL) delete(); // delete all nodes until list is empty
}
```
