    FAPI_CRC_INDICATION_PDU_T *list;
    size_t count;
    pthread_mutex_t mutex;
};

int createList(struct DataList **data, int timeout) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout; // timeout in seconds

    pthread_mutexattr_t attr;
    if (pthread_mutexattr_init(&attr) != 0) {
        return -1;
    }

    *data = malloc(sizeof(struct DataList));
    if (*data == NULL) {
        return -2;
    }

    (*data)->count = 0;

    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    if (pthread_mutex_init(&(*data)->mutex, &attr) != 0) {
        free(data);
        return -3;
    }

    (*data)->list = calloc(NFAPI_CRC_INDICATION_PDU_T_SIZE, sizeof(FAPI_CRC_INDICATION_PDU_T));
    if ((*data)->list == NULL) {
        pthread_mutex_destroy(&(*data)->mutex);
        free(*data);
        return -4;
    }

    // If lock is not acquired after timeout, return error code
    if (pthread_mutex_timedlock(&(*data)->mutex, &ts) == ETIMEDOUT) {
        pthread_mutex_destroy(&(*data)->mutex);
        free((*data)->list);
        free(*data);
        return -5;
    }

    (*data)->count = NFAPI_CRC_INDICATION_PDU_T_SIZE;
    pthread_mutex_unlock(&(*data)->mutex);

    return 0; // success
}
