```c
#include <stdlib.h>
#include <pthread.h>
#include <sys/time.h>
#include <unistd.h>
#include <limits.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int valid;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct IP_entry{
    char* ip;
    unsigned long timestamp;
    NFAPI_CRC_INDICATION_PDU_T* pdu_list;
    int num_pdus;
    struct IP_entry* next;
}IP_entry;

typedef struct HashTable {
    int size;
    int count;
    IP_entry** table;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_table(int size) {
    HashTable* t = malloc(sizeof(HashTable));
    t->size = size;
    t->count = 0;
    t->table = calloc(size, sizeof(IP_entry*));
    pthread_mutex_init(&t->lock, NULL);
    return t;
}

unsigned long hash(char* str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; 

    return hash;
}

int add_entry(HashTable* t, char* ip, NFAPI_CRC_INDICATION_PDU_T pdu) {
    unsigned long index = hash(ip) % t->size;

    pthread_mutex_lock(&t->lock);
    if (t->table[index] != NULL){
        IP_entry* tmp = t->table[index];

        while(tmp != NULL){
            if (!strcmp(tmp->ip, ip)) {
                // Update the entry with new data
                free(pdu);
                break;
            } else if (tmp->next == NULL) {
                IP_entry* newEntry = malloc(sizeof(IP_entry));
                newEntry->num_pdus = 1;
                newEntry->ip = ip;
                newEntry->pdu_list = calloc(newEntry->num_pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T));
                newEntry->pdu_list[0] = pdu;
                newEntry->timestamp = getCurrentTime();
                newEntry->next = NULL;

                tmp->next = newEntry;
                t->count++;
                break;
            } else {
                tmp = tmp->next;
            }
        }
    } else {
        IP_entry* newEntry = malloc(sizeof(IP_entry));
        newEntry->num_pdus = 1;
        newEntry->ip = ip;
        newEntry->pdu_list = calloc(newEntry->num_pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        newEntry->pdu_list[0] = pdu;
        newEntry->timestamp = getCurrentTime();
        newEntry->next = NULL;

        t->table[index] = newEntry;
        t->count++;
    }

    if(t->count > (int) ((float)t->size * 0.7)){
        rehash_table(t);
    }
    pthread_mutex_unlock(&t->lock);
}

void rehash_table(HashTable* t){
    int newSize = t->size * 2;

    HashTable* newTable = create_table(newSize);

    for(int i=0;i<t->size;++i){
        IP_entry* tmp = t->table[i];

        while(tmp != NULL){
            add_entry(newTable, tmp->ip, tmp->pdu);

            // Free old memory
            free(tmp->ip);
            free(tmp->pdu_list);
            IP_entry* next = tmp->next;
            free(tmp);
            tmp = next;
        }
    }

    pthread_mutex_destroy(&t->lock);
    free(t->table);
    free(t);

    t = newTable;
}

unsigned long getCurrentTime(){
    struct timeval tv;
    gettimeofday(&tv,NULL);
    return (unsigned long)(tv.tv_sec * 1000000 + tv.tv_usec);
}
```
