        // Double the capacity of the array when it is full
        array->data = realloc(array->data, 2 * array->capacity * sizeof(UserSessionProfile*));

        if (!array->data) {
            perror("Failed to allocate memory for data in dynamic array");
            pthread_mutex_unlock(&array->lock);
            exit(EXIT_FAILURE);
        }

        array->capacity *= 2;
    }

    array->data[array->size] = element;
    array->size++;

    pthread_mutex_unlock(&array->lock);
