#include <string.h>
#define MAX_STRING_LENGTH 1024

typedef struct Node {
    char string[MAX_STRING_LENGTH];
    struct Node* next;
} Node;

void insertAfter(Node** head, const char* target, const char* str) {
    pthread_mutex_lock(&lock);

    Node* node = *head;
    while (node && strcmp(node->string, target)) {  // find first occurrence of the target string
        node = node->next;
    }

    if (!node) {  // if not found append to the end
        for (node = *head; node && node->next; node = node->next);

        node->next = malloc(sizeof(Node));
        strcpy(node->next->string, str);
    } else {  // insert after the found string
        Node* newNode = malloc(sizeof(Node));
        strcpy(newNode->string, str);

        newNode->next = node->next;
        node->next = newNode;
    }

    pthread_mutex_unlock(&lock);
}
