['Here is a C code block implementing the described task using pthreads and semaphore for thread safety. 

```c
#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <errno.h>

// Predefined maximum limit
#define MAX_STRUCTS 1024

typedef struct {
    int RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    CRC_INDICATION_REL8_TAG crc_indication;
} FAPI_CRC_INDICATION_PDU_T;

FAPI_CRC_INDICATION_PDU_T* allocateMemory(size_t N) {
    static sem_t semaphore;
    static int initialized = 0;

    if(!initialized){
        sem_init(&semaphore, 0, 1);
        initialized = 1;
    }

    // Ensure that the total number of structures does not exceed a predefined maximum limit.
    if (N > MAX_STRUCTS) {
        errno = E2BIG;
        return NULL;
    }

    sem_wait(&semaphore);  // Lock to prevent race conditions and data corruption
    FAPI_CRC_INDICATION_PDU_T* array = malloc(N * sizeof(FAPI_CRC_INDICATION_PDU_T));

    if (array == NULL) {
        errno = ENOMEM;
        sem_post(&semaphore);  // Release the lock in case of allocation failure
        return NULL;
    }

    for(size_t i = 0; i < N; ++i){
        array[i].crc_indication.CRCFLAG = rand() % 2;  // Randomly set CRCFLAG

        // Ensure that all RNTI values are unique within the array
        int tempRNTI;
        do {
            tempRNTI = rand();
            for(size_t j = 0; j < i; ++j){
                if(array[j].rx_ue_information.RNTI == tempRNTI){
                    tempRNTI = -1;  // Mark as duplicate RNTI
                    break;
                }
            }
        } while (tempRNTI == -1);

        array[i].rx_ue_information.RNTI = tempRNTI;
    }

    sem_post(&semaphore);  // Release the lock after successful allocation and initialization
    return array;
}
```
The function `allocateMemory` is thread-safe, meaning that it properly handles concurrent access without causing data corruption or race conditions. It validates the RNTI values to ensure uniqueness within the array before allocating memory for them. If memory allocation fails due to insufficient resources, errno is set appropriately and NULL is returned as per POSIX standards. The function uses semaphore for thread synchronization to prevent race conditions and data corruption.
