void addFrameToBuffer(LTE_PHY_RX_FRAME* frame) {
    pthread_mutex_lock(&bufferMutex);

    if (bufferSize < MAX_BUFFER_SIZE) {
        for (int i = 0; i < bufferSize; ++i) {
            // Checking if the new frame is already in the buffer 
            if ((frameBuffer[i]->cell_id == frame->cell_id) && (frameBuffer[i]->rf_chain == frame->rf_chain)) {
                free(frame); // Dropping it because it's a duplicate
                pthread_mutex_unlock(&bufferMutex);
                return;
            }
        }

        frameBuffer[bufferSize++] = frame;
    } else {
