// Structure to hold list node data
typedef struct NetworkEventNode {
    NetworkEvent *event;
    struct NetworkEventNode *next;
} NetworkEventNode;

// Dynamic list structure for network events
typedef struct {
    NetworkEventNode *head;
    pthread_mutex_t lock;  // Mutex to ensure thread-safe access
} NetworkEventsList;

void initNetworkEventsList(NetworkEventsList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to add a network event to the list
void addNetworkEvent(NetworkEventsList *list, NetworkEvent *event) {
    // Lock the mutex for thread-safe access
    pthread_mutex_lock(&list->lock);

    NetworkEventNode *node = malloc(sizeof(NetworkEventNode));
    node->event = event;
    node->next = list->head;
    list->head = node;

    // Unlock the mutex to allow other threads to access it
    pthread_mutex_unlock(&list->lock);
}

// Function to save network events to a file, with options for user-specified compression and encryption
void saveNetworkEvents(NetworkEventsList *list, const char *filename, CompressionMethod *compressionMethod, EncryptionMethod *encryptionMethod) {
    // Open the output file using abstracted file handling interface
    FILE *file = openFile(filename);

    // Iterate over list and write network events to file
    NetworkEventNode *node = list->head;
    while (node != NULL) {
        char *serializedData = serializeNetworkEvent(node->event);

        if (compressionMethod != NULL)
            serializedData = compressData(serializedData, compressionMethod);

        if (encryptionMethod != NULL)
            serializedData = encryptData(serializedData, encryptionMethod);

        writeToFile(file, serializedData);

        node = node->next;
    }

    // Close the output file using abstracted file handling interface
    closeFile(file);
}
