#include <iostream>
#include <random>
#include <vector>
#include <algorithm>

class RangeGenerator {
private:
    int min;
    int max;
public:
    RangeGenerator(int min, int max) : min{min}, max{max} {}

    int generate() const {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(min, max);
        return dis(gen);
    }
};

struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
    int CRC_INDICATION_REL8_TAG;
};

void processInputAndGenerateCRCIndications() {
    constexpr int lowerLimit = -(1<<31);
    constexpr int upperLimit = (1<<31) - 1;
    RangeGenerator rangeGen{lowerLimit, upperLimit};

    std::vector<int> dataList;
    std::string input;
    while(std::getline(std::cin, input)) {
        try {
            int num = std::stoi(input);
            if (num >= lowerLimit && num <= upperLimit) 
                dataList.push_back(num);
            else 
                std::cerr << "Warning: Value out of range -> " << input << "\n";
        } catch (std::invalid_argument const& ex) {
            std::cerr << "Warning: Invalid argument error -> " << input << "\n";
        } catch(std::out_of_range const& ex){
            std::cerr << "Warning: Out of range error -> " << input << "\n";
        } catch (...) { 
            std::cerr << "Unknown error.\n";
        }
    }

    if(dataList.empty()) {
        std::cout<<"No valid data found\n";
        return;
    }

    int maxVal = *std::max_element(dataList.begin(), dataList.end());
    std::cout << "Largest integer in array is: " << maxVal << "\n";

    std::vector<NFAPI_CRC_INDICATION_PDU_T> crcIndications;
    for(const auto& num : dataList) {
        NFAPI_CRC_INDICATION_PDU_T indication{num, rangeGen.generate(), 
                                            static_cast<bool>(rangeGen.generate() % 2), 
                                            rangeGen.generate()};
        crcIndications.push_back(indication);
    }
}
```
