["Here is a basic implementation of a C function that meets your requirements using POSIX threads to handle concurrency, a linked list to manage sessions, and a custom timer to trigger cleanup events. 

```C
#include <pthread.h>
#include <time.h>

typedef struct UeSessionState {
    int id;
    // other fields...
} UeSessionState;

typedef struct SessionNode {
    UeSessionState* session;
    time_t lastUpdated;
    struct SessionNode* next;
} SessionNode;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static SessionNode* sessions = NULL;
static int timeout = 60 * 60; // 1 hour in seconds

void addSession(UeSessionState* session) {
    pthread_mutex_lock(&lock);
    SessionNode* newNode = malloc(sizeof(SessionNode));
    newNode->session = session;
    newNode->lastUpdated = time(NULL);
    newNode->next = sessions;
    sessions = newNode;
    pthread_mutex_unlock(&lock);
}

void removeSession(int id) {
    pthread_mutex_lock(&lock);
    SessionNode** ptr = &sessions;
    while (*ptr != NULL) {
        if ((*ptr)->session->id == id) {
            SessionNode* toDelete = *ptr;
            *ptr = (*ptr)->next;
            free(toDelete);
            break;
        }
        ptr = &((*ptr)->next);
    }
    pthread_mutex_unlock(&lock);
}

void updateSession(UeSessionState* session) {
    pthread_mutex_lock(&lock);
    SessionNode* node = sessions;
    while (node != NULL) {
        if (node->session->id == session->id) {
            node->lastUpdated = time(NULL);
            break;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&lock);
}

SessionNode* findInactiveSessions() {
    SessionNode* inactive = NULL;
    SessionNode** prevPtr = &inactive;
    time_t now = time(NULL) - timeout;
    for (SessionNode* node = sessions; node != NULL; node = node->next) {
        if (node->lastUpdated < now) {
            *prevPtr = node;
            prevPtr = &((*prevPtr)->next);
        }
    }
    return inactive;
}

void cleanupInactiveSessions() {
    SessionNode* toDelete = findInactiveSessions();
    while (toDelete != NULL) {
        removeSession(toDelete->session->id);
        free(toDelete->session);
        toDelete = toDelete->next;
    }
}
```

This is a simple solution and it does not cover all aspects of your requirements, but it should serve as a starting point. It uses a linked list for session management and POSIX threads for concurrency control, which are common choices in C when dealing with concurrent data structures like this one. 

