#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    float rsrp;
    float rsrq;
    float sinr;
    int uplinkPowerControlCmd;
} MeasurementReport;

typedef struct {
    pthread_mutex_t mutex;
    size_t maxSize;
    size_t currentSize;
    MeasurementReport* reports;
} ReportManager;

// Initialize the report manager
void initReportManager(ReportManager* rm, size_t initialSize) {
    rm->reports = (MeasurementReport*)malloc(initialSize * sizeof(MeasurementReport));
    rm->maxSize = initialSize;
    rm->currentSize = 0;
    pthread_mutex_init(&rm->mutex, NULL);
}

// Add a new report to the manager
int addReport(ReportManager* rm, MeasurementReport* newReport) {
    int errorCode = 0;

    pthread_mutex_lock(&rm->mutex);

    // Check if we need to resize our array
    if (rm->currentSize == rm->maxSize) {
        MeasurementReport* newArray = realloc(rm->reports, 2 * rm->maxSize * sizeof(MeasurementReport));

        // If the allocation failed, we return an error code and do nothing else
        if (newArray == NULL) {
            errorCode = 1;
        } else {
            rm->reports = newArray;
            rm->maxSize *= 2;
        }
    }

    // If we haven't returned by this point, the array is large enough and we can add our report
    if (errorCode == 0) {
        memcpy(&rm->reports[rm->currentSize], newReport, sizeof(MeasurementReport));
        rm->currentSize++;
    }

    pthread_mutex_unlock(&rm->mutex);

    return errorCode;
}

// Update an existing report in the manager
int updateReport(ReportManager* rm, size_t index, MeasurementReport* newData) {
    int errorCode = 0;

    pthread_mutex_lock(&rm->mutex);

    // Check if the index is valid before trying to access it
    if (index < rm->currentSize) {
        memcpy(&rm->reports[index], newData, sizeof(MeasurementReport));
    } else {
        errorCode = 2;
    }

    pthread_mutex_unlock(&rm->mutex);

    return errorCode;
}

// Retrieve the latest report in the manager
int getLatestReport(ReportManager* rm, MeasurementReport* out) {
    int errorCode = 0;

    pthread_mutex_lock(&rm->mutex);

    // Check if there are any reports before trying to access them
    if (rm->currentSize > 0) {
        memcpy(out, &rm->reports[rm->currentSize - 1], sizeof(MeasurementReport));
    } else {
        errorCode = 3;
    }

    pthread_mutex_unlock(&rm->mutex);

    return errorCode;
}
```
