} NetworkConfig;

int validateMacAddress(const char* mac) {
    int i = 0;
    int sz = strlen(mac);
    if (sz != 17) return 0;

    while (*mac) {
        // Check if each character is valid.
        if (!(isxdigit(*mac) || *mac == ':'))
            return 0;
        ++mac;
        ++i;
    }
    // Ensure that the MAC address has five colons.
    return (i == 17);
}

int validateIPAddress(const char* ip) {
    int i, num, dots = 0;

    for(i=0;ip[i] != '\0';i++){
        if(isdigit(ip[i])) continue;
        else if(ip[i] == '.'){
            dots++;
        }
        else return 0;
    }

    // IP address should contain three dots.
    if (dots != 3)
        return 0;

    return 1;
}

void updateNetworkConfig(NetworkConfig* nc, const char* mac_address, const char* ip_address, const char* subnet_mask, const char* gateway_address) {
    if (validateMacAddress(mac_address) && validateIPAddress(ip_address)) {
        strncpy(nc->mac_address, mac_address, 17);
        strncpy(nc->ip_address, ip_address, 15);
        strncpy(nc->subnet_mask, subnet_mask, 15);
        strncpy(nc->gateway_address, gateway_address, 15);
