    struct Node *next;
} Node;

pthread_mutex_t listLock = PTHREAD_MUTEX_INITIALIZER;
Node *head = NULL;

void add_to_list(int rnti, int crcFlag) {
    Node *newNode = malloc(sizeof(Node));
    newNode->data.rnti = rnti;
    newNode->data.crcFlag = crcFlag;
    newNode->next = NULL;

    pthread_mutex_lock(&listLock);
    if (head == NULL) {
        head = newNode;
    } else {
        Node *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    pthread_mutex_unlock(&listLock);
}

void save_to_file(const char *filename, int binaryOutput) {
    pthread_mutex_lock(&listLock);
    FILE *outputFile = (binaryOutput ? fopen_bin(filename) : fopen_text(filename));

    Node *current = head;
    while (current != NULL) {
        if (binaryOutput) {
