    list->emmInfo = calloc(initialCapacity, sizeof(EMM));
    list->size = 0;
    return list;
}

void addElement(NAS_TRANSPORT_MESSAGE *list, EPS_BEARER_CONTEXT bearerContext, EMM emm) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        list->bearerContexts = realloc(list->bearerContexts, 2 * list->capacity * sizeof(EPS_BEARER_CONTEXT));
        list->emmInfo = realloc(list->emmInfo, 2 * list->capacity * sizeof(EMM));
        list->capacity *= 2;
    }
    list->bearerContexts[list->size] = bearerContext;
    list->emmInfo[list->size] = emm;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}
