```cpp
#ifndef RANDOMNUMBERGENERATOR_H
#define RANDOMNUMBERGENERATOR_H

#include <random>
#include <vector>
#include <algorithm>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int rnti;
    bool crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

class RandomGenerator {
private: 
    std::mt19937 generator_;
    static RandomGenerator* instance_;
    static std::mutex mutex_;

protected:
    RandomGenerator(int seed) : generator_(seed){};
    ~RandomGenerator() {};

public:
    RandomGenerator(RandomGenerator &other) = delete;   // Singleton should not be cloneable.
    void operator=(const RandomGenerator &) = delete;  // Singleton should not be assignable.

    static RandomGenerator *GetInstance(int seed);

    std::vector<NFAPI_CRC_INDICATION_PDU_T> populate_crc_list(size_t populationSize){
        std::uniform_real_distribution<> distribution(0, 65535); // assuming the range of RNTI is from 0 to 65535.
        std::bernoulli_distribution bernoulliDistribution(0.5);   // CRC flag set to true or false with equal probability.

        std::vector<NFAPI_CRC_INDICATION_PDU_T> list;
        for (size_t i = 0; i < populationSize; ++i){
            NFAPI_CRC_INDICATION_PDU_T structInstance = { 
                static_cast<unsigned int>(distribution(generator_)), 
                bernoulliDistribution(generator_) };
            list.push_back(structInstance);
        }

        return list;
    }

    unsigned int find_largest_int(std::vector<unsigned int> &array) {
        if (array.empty())
            throw std::invalid_argument("The input array is empty");

        return *max_element(array.begin(), array.end());
    }
};

RandomGenerator* RandomGenerator::instance_{nullptr};
std::mutex RandomGenerator::mutex_;

// Singleton pattern implementation
RandomGenerator *RandomGenerator::GetInstance(int seed){
    std::lock_guard<std::mutex> lock(mutex_);
    if(instance_ == nullptr){
        instance_ = new RandomGenerator(seed);
    }
    return instance_;
}

#endif // RANDOMNUMBERGENERATOR_H
```

