int initList(LTE_PHY_TX_BUFFER_T** list, size_t* listCapacity, const Config* config) {
    if (config->seedSize <= 0 || config->maxFrequencyOffset < 0 || 
        config->minPowerLevel > config->maxPowerLevel) {
        return -1;  // Invalid input parameters
    }

    int count = 0;
    for (int i = 0; i < *listCapacity; ++i) {
        LTE_PHY_TX_BUFFER_T* buffer = malloc(sizeof(LTE_PHY_TX_BUFFER_T));
        if (!buffer) break;  // Out of memory

        buffer->modulation = 0;  // Assuming a default modulation scheme for now
        buffer->frequency_offset = ((double)rand() / RAND_MAX) * config->maxFrequencyOffset;
        buffer->power_level = config->minPowerLevel + ((float)rand() / (float)(RAND_MAX)) * (config->maxPowerLevel - config->minPowerLevel);

        // Generate a random payload for each seed size
        unsigned char* payload = malloc(config->seedSize * sizeof(unsigned char));
        if (!payload) {
            free(buffer);  // Rollback allocation in case of failure
            break;
