```C
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Forward declaration of functions for error handling and thread safety
void handle_error(char* err);
void lock();
void unlock();

typedef struct node {
    struct NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

Node *head = NULL;
int size = 0;
int M = 100;  // Maximum list size, can be configured.
pthread_mutex_t locker = PTHREAD_MUTEX_INITIALIZER;

void insert(struct NFAPI_CRC_INDICATION_PDU_T data) {
    Node *newNode = (Node*)malloc(sizeof(Node));

    if(!newNode) {
        handle_error("Memory allocation error\n");
    }

    newNode->data = data;
    newNode->next = NULL;

    lock();

    size++;

    // If list is empty or we need to insert at head.
    if(head == NULL || head->data.RNTI > data.RNTI) {
        newNode->next = head;
        head = newNode;

        while(size > M) {  // Evict the least recently added structure
            Node *temp = head;

            while (temp->next->next != NULL)
                temp = temp->next;

            free(temp->next);
            temp->next = NULL;
            size--;
        }

        unlock();
        return;
    }

    Node *current = head;

    // Find the node before which we need to insert new node.
    while(current->next != NULL && current->next->data.RNTI < data.RNTI) {
        current = current->next;
    }

    newNode->next = current->next;
    current->next = newNode;

    unlock();
}

void remove_node(int rnti) {
    lock();

    Node *temp = head, *prev = NULL;

    if (temp != NULL && temp->data.RNTI == rnti) {
        head = temp->next;
        free(temp);
        size--;

        unlock();
        return;
    }

    while (temp != NULL && temp->data.RNTI != rnti) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) {
        handle_error("No such RNTI in list\n");

        unlock();
        return;
    }

    size--;

    prev->next = temp->next;

    free(temp); // Free memory

    unlock();
}

void handle_error(char* err) {
    fprintf(stderr, "Error: %s\n", err);
    exit(EXIT_FAILURE);
}

void lock() {
    if (pthread_mutex_lock(&locker) != 0) {
        handle_error("Mutex Lock Error\n");
    }
}

void unlock() {
    if (pthread_mutex_unlock(&locker) != 0) {
        handle_error("Mutex Unlock Error\n");
    }
}
```

