['The task requires a deep understanding of low-level network programming in C and the ability to work with complex systems such as NICs, sockets, etc. 

Here is an example of how this problem can be solved using POSIX threads and the Linux system programming interface:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <errno.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

typedef struct {
    int sock;
    pthread_t thread;
} SocketData;

void* handleSocket(void *data) {
    // This is the function that each new socket connection will run on its own thread
    SocketData *sd = (SocketData*) data;

    printf("Starting handling socket %d\n", sd->sock);

    /* Read and write from/to this socket */

    printf("Finished handling socket %d\n", sd->sock);

    close(sd->sock);
    free(data);
    return NULL;
}

void initNIC() {
    int listen_sock = socket(AF_INET, SOCK_STREAM, 0);
    if (listen_sock < 0) {
        perror("Failed to create socket");
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(12345); // Listening on port 12345
    inet_pton(AF_INET, "0.0.0.0", &addr.sin_addr); // Accepting connections from all interfaces

    if (bind(listen_sock, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("Failed to bind socket");
        exit(EXIT_FAILURE);
    }

    listen(listen_sock, 1024); // Listen for up to 1024 connections

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t len = sizeof(client_addr);

        int client_sock = accept(listen_sock, (struct sockaddr*)&client_addr, &len);
        if (client_sock < 0) {
            perror("Failed to accept connection");
            continue;
        }

        printf("Accepted new connection\n");

        SocketData *sd = malloc(sizeof(SocketData));
        sd->sock = client_sock;

        if (pthread_create(&sd->thread, NULL, handleSocket, sd) != 0) {
            perror("Failed to create thread");
            free(sd);
            continue;
        }
    }
}

int main() {
    initNIC();
    return 0;
}
```
This is a simplified example and lacks many details such as error handling, buffer management, reallocation etc. Also please note that in real-world scenarios, you should use robust libraries for handling network operations like libevent or Boost.Asio which handle these complexities internally.
