#include <pthread.h>
#include <stdint.h>
#include <time.h>
#include <unordered_map>
#include <vector>
#include <string>

typedef struct Event {
    uint64_t id;  // Assuming unique IDs across all events
    time_t timestamp;
    std::unordered_map<std::string, std::string> metadata;
} Event;

// Global storage for all the events. Note that accessing this concurrently from different threads is not safe without appropriate synchronization.
std::unordered_map<uint64_t, Event*> eventStorage; 
pthread_mutex_t storageMutex = PTHREAD_MUTEX_INITIALIZER;

// Add a new event to the system
void addEvent(Event *e) {
    pthread_mutex_lock(&storageMutex);
    eventStorage[e->id] = e;
    pthread_mutex_unlock(&storageMutex);
}

// Remove an existing event from the system
void removeEvent(uint64_t id) {
    pthread_mutex_lock(&storageMutex);
    if (eventStorage.find(id) != eventStorage.end()) {
        delete eventStorage[id];
        eventStorage.erase(id);
    }
    pthread_mutex_unlock(&storageMutex);
}
```
