int generateUniqueOffsets(long *offsets, size_t maxSize, unsigned seed) {
    srand(seed);
    int count = 0;
    while (count < maxSize) {
        long offset = rand();

        // Check for duplicates
        int isDuplicate = 0;
        for (int i = 0; i < count; ++i) {
            if(offsets[i] == offset){
                isDuplicate = 1;
                break;
            }
        }

        // If not duplicate add it to the array
        if(!isDuplicate) {
            offsets[count++] = offset;
        }
    }
    return count;
}

int generateUniqueKeys(long *offsets, int maxOffsetCount, int *keys, size_t maxSize, unsigned seed) {
    srand(seed);
    int count = 0;
    while (count < maxSize) {
        long key = rand();

        // Check for overlap with offsets and duplicates
        int isDuplicateOrOverlap = 0;
        for (int i = 0; i < count; ++i) {
            if(keys[i] == key || bsearch(&key, offsets, maxOffsetCount, sizeof(*offsets), cmpLong)){
                isDuplicateOrOverlap = 1;
                break;
            }
        }

        // If not overlap or duplicate add it to the array
        if(!isDuplicateOrOverlap) {
            keys[count++] = key;
        } else {
            // Add a secondary identifier for keys that appear multiple times.
            // This is an example, modify according to your needs.
            keys[count-1] *= -1; 
        }
    }
    return count;
}

Record* createRecords(long *offsets, size_t maxOffsetCount, int *keys, size_t maxSize) {
    Record* records = (Record*) malloc(sizeof(Record)*maxSize);
    if(!records){
        return NULL;  // Failed to allocate memory
    }

    srand(time(NULL));  
    for(int i = 0; i < maxSize; ++i) {
        records[i].offset = offsets[i % maxOffsetCount];
        records[i].key = keys[i % maxSize];
        records[i].randomValue = ((double) rand() / (RAND_MAX));  // Random floating-point number in the range [0,1]
    }

    return records;
}

void* generatePipeline(unsigned seed, long *offsets, size_t maxOffsetCount, int *keys, size_t maxKeyCount) {
    pthread_mutex_lock(&lock);

    // Generate unique offsets
    if(!generateUniqueOffsets(offsets, maxOffsetCount, seed)) {
        pthread_mutex_unlock(&lock);
        return NULL;  // Failed to generate unique offsets
    }

    // Generate unique keys with secondary identifiers for overlaps
    if(!generateUniqueKeys(offsets, maxOffsetCount, keys, maxKeyCount, seed)) {
        pthread_mutex_unlock(&lock);
        return NULL;  // Failed to generate unique keys
    }

    Record* records = createRecords(offsets, maxOffsetCount, keys, maxKeyCount);
    if(!records){
        pthread_mutex_unlock(&lock);
        return NULL;  // Failed to allocate memory for records
    }

    pthread_mutex_unlock(&lock);
    return records;  
}
