void addElement(DynamicArray* arr, NFAPI_RRC_C newElement) {
    pthread_mutex_lock(&arr->mutex);

    if (arr->length == arr->capacity) {
        // If we're out of space, double the capacity.
        arr->data = realloc(arr->data, 2 * arr->capacity * sizeof(NFAPI_RRC_C));
    }

    arr->data[arr->length] = newElement;
    arr->length++;

    pthread_mutex_unlock(&arr->mutex);
}

// Function to remove an element.
void removeElement(DynamicArray* arr, size_t index) {
    pthread_mutex_lock(&arr->mutex);

    // Shift all elements after the removed one down by one position.
    for (size_t i = index; i < arr->length - 1; ++i) {
        arr->data[i] = arr->data[i + 1];
    }

    // Decrease length and check if we need to shrink the array.
    arr->length--;
    if (arr->capacity > 4 * arr->length) {
        arr->data = realloc(arr->data, 0.5 * arr->capacity * sizeof(NFAPI_RRC_C));
