// Assume NRCellConfig, Band, Bandwidth, and NRCellMeasurement are defined elsewhere

typedef struct DynamicArray {
    int size;  // Current number of elements in the array
    int capacity; // Maximum number of elements that can be stored
    void** data; // An array of pointers to NRCellConfig structures
    pthread_mutex_t mutex; // For thread safety
} DynamicArray;

// Initialize a dynamic array
DynamicArray* init_dynamic_array() {
    DynamicArray* da = malloc(sizeof(DynamicArray));
    if (da == NULL) {
        return NULL;
    }

    da->size = 0;
    da->capacity = 10; // Start with an arbitrary initial capacity
    da->data = malloc(sizeof(void*) * da->capacity);
    if (da->data == NULL) {
        free(da);
        return NULL;
    }

    pthread_mutex_init(&da->mutex, NULL); // Initialize mutex for thread safety
    return da;
}

// Add a new element to the dynamic array
void add_element(DynamicArray* da, void* element) {
    if (pthread_mutex_lock(&da->mutex) != 0) {
        return;
    }

    // If array is full, double its size and copy elements to new array
    if (da->size == da->capacity) {
        da->capacity *= 2;
        void** new_data = realloc(da->data, sizeof(void*) * da->capacity);

        // If allocation failed, unlock mutex and return without adding element
        if (new_data == NULL) {
            pthread_mutex_unlock(&da->mutex);
            return;
        }

        da->data = new_data;
    }

    // Add the new element to the array and update size
    da->data[da->size] = element;
    da->size++;

    pthread_mutex_unlock(&da->mutex);
}
```

