typedef struct NFAPI_CRC_INDICATION_PDU {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

int findMax(int *arr, int n) {
    int i, max = arr[0];

    for (i = 1; i < n; i++)
        if (arr[i] > max)
            max = arr[i];

    return max;
}

void createStruct(int *tags, int *rntis, NFAPI_CRC_INDICATION_PDU_T **structs, int n) {
    for (int i = 0; i < n; i++) {
        (*structs)[i].RX_UE_INFORMATION_TAG = tags[i];
        (*structs)[i].RNTI = rntis[i];
    }
}

void readIntegers(int **arr, int *n) {
    *n = 0; 
    int capacity = 10; 
    *arr = malloc(capacity * sizeof(int)); 

    if (*arr == NULL) {
        fprintf(stderr, "Failed to allocate memory.\n");
        exit(EXIT_FAILURE);
    }

    int num; 
    while (scanf("%d", &num) == 1) {
        if (*n >= capacity) {
            capacity *= 2; 
            *arr = realloc(*arr, capacity * sizeof(int)); 

            if (*arr == NULL) {
                fprintf(stderr, "Failed to re-allocate memory.\n");
                exit(EXIT_FAILURE);
            }
        }

        (*arr)[(*n)++] = num;
    }

    *arr = realloc(*arr, *n * sizeof(int)); 
}

void main() {
    int *numbers; 
    int count; 

    readIntegers(&numbers, &count);

    if (count == 0) {
        fprintf(stderr, "No integers provided.\n");
        exit(EXIT_FAILURE);
    }

    printf("Max integer: %d\n", findMax(numbers, count));
}
