["Below is the C code for the requested function. The `DataPacket` structure includes fields for a timestamp, unique packet identifier, and payload length. A dynamic array of these structures will be managed by this function, with methods to add new packets, remove existing ones by identifier, and retrieve the total number of packets.

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct DataPacket {
    int timestamp;
    char *unique_id; // assuming unique ID is a string for simplicity
    size_t payload_length;
} DataPacket;

typedef struct PacketArray {
    DataPacket **packets;
    size_t size;
    pthread_mutex_t lock;
} PacketArray;

void packet_array_init(PacketArray *arr) {
    arr->size = 0;
    arr->packets = NULL;
    pthread_mutex_init(&arr->lock, NULL);
}

int packet_array_add(PacketArray *arr, DataPacket *packet) {
    if (!packet) return -1; // handle null pointers

    pthread_mutex_lock(&arr->lock); // ensure thread safety during access

    arr->size++;
    arr->packets = realloc(arr->packets, sizeof(*arr->packets) * arr->size);

    if (!arr->packets) {
        pthread_mutex_unlock(&arr->lock); // unlock mutex before returning in case of allocation failure
        return -1;
    }

    arr->packets[arr->size - 1] = packet;

    pthread_mutex_unlock(&arr->lock);
    return 0;
}

int packet_array_remove(PacketArray *arr, char *id) {
    if (!id || !arr) return -1; // handle null pointers

    pthread_mutex_lock(&arr->lock); // ensure thread safety during access

    for (size_t i = 0; i < arr->size; ++i) {
        if (!strcmp(arr->packets[i]->unique_id, id)) {
            free(arr->packets[i]); // free memory of removed packet
            memmove(&arr->packets[i], &arr->packets[i + 1], (arr->size - i - 1) * sizeof(*arr->packets));
            arr->size--;
            pthread_mutex_unlock(&arr->lock);
            return 0; // return early after successfully removing packet
        }
    }

    pthread_mutex_unlock(&arr->lock);
    return -1; // packet not found
}

size_t packet_array_count(PacketArray *arr) {
    if (!arr) return 0; // handle null pointers

    pthread_mutex_lock(&arr->lock); // ensure thread safety during access
    size_t count = arr->size;
    pthread_mutex_unlock(&arr->lock);

    return count;
}

void packet_array_destroy(PacketArray *arr) {
    if (!arr || !arr->packets) return; // handle null pointers

    for (size_t i = 0; i < arr->size; ++i) free(arr->packets[i]);

    free(arr->packets);
    pthread_mutex_destroy(&arr->lock);
}
```

