#include <openssl/md5.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    int packetID;
    size_t payloadLength;
} DataPacket;

typedef struct {
    pthread_mutex_t lock;
    DataPacket** packets;
    size_t numPackets;
} PacketManager;

void handleError(char* msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

DataPacket* newPacket(time_t timestamp, int packetID, size_t payloadLength) {
    DataPacket* packet = (DataPacket*)malloc(sizeof(DataPacket));
    if (packet == NULL) handleError("Failed to allocate memory for packet");
    packet->timestamp = timestamp;
    packet->packetID = packetID;
    packet->payloadLength = payloadLength;
    return packet;
}

PacketManager* newPacketManager() {
    PacketManager* manager = (PacketManager*)malloc(sizeof(PacketManager));
    if (manager == NULL) handleError("Failed to allocate memory for packet manager");

    if (pthread_mutex_init(&manager->lock, NULL) != 0) {
        free(manager);
        handleError("Failed to initialize mutex lock");
    }

    manager->packets = NULL;
    manager->numPackets = 0;
    return manager;
}

void addPacket(PacketManager* manager, DataPacket* packet) {
    pthread_mutex_lock(&manager->lock);
    manager->packets = realloc(manager->packets, sizeof(DataPacket*) * (manager->numPackets + 1));
    if (manager->packets == NULL) handleError("Failed to allocate memory for packets array");
    manager->packets[manager->numPackets++] = packet;
    pthread_mutex_unlock(&manager->lock);
}

void removePacket(PacketManager* manager, int packetID) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->numPackets; ++i) {
        if (manager->packets[i]->packetID == packetID) {
            free(manager->packets[i]);
            manager->packets[i] = manager->packets[--manager->numPackets];
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

size_t getNumPackets(const PacketManager* manager) {
    return manager->numPackets;
}

char* md5Hash(const char *str) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)str, strlen(str), (unsigned char*)&digest);    
    char *mdString = malloc(33);
    if (mdString == NULL) handleError("Failed to allocate memory for MD5 string");
    for(int i = 0; i < 16; ++i) {
        sprintf(&mdString[i*2], "%02x", (unsigned int)digest[i]);
    }
    return mdString;
}
```

