#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int packet_id;
    long timestamp;
    char source_ip[16];  // Assuming IP addresses have max length of 15 characters + null terminator
} PacketHeader;

typedef struct {
    char *payload;
} Payload;

typedef struct {
    PacketHeader header;
    Payload payload;
} DataPacket;

typedef struct {
    pthread_mutex_t mutex;
    DataPacket **packets;  // Dynamic array of packets
    int size;              // Current number of elements in the array
    int capacity;          // Maximum number of elements that can be stored in the current allocated memory
} PacketArray;

void init_array(PacketArray *a, int initialSize) {
    a->packets = (DataPacket **)malloc(initialSize * sizeof(DataPacket *));
    a->size = 0;
    a->capacity = initialSize;
    pthread_mutex_init(&a->mutex, NULL);
}

void insert_array(PacketArray *a, DataPacket *element) {
    pthread_mutex_lock(&a->mutex);

    if (a->size == a->capacity) {
        // Reallocate memory with double the current capacity
        a->capacity *= 2;
        a->packets = realloc(a->packets, a->capacity * sizeof(DataPacket *));
    }

    a->packets[a->size++] = element;

    pthread_mutex_unlock(&a->mutex);
}

void free_array(PacketArray *a) {
    for (int i = 0; i < a->size; ++i) {
        free(a->packets[i]->payload.payload);
        free(a->packets[i]);
    }

    free(a->packets);
}
