    ARQParameters arqParams; // Automatic Repeat Request parameters
    HARQSettings harqSettings; // Hybrid Automatic Repeat Request settings
    ChannelSpecificParams channelParams; // Channel-specific parameters
};

// Dynamic array of MAC configurations
struct DynamicArray {
    pthread_mutex_t mutex; // Mutex for thread safety
    struct MACConfiguration* configs; // Array of MAC configurations
    int size; // Total number of configurations
    int capacity; // Current maximum capacity of the array
};

// Initialization function
void initDynamicArray(struct DynamicArray* arr, int initialCapacity) {
    pthread_mutex_init(&arr->mutex, NULL);
    arr->size = 0;
    arr->capacity = initialCapacity;
    arr->configs = malloc(initialCapacity * sizeof(struct MACConfiguration));
}

// Adding a configuration to the array
void addConfig(struct DynamicArray* arr, struct MACConfiguration config) {
    pthread_mutex_lock(&arr->mutex);

    // Check for conflicts and remove configurations with lower priority if necessary
    int existingIndex = getConfigById(arr, config.id);
    if (existingIndex != -1 && arr->configs[existingIndex].priority < config.priority) {
        removeConfigAtIndex(arr, existingIndex);
    }

    // Resize the array if necessary
    if (arr->size >= arr->capacity) {
        resizeArray(arr, arr->capacity * 2);
    }

    // Add the new configuration
    arr->configs[arr->size] = config;
    arr->size++;

    pthread_mutex_unlock(&arr->mutex);
}

// Retrieving a specific configuration by its unique identifier
struct MACConfiguration getConfigById(struct DynamicArray* arr, int id) {
    struct MACConfiguration result = {.id = -1}; // Default return value if no matching configuration is found

    pthread_mutex_lock(&arr->mutex);

    for (int i = 0; i < arr->size; ++i) {
        if (arr->configs[i].id == id) {
            result = arr->configs[i];
            break;
        }
    }

    pthread_mutex_unlock(&arr->mutex);

    return result;
}

// Removing a configuration at a specific index
void removeConfigAtIndex(struct DynamicArray* arr, int index) {
    // Shift configurations above the removed one down to fill the gap
    for (int i = index; i < arr->size - 1; ++i) {
        arr->configs[i] = arr->configs[i + 1];
    }

    arr->size--;
}
