    pthread_mutex_lock(&array->lock);

    if (index < array->count) {
        free(array->macs[index]);
        array->macs[index] = new_config;
    }

    pthread_mutex_unlock(&array->lock);
}

MACConfig* get_config(MACArray* array, int index) {
    MACConfig* config = NULL;

    pthread_mutex_lock(&array->lock);

    if (index < array->count) {
        config = array->macs[index];
    }

    pthread_mutex_unlock(&array->lock);

    return config;
}
``` 

