    u_char ip[INET6_ADDRSTRLEN]; // maximum size for IPv4/IPv6 address
    time_t timestamp;
} DNSCache;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; 
DNSCache dns_cache[MAX_CACHE]; // define a cache to store recent DNS resolutions
int dns_cache_index = 0; // index for round-robin DNS cache replacement

ErrorCode resolveHostname(char* hostname, u_char* ip) {
    struct addrinfo hints, *infoptr;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // either IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    int result = getaddrinfo(hostname, NULL, &hints, &infoptr);
    if (result != 0) { return DNS_LOOKUP_FAILED; }

    // Assuming we only want the first IP address returned
    struct sockaddr *addr = infoptr->ai_addr;
    getnameinfo(addr, infoptr->ai_addrlen, ip, sizeof(ip), NULL, 0, NI_NUMERICHOST);

    freeaddrinfo(infoptr); // important to avoid memory leakage
    return NO_ERROR;
}

void addToCache(char* hostname, u_char* ip) {
    pthread_mutex_lock(&mutex);
    strncpy(dns_cache[dns_cache_index].hostname, hostname, sizeof(dns_cache[dns_cache_index].hostname));
    memcpy(dns_cache[dns_cache_index].ip, ip, INET6_ADDRSTRLEN);
    dns_cache[dns_cache_index].timestamp = time(NULL); // update timestamp

    dns_cache_index++;
    if (dns_cache_index == MAX_CACHE) { dns_cache_index = 0; } // wrap around cache

    pthread_mutex_unlock(&mutex);
}

u_char* getFromCache(char* hostname) {
    for (int i=0; i<MAX_CACHE; i++) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0 && 
            time(NULL)-dns_cache[i].timestamp < 60*5 ) { // Cache for 5 minutes

            return dns_cache[i].ip;
        }
    }

    return NULL; // not found in cache or expired
}

DataPacket createPacket(char* hostname, char* payload) {
    u_char ip[INET6_ADDRSTRLEN];
    ErrorCode error = NO_ERROR;

    pthread_mutex_lock(&mutex);

    u_char* cacheIP = getFromCache(hostname); // check if IP is in the cache
    if (cacheIP != NULL) { memcpy(ip, cacheIP, INET6_ADDRSTRLEN); }
    else { error = resolveHostname(hostname, ip); addToCache(hostname, ip); } // resolve DNS and update cache

    pthread_mutex_unlock(&mutex);

    if (error != NO_ERROR) { /* Handle the error */ }

    DataPacket packet;
    packet.header.packet_id = rand(); // for example, use a random ID
    packet.header.timestamp = time(NULL);
    strncpy(packet.header.source_ip, ip, INET6_ADDRSTRLEN);

    packet.payload.length = strlen(payload);
    packet.payload.data = malloc(packet.payload.length + 1); // allocate memory for payload data
    strcpy(packet.payload.data, payload);

    return packet;
}
