    pthread_mutex_lock(&log->lock);

    if (log->size == log->capacity) { // If the array is full, we need to resize it
        size_t newCap = log->capacity * 2;
        LogEntry* temp = realloc(log->entries, sizeof(LogEntry)*newCap);
        if (temp == NULL) {
            pthread_mutex_unlock(&log->lock);
            return -1; // Error
        }

        log->capacity = newCap;
        log->entries = temp;
    }

    log->entries[log->size++] = entry; // Add the entry to the array

    pthread_mutex_unlock(&log->lock);
    return 0; // Success
}

LogEntry* getEntriesBySessionID(EventLog *log, char sessionID[]) {
    LogEntry *result = NULL;
    size_t resultSize = 0;

    pthread_mutex_lock(&log->lock);

    for (size_t i = 0; i < log->size; ++i) {
        if (strcmp(log->entries[i].sessionID, sessionID) == 0) {
            result = realloc(result, sizeof(LogEntry)*(++resultSize));

            // Add the entry to the results array
            if (result != NULL) { 
                result[resultSize-1] = log->entries[i];
            } else {
                --resultSize;
            }
        }
    }

    pthread_mutex_unlock(&log->lock);
    return result;
}
