#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#define CACHE_SIZE 100 // fixed size cache for demonstration purposes

// Define structures
typedef struct {
    char* key;
    long offset;
    double timestamp;
} Entry;

typedef struct {
    Entry* entry;
    int statusFlag;
} Report;

typedef struct {
    pthread_mutex_t lock; // mutex for synchronization 
    Entry** entries; // array of pointers to Entry
    Report** reports; // array of pointers to Reports
    int* lruTable; // to implement LRU eviction strategy
} Cache;

Cache cache;
pthread_t threads[2];

// Function declarations
Entry* createEntry(char* key, long offset);
Report* createReport(Entry* entry, int statusFlag);
void initializeCache();
int getVictimIndex();
void addToCache(Entry* entry);
void updateLRU(int index);
double getCurrentTime();
void printMemoryUsage();
void freeEntries();
void* threadFunction(void *arg);

// Main function to start threads and manage cache
int main() {
    initializeCache();

    for (int i = 0; i < 2; ++i) 
        pthread_create(&threads[i], NULL, &threadFunction, NULL);

    for (int i = 0; i < 2; ++i) 
        pthread_join(threads[i], NULL);

    freeEntries(); // free all allocated memory before exiting
    return 0;
}

// Helper functions
Entry* createEntry(char* key, long offset){
    Entry* entry = malloc(sizeof(Entry));
    if(!entry) {
        exit(-1); // Handle error case
    }
    entry->key = strdup(key);
    entry->offset = offset;
    entry->timestamp = getCurrentTime();

    return entry;
}

Report* createReport(Entry* entry, int statusFlag) {
    Report* report = malloc(sizeof(Report));
    if(!report) {
        exit(-1); // Handle error case
    }
    report->entry = entry;
    report->statusFlag = statusFlag;

    return report;
}

void initializeCache() {
    cache.entries = malloc(sizeof(Entry*) * CACHE_SIZE);
    cache.reports = malloc(sizeof(Report*) * CACHE_SIZE);
    cache.lruTable = malloc(sizeof(int) * CACHE_SIZE);

    for (int i = 0; i < CACHE_SIZE; ++i){
        cache.entries[i] = NULL;
        cache.reports[i] = NULL;
        cache.lruTable[i] = 0;
    }
}

int getVictimIndex() { // Implement LRU eviction strategy
    int lru = 0;

    for (int i = 1; i < CACHE_SIZE; ++i) 
        if(cache.lruTable[i] > cache.lruTable[lru]) 
            lru = i;

    return lru;
}

void addToCache(Entry* entry){
    pthread_mutex_lock(&cache.lock); // Thread-safe operation with mutex locking

    int index = getVictimIndex();
    if (cache.entries[index]) 
        free(cache.entries[index]);

    cache.entries[index] = entry;
    ++cache.lruTable[index]; // Increase LRU score for newly added Entry

    pthread_mutex_unlock(&cache.lock);
}

void updateLRU(int index) {
    pthread_mutex_lock(&cache.lock);
    ++cache.lruTable[index]; // Increase LRU score for accessed Entry
    pthread_mutex_unlock(&cache.lock);
}

double getCurrentTime() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    return (double) ts.tv_sec + ((double) ts.tv_nsec / 1e9);
}

void printMemoryUsage(){
    // Implement system-specific logging for memory usage and cache hit/miss statistics
    printf("Memory Usage: %ld bytes\n", getCurrentRSS());
}

void freeEntries() {
    pthread_mutex_lock(&cache.lock);

    for (int i = 0; i < CACHE_SIZE; ++i) 
        if(cache.entries[i]) {
            free(cache.entries[i]->key);
            free(cache.entries[i]);
        }

    pthread_mutex_unlock(&cache.lock);
}

void* threadFunction(void *arg) {
    Entry* entry = createEntry("testKey", 123456789L);
    addToCache(entry);
    Report* report = createReport(entry, 0);

    pthread_exit(NULL); // Exit thread
}
