```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    unsigned int sequence_number;
} FRAME_TRACKING;

typedef struct {
    // fields for RX_FRAME and CRC_INDICATION
    int rnti;
    bool crc_flag;

    // other necessary fields...
    FRAME_TRACKING tracking;
} NFAPI_RX_FRAME_INFO;

typedef struct {
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    NFAPI_RX_FRAME_INFO* array;
} Array;

Array *initializeAndPopulate(size_t initialCapacity) {
    Array* array = (Array*)malloc(sizeof(Array));

    if (!array) return NULL;

    array->capacity = initialCapacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    array->array = (NFAPI_RX_FRAME_INFO*)malloc(initialCapacity * sizeof(NFAPI_RX_FRAME_INFO));

    if (!array->array) {
        free(array);
        return NULL;
    }

    return array;
}

void addElement(Array* array, NFAPI_RX_FRAME_INFO element) {
    pthread_mutex_lock(&array->mutex);

    if (array->size >= array->capacity) {
        // Double the capacity and reallocate memory. This avoids performance bottlenecks due to frequent resizing.
        size_t newCapacity = array->capacity * 2;

        NFAPI_RX_FRAME_INFO* newArray = (NFAPI_RX_FRAME_INFO*)realloc(array->array, newCapacity * sizeof(NFAPI_RX_FRAME_INFO));

        if (!newArray) {
            pthread_mutex_unlock(&array->mutex);
            return;
        }

        array->capacity = newCapacity;
        array->array = newArray;
    }

    // Add the element to the array.
    array->array[array->size] = element;
    array->size++;

    pthread_mutex_unlock(&array->mutex);
}
```
This code creates a dynamic array structure with thread safety. The 'addElement' function resizes the array when necessary, avoiding frequent reallocations which can cause performance bottlenecks. 

Please note that this is just an example and actual implementation could be more complex depending on exact requirements such as real-time constraints, memory efficiency etc. Also, please ensure to handle error cases properly in a production environment. For instance, we have not handled the case where realloc fails. It's always better to return some specific error code or throw an exception. 

The mutex ensures thread safety but it can cause performance bottlenecks for concurrent reads as mutexes are heavy-weight lock mechanisms and should be used sparingly due to contention which reduces the parallelism available to other threads. Therefore, proper balance is required based on the specific use case. 

