    MAC_CONTEXT_T* array = malloc(N * sizeof(MAC_CONTEXT_T));
    if (array == NULL) {
        logError("Memory allocation failed");
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        // Validate header and buffer size
        MAC_HEADER header = { .header_field = 1 }; // Replace with actual values
        TRANSMIT_BUFFER transmitBuffer = { 
            .bufferSize = M, 
            .data = malloc(M) 
        };

        if (transmitBuffer.data == NULL || transmitBuffer.bufferSize > MAX_TRANSMISSION_SIZE) {
            logError("Memory allocation failed for buffer or exceeded max size");
            // De-allocation in case of error to avoid memory leak
            free(array); 
            pthread_mutex_unlock(&lock); // Unlock before returning
            return NULL;
        }

        array[i].header = header;
        array[i].transmitBuffer = transmitBuffer;

        logInfo("Created MAC_CONTEXT_T structure");
    }

    pthread_mutex_unlock(&lock); // Unlock after successful allocation
    return array;
}
```
This code assumes that the logging library is already properly initialized and includes a "logger.h" header file where `logInfo` and `logError` are defined. The function `createContextArray()` dynamically allocates an array of `MAC_CONTEXT_T` structures, each containing a `MAC_HEADER`, `PHY_STATS`, and `TRANSMIT_BUFFER` with size `M`. Error checking is implemented to ensure the memory allocation is successful before attempting to use each element in the array.

