void insert(NFAPI_CRC_INDICATION_PDU_T* element, int priority) {
    Node *newNode = malloc(sizeof(Node));
    newNode->value = ATOMIC_VAR_INIT(element);
    newNode->next = NULL;

    pthread_mutex_lock(&lock);
    if (getListSize() < maxSize) {
        if (!head || priority > getListSize()) { // If list is empty or higher priority than current size, insert at the head.
            newNode->next = head;
            head = newNode;
        } else { // Insert at a specific position based on priority.
            Node *curr = head, *prev = NULL;
            while (priority-- && curr) {
                prev = curr;
                curr = curr->next;
            }

            newNode->next = curr;
            if (prev)
                prev->next = newNode;
            else
                head = newNode;
        }
    } else { // If list is full, delete the last node and insert at the correct position.
        Node *curr = head, *prev = NULL;

        while (curr) {
            prev = curr;
            curr = curr->next;
        }

        freeNode(prev->value); // Free memory of overwritten node.
        prev->value = ATOMIC_VAR_INIT(element);
    }

    pthread_mutex_unlock(&lock);
}

void updateMaxSize(size_t newSize) {
    maxSize = newSize;
}

size_t getListSize() {
    size_t size = 0;
    Node* curr = head;

    while (curr) {
        size++;
        curr = curr->next;
    }

    return size;
}

void dumpList() {
    pthread_mutex_lock(&lock);
    Node *curr = head;

    while (curr) {
        printf("Element: %p\n", atomic_load(curr->value)); // Print or handle the element as needed.
        curr = curr->next;
    }

    pthread_mutex_unlock(&lock);
}

void freeNode(_Atomic(NFAPI_CRC_INDICATION_PDU_T*) node) {
    while (atomic_flag_test_and_set(&node->flag)); // Spin until lock is acquired.
    atomic_store(node, NULL); // Release memory for the node's content.
