["Here is a simplified version of such function in C with focus on memory management and thread safety. For full implementation you should also consider handling dynamic scaling, resource allocation/deallocation, integration complexities, performance tuning, error handling, unit tests etc. which are beyond the scope of this platform.

```c
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

#define MAXIMUM_PDU_COUNT 500

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Implement the structure members here...
} NFAPI_CRC_INDICATION_PDU;

// Memory pool for PDUs.
NFAPI_CRC_INDICATION_PDU* pduPool[MAXIMUM_PDU_COUNT]; 
atomic_int nextAvailable = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate memory for a new PDU.
NFAPI_CRC_INDICATION_PDU* createPDUBuffer() {
    pthread_mutex_lock(&lock);
    if (nextAvailable >= MAXIMUM_PDU_COUNT) {
        pthread_mutex_unlock(&lock);
        return NULL;  // No available buffer.
    }

    NFAPI_CRC_INDICATION_PDU* buffer = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));

    if (buffer == NULL) {
        pthread_mutex_unlock(&lock);
        return NULL;  // Memory allocation failed.
    }

    int index = atomic_fetch_add(&nextAvailable, 1);
    pduPool[index] = buffer;

    pthread_mutex_unlock(&lock);
    return buffer;
}

// Function to release memory of a PDU.
void freePDUBuffer(NFAPI_CRC_INDICATION_PDU* pdu) {
    // Find the index in the pool and release the memory.
    for (int i = 0; i < MAXIMUM_PDU_COUNT; i++) {
        if (pduPool[i] == pdu) {
            free(pdu);
            pduPool[i] = NULL;  // Mark as freed.
            atomic_fetch_sub(&nextAvailable, 1);
            break;
        }
    }
}
```
