        // Check for allocation failure
        if (array->packets == NULL) exit(1);

        array->capacity *= 2;
    }

    array->packets[currentSize] = packet;
    atomic_fetch_add(&array->size, 1);

    pthread_mutex_unlock(&array->lock);
}

