int add(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&lock);

    Node* new_node = (Node*) malloc(sizeof(Node));
    if(new_node == NULL) {
        pthread_mutex_unlock(&lock); 
        return -1; // error
    }

    new_node->data = data;
    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&lock);
    return 0; // success
}

int delete(time_t timestamp) {
    pthread_mutex_lock(&lock);

    Node* temp = head;
    Node* prev = NULL;

    while (temp != NULL && temp->data.timestamp != timestamp) {
        prev = temp;
        temp = temp->next;
    }

    if(temp == NULL) {
        pthread_mutex_unlock(&lock); 
        return -1; // not found
    }

    if (prev != NULL)
        prev->next = temp->next;

    if(head == temp)
        head = head->next;

    free(temp);
    pthread_mutex_unlock(&lock); 
    return 0; // success
}
