void update(long offset, int new_key) {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < size; ++i) {
        if (records[i].offset == offset) {
            records[i].key = new_key;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void* allocate(size_t n, int min, int max) {
    if (capacity < size + n) {
        capacity = size > 0 ? 2 * capacity : 1;
        records = realloc(records, capacity * sizeof(*records));
        if (!records) {
