        size_t newCapacity = array->capacity * 2;
        DataPacket** newArray = malloc(newCapacity * sizeof(DataPacket*));
        memcpy(newArray, array->packets, array->length * sizeof(DataPacket*));
        free(array->packets);
        array->packets = newArray;
        array->capacity = newCapacity;
