char* computeMD5(const char *str) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)str, strlen(str), digest);    

    char *mdString = malloc(33); // 1 byte for each 2 hex digits and one for null terminator
    for(int i = 0; i < 16; ++i) {
