    }

    return mdString;
}

NFAPI_CRC_INDICATION_PDU_T generateNfareIndications(int N, unsigned int *RNTI){
    srand((unsigned int)time(NULL)); // Use current time as seed for random generator
    NFAPI_CRC_INDICATION_PDU_T indications[N];

    for (int i = 0; i < N; ++i) {
        indications[i].RX_UE_INFORMATION_TAG = rand() % 1024; // Random number between 0 and 1023
