        // Use the first bit of mdString as CRCFLAG
        unsigned int hexValue; 
        sscanf(&mdString[0], "%x", &hexValue);
        indications[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (hexValue >> 31) & 1U;
    }

    return indications;
}
