// Define structures for metrics, config and aggregated data
typedef struct Metrics {
    time_t timestamp;
    int counter;
    int threshold;
} Metrics;

typedef struct Config {
    char* source; // URL or local file path of the external data source
    double performanceLimit;
} Config;

typedef struct AggregatedData {
    unsigned char hash[SHA256_DIGEST_LENGTH];  // Hash for identification
    Metrics metrics;
    int movingAvgCounter;  // The aggregation of the moving average of counters
} AggregatedData;

// Node structure for linked list
typedef struct Node {
    AggregatedData* data;
    struct Node* next;
} Node;

Node* processAndAggregateMetrics(int N, Metrics* metrics, Config* config) {
    // Create a new node and allocate memory dynamically (check if allocation was successful)
    Node* head = malloc(sizeof(Node));
    if (!head) exit(-1);  // Memory allocation failed. Exit with error code -1

    // Calculate moving average of counters
    int sum = 0;
    for (int i = 0; i < N && metrics[i].counter != NULL; ++i) {
        if (metrics[i].counter >= metrics[i].threshold) {  // Filter based on thresholds
            sum += metrics[i].counter;
        }
    }

    int movingAvgCounter = sum / N;

    // Create a string of timestamp and counter values to generate the hash
    char* concat = malloc(20);  // Allocate memory for concatenation (consider padding space)
    sprintf(concat, "%ld%d", metrics->timestamp, movingAvgCounter);

    // Generate SHA-256 hash of the string using OpenSSL library
    unsigned char sha_hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)concat, strlen(concat), sha_hash);

    // Allocate memory for AggregatedData and copy the computed values into it
    head->data = malloc(sizeof(AggregatedData));
    memcpy(head->data->hash, sha_hash, SHA256_DIGEST_LENGTH);  // Copy hash

    head->data->metrics = *metrics;  // Directly copy the metrics data structure
    head->data->movingAvgCounter = movingAvgCounter;  // Copy the computed average counter

    // Clean up memory and return the created node
    free(concat);
    return head;
}
```

