#include <chrono>
#include <mutex>
#include <unordered_map>
#include <vector>

class UserSession {
public:
    std::string sessionID;
    std::chrono::time_point<std::chrono::system_clock> lastActivityTime;
    std::string userIP;
    int sessionDuration; // in seconds
};

class SessionManager {
private:
    std::mutex mutex_;
    std::unordered_map<std::string, UserSession*> activeSessions;

public:
    void addSession(UserSession *session) {
        std::lock_guard<std::mutex> lock(mutex_);
        activeSessions[session->userIP] = session;
    }

    std::vector<UserSession*> getActiveSessionsByIP(const std::string& ip) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::vector<UserSession*> result;
        for (auto &it : activeSessions) {
            if (it.second->userIP == ip) {
                result.push_back(it.second);
            }
        }
        return result;
    }

    void cleanupInactiveSessions() {
        std::lock_guard<std::mutex> lock(mutex_);

        // Consider a session as inactive if lastActivityTime is more than 30 minutes ago
        auto currentTime = std::chrono::system_clock::now();
        for (auto it = activeSessions.begin(); it != activeSessions.end();) {
            if ((currentTime - it->second->lastActivityTime).count() > 1800 ) {
                delete it->second; // Assuming UserSession is allocated with new
                it = activeSessions.erase(it);
            } else {
                ++it;
            }
        }
    }

    void removeSession(const std::string& sessionID) {
        std::lock_guard<std::mutex> lock(mutex_);

        for (auto it = activeSessions.begin(); it != activeSessions.end(); ++it) {
            if (it->second->sessionID == sessionID) {
                delete it->second; // Assuming UserSession is allocated with new
                activeSessions.erase(it);
                break;
            }
        }
    }
};
``` 
