// Initialize the context with a dynamic resizing mechanism.
void init_context(MAC_CONTEXT* ctx) {
    ctx->capacity = MAX_FRAMES / 2; // start with half of max frames
    ctx->num_frames = 0;
    ctx->frames = malloc(ctx->capacity * sizeof(MAC_FRAME*));
    pthread_mutex_init(&ctx->lock, NULL);
}

// Add a frame to the context with thread safety. 
void add_frame(MAC_CONTEXT* ctx, char* prefix) {
    // Acquire the lock before modifying data
    pthread_mutex_lock(&ctx->lock);

    if (ctx->num_frames >= ctx->capacity) {
        // Resize context when limit is reached
        ctx->capacity *= 2;
        ctx->frames = realloc(ctx->frames, ctx->capacity * sizeof(MAC_FRAME*));
    }

    // Create a new frame with sequence number and ue_id
    MAC_FRAME* newFrame = malloc(sizeof(MAC_FRAME));
