["Here's an example of a C code block that implements such functionality. Please note this is just a basic implementation and should be adapted as needed for production-level codebases.

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    long offset;
    int key;
    int value;
} Record;

typedef struct DynamicArray {
    pthread_mutex_t lock; // used for thread safety
    Record** records; // array of pointers to Record structures
    size_t size; // number of elements in the array
    size_t capacity; // maximum capacity of the array
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* da = malloc(sizeof(DynamicArray));
    if (da == NULL) return NULL;

    pthread_mutex_init(&da->lock, NULL); // initialize mutex lock for thread safety
    da->records = NULL;
    da->size = 0;
    da->capacity = 0;
    return da;
}

void add_record(DynamicArray* da, Record* record) {
    if (da == NULL || record == NULL) return;

    pthread_mutex_lock(&da->lock); // lock for thread safety
    if (da->size >= da->capacity) {
        size_t newCapacity = da->capacity == 0 ? 1 : da->capacity * 2; // double the capacity
        Record** tempRecords = realloc(da->records, newCapacity * sizeof(Record*));

        if (tempRecords == NULL) { // handle allocation failure gracefully
            pthread_mutex_unlock(&da->lock);
            return;
        }

        da->capacity = newCapacity;
        da->records = tempRecords;
    }

    da->records[da->size++] = record; // add the record to the array
    pthread_mutex_unlock(&da->lock); // unlock after operation is complete
}

void destroy_dynamic_array(DynamicArray* da) {
    if (da == NULL) return;

    for (size_t i = 0; i < da->size; ++i) free(da->records[i]); // free each individual record
    free(da->records); // then the array itself
    pthread_mutex_destroy(&da->lock); // destroy mutex lock for thread safety

    da = NULL;
}
```
This code implements a dynamic array of `record` structures, each containing a long offset value and an int key/value pair. The array is dynamically resized as necessary to accommodate new records. The addition operation is protected by a mutex lock for thread safety. 

