['```C
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int value;
} record;

// Dynamic Array Structure
typedef struct {
    record* array;
    size_t used;
    size_t size;
} Array;

void initArray(Array* a, size_t initialSize) {
    a->array = (record*)malloc(initialSize * sizeof(record));
    if(a->array == NULL) exit(-1); // Memory allocation failure

    a->used = 0;
    a->size = initialSize;
}

void insertArray(Array* a, record element) {
    if (a->used == a->size) {
        a->size *= 2; // Increase size by double when full
        a->array = (record*)realloc(a->array, a->size * sizeof(record));

        if(a->array == NULL) exit(-1); // Memory allocation failure
    }

    a->array[a->used++] = element; // Add record to array and increment the counter
}

void freeArray(Array* a) {
    free(a->array);  // Free memory allocated for records
    a->array = NULL;
    a->used = a->size = 0;
}

// Garbage Collection function to remove old or unused records
int garbageCollector(Array* a, size_t threshold) {
    if (a->used < threshold) return 0; // No need for GC

    size_t freedRecords = a->used - threshold;
    printf("Freed %zu records\n", freedRecords);

    a->size = a->used = threshold; // Set the new usage to the threshold
    a->array = (record*)realloc(a->array, a->size * sizeof(record));

    if(a->array == NULL) exit(-1); // Memory allocation failure

    return freedRecords;
}
```
This code provides the basic structures and functionalities to manage a dynamic array of records with memory safety checks, garbage collection feature (which removes excess data while maintaining existing ones), and log the number of freed records. Please note that this is just a basic implementation and might need more sophisticated error handling or optimization based on specific requirements.
