```c
#include <pthread.h>
#include <time.h>
#include <stdlib.h>
#include <string.h>

typedef struct Connection {
    pthread_mutex_t lock;
    char* connectionId;
    time_t lastActivity;
    int isActive;
    struct Connection* next;
} Connection;

Connection* head = NULL;
pthread_mutex_t globalLock = PTHREAD_MUTEX_INITIALIZER;

void addConnection(char* connectionId) {
    pthread_mutex_lock(&globalLock);

    Connection* newConnection = (Connection*) malloc(sizeof(Connection));
    if (newConnection == NULL) {
        // handle error
        return;
    }

    newConnection->connectionId = strdup(connectionId);
    time(&(newConnection->lastActivity));
    newConnection->isActive = 1;

    pthread_mutex_init(&(newConnection->lock), NULL);
    newConnection->next = head;
    head = newConnection;

    pthread_mutex_unlock(&globalLock);
}

void updateActivity(char* connectionId) {
    Connection* current = head;
    while (current != NULL) {
        if (strcmp(current->connectionId, connectionId) == 0) {
            pthread_mutex_lock(&(current->lock));

            time(&(current->lastActivity));
            current->isActive = 1;

            pthread_mutex_unlock(&(current->lock));
            return;
        }
        current = current->next;
    }
}
```
This is a very simplified version of what your code could look like. It doesn't include garbage collection, integration with external services, configuration parameters or resource limits as those would require more complicated code and design considerations to handle them properly. Also note that this basic implementation assumes that connection IDs are unique across all connections, which might not be the case depending on your use-case.
