```java
import java.security.MessageDigest;
import java.util.Map;
import java.util.concurrent.*;

public class DataProcessorService {
    private ExecutorService executor = Executors.newFixedThreadPool(10); // adjust as needed
    private Map<NFAPI_CRC_INDICATION_PDU_T, String> pduHashes = 
        new ConcurrentHashMap<>();

    public void process(NFAPI_CRC_INDICATION_PDU_T pdu) {
        executor.submit(() -> {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(pdu.toString().getBytes());

            String hash = new BigInteger(1, digest).toString(16);
            pduHashes.put(pdu, hash);
        });
    }

    public void shutdown() {
        executor.shutdown();

        try {
            if (!executor.awaitTermination(500, TimeUnit.MILLISECONDS)) {
                executor.shutdownNow();
            } 
        } catch (InterruptedException ex) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }
}
```

