FrameArray* init_frame_array(size_t max_frames) {
    FrameArray* array = malloc(sizeof(FrameArray));
    if (array == NULL) return NULL;

    pthread_mutex_init(&array->lock, NULL);
    array->count = 0;
    array->frames = calloc(max_frames, sizeof(NFAPI_RX_FRAME_INFO));
    if (array->frames == NULL) {
        free(array);
        return NULL;
    }

    return array;
}

void populate_frame_array(FrameArray* array, uint32_t seed, size_t count) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < count && i + array->count < MAX_FRAMES; ++i) {
        array->frames[array->count].rnti = rand_r(&seed);  // Pseudo random generation
        array->frames[array->count].CRC_INDICATION = (rand_r(&seed) % 2 == 0)? 1 : 0;  // Random CRC Indication
        ++array->count;
    }
    pthread_mutex_unlock(&array->lock);
}

void free_frame_array(FrameArray* array) {
    if (array != NULL) {
        pthread_mutex_destroy(&array->lock);
        free(array->frames);
        free(array);
    }
}
