long* offsets;
int* keys;
Record** records;

Node* createLinkedList(int numNodes, int minVal, int maxVal) {
    srand(time(0));  // Seed the random number generator

    Node* head = NULL;
    Node* tail = NULL;

    for (int i = 0; i < numNodes; i++) {
        int val = minVal + rand() % ((maxVal + 1) - minVal);  // Generate a random value in the specified range

        Node* newNode = malloc(sizeof(Node));
        if (newNode == NULL) {
            printf("Error: Out of memory\n");
            exit(EXIT_FAILURE);
        }

        newNode->value = val;
        newNode->next  = NULL;

        if (head == NULL) {
            head = newNode;
            tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }
    }

    return head;
}

void initializeDataStructures(long numOffsets, int numKeys, Record* numRecords, 
                             int minVal, int maxVal, int linkedListSize) {
    pthread_mutex_lock(&lock); // Lock the mutex before accessing shared data

    offsets = malloc(numOffsets * sizeof(long));
    keys    = malloc(numKeys    * sizeof(int));
    records = malloc(numRecords * sizeof(Record*));

    if (offsets == NULL || keys == NULL || records == NULL) {
        printf("Error: Out of memory\n");
        exit(EXIT_FAILURE);
