void addDataRecord(int value, float decimalValue, char* stringContent) {
    pthread_mutex_lock(&mutex);

    if (recordCount >= recordCapacity) {
        // Double capacity each time we need to resize
        recordCapacity = recordCapacity ? recordCapacity * 2 : 1;
        dataRecords = realloc(dataRecords, sizeof(DataRecord) * recordCapacity);
    }

    DataRecord* newRecord = &dataRecords[recordCount++];
    newRecord->value = value;
    newRecord->decimalValue = decimalValue;
    newRecord->stringContent = stringContent;  // Assuming string is properly copied and managed

    pthread_mutex_unlock(&mutex);
}
