["```c
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <limits.h>
#include <errno.h>

typedef struct Record {
    long offset;
    int key;
} Record;

int initializeRecords(size_t count, size_t seed, long minOffset, long maxOffset, unsigned long uniqueIdentifier, 
                      Record **recordsPtr, int **keysPtr, long **offsetsPtr) {

    if (count <= 0 || maxOffset - minOffset + 1 < count) {
        return EINVAL;
    }

    // Allocate memory for records array.
    *recordsPtr = malloc(sizeof(Record *) * count);
    if (*recordsPtr == NULL) {
        return ENOMEM;
    }

    // Allocate memory for keys and offsets arrays.
    *keysPtr = calloc(count, sizeof(int));
    *offsetsPtr = malloc(sizeof(long) * count);
    if (*keysPtr == NULL || *offsetsPtr == NULL) {
        free(*recordsPtr);
        free(*keysPtr);
        free(*offsetsPtr);
        return ENOMEM;
    }

    srand((unsigned int)seed);  // Seed the random number generator.

    for (size_t i = 0; i < count; ++i) {
        (*recordsPtr)[i] = malloc(sizeof(Record));

        if ((*recordsPtr)[i] == NULL) {
            // Free previously allocated memory and return error.
            for (--i; i > 0; --i) {
                free((*recordsPtr)[i]);
            }
            free(*recordsPtr);
            free(*keysPtr);
            free(*offsetsPtr);
            return ENOMEM;
        }

        // Generate unique key using hash of timestamp and unique identifier.
        (*keysPtr)[i] = (int)(((time(NULL) * 31 + uniqueIdentifier) % LONG_MAX) % INT_MAX);
        ++uniqueIdentifier;

        // Initialize offset to a random value within given range.
        (*offsetsPtr)[i] = rand() % (maxOffset - minOffset + 1) + minOffset;
    }

    return 0;
}
```
Please note that the above function doesn't handle collision in keys array due to the usage of a simple hash. For production quality code, consider using a more robust collision resistant algorithm or data structure. Also, please note that this implementation uses `rand` for generating random offsets which is not considered cryptographically secure and might be slow on some systems. If you need stronger randomness, you should use a cryptographic random number generator instead.
