['Here is a basic C code sample for the requested task:
```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int type;
    unsigned char* data;
} FrameMetadata;

typedef struct {
    FrameMetadata metadata;
    void *packetData;
} FrameBuffer;

static pthread_mutex_t framebufferMutex = PTHREAD_MUTEX_INITIALIZER;

unsigned long calculateChecksum(void* packet, size_t len) {
    unsigned char *ucPacket = (unsigned char *)packet;
    unsigned long checksum = 0xFFFFFFFFL;

    while (len > 3) {
        unsigned long tlen;
        memcpy(&tlen, ucPacket, sizeof(tlen));
        checksum ^= tlen;
        len -= 4;
        ucPacket += 4;
    }

    if (len > 0) {
        unsigned long tlen = 0;
        memcpy(&tlen, ucPacket, len);
        checksum ^= tlen;
    }

    return checksum;
}

size_t initFrameBuffer(FrameBuffer** frameBuffers, size_t count) {
    if (frameBuffers == NULL || count == 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return 0;
    }

    *frameBuffers = calloc(count, sizeof(FrameBuffer));
    if (*frameBuffers == NULL) {
        perror("Memory allocation failed");
        return 0;
    }

    size_t successfulFrames = 0;
    for (size_t i = 0; i < count; ++i) {
        FrameBuffer* frameBuffer = &(*frameBuffers)[i];

        // Initialize metadata and packetData based on type
        switch(frameBuffer->metadata.type) {
            case 1:
                frameBuffer->packetData = calloc(50, sizeof(char));
                break;
            case 2:
                frameBuffer->packetData = calloc(100, sizeof(char));
                break;
            default:
                fprintf(stderr, "Unknown type %d\n", frameBuffer->metadata.type);
                continue;
        }

        if (frameBuffer->packetData == NULL) {
            perror("Memory allocation failed");
            continue;
        }

        // Validate packet data integrity by checksum
        unsigned long calculatedChecksum = calculateChecksum(frameBuffer->packetData, 100); // Assume size is 100 bytes
        if (calculatedChecksum != frameBuffer->metadata.data) {
            fprintf(stderr, "Packet data integrity check failed\n");
            free(frameBuffer->packetData);
            continue;
        }

        pthread_mutex_lock(&framebufferMutex);
        successfulFrames++;
        pthread_mutex_unlock(&framebufferMutex);
    }

    return successfulFrames;
}
```
