['Here's how you might implement such a system in C using POSIX Threads (pthread) for thread safety, and a linked list to manage the packets efficiently:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct packet {
    int sfn; // System Frame Number
    int sequence_number;
} PACKET;

typedef struct node {
    PACKET *packet;
    struct node* next;
} NODE;

// Macro for the maximum number of packets to store simultaneously.
#define MAX_PACKETS 1024

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static int num_packets = 0; // Current number of packets in the list.
static NODE* head = NULL; // Start of the linked list.

void addPacket(PACKET *packet) {
    pthread_mutex_lock(&lock);

    if (num_packets >= MAX_PACKETS) {
        printf("Maximum number of packets reached, discarding packet with sfn %d.\n", packet->sfn);
        free(packet);
        pthread_mutex_unlock(&lock);
        return;
    }

    NODE* newNode = malloc(sizeof(NODE));
    newNode->packet = packet;
    newNode->next = head;
    head = newNode;
    num_packets++;

    pthread_mutex_unlock(&lock);
}

PACKET* createPacket(int sfn, int sequence_number) {
    PACKET *newPacket = malloc(sizeof(PACKET));
    if (newPacket != NULL) {
        newPacket->sfn = sfn;
        newPacket->sequence_number = sequence_number;
    } else {
        printf("Failed to allocate memory for packet with sfn %d.\n", sfn);
