int customLCG(void) {
    static unsigned long next = 1;
    const int MODULUS = 2147483647;  // The 'm' parameter of LCG formula
    const int MULTIPLIER = 48271;     // The 'a' parameter of LCG formula
    const int INCREMENT = 0;          // The 'c' parameter of LCG formula

    next = (MULTIPLIER * next + INCREMENT) % MODULUS;
    return next;
}
