    }

    fprintf(logfile, "%s: RX_BUFFER_ID=%d, RX_BUFFER_SIZE=%d, RX_BUFFER_TIMESTAMP=%lld\n", 
            op, info.RX_BUFFER_ID, info.RX_BUFFER_SIZE, info.RX_BUFFER_TIMESTAMP);
    fclose(logfile);
}
```
