public void manageConnections(ServerSocketChannel server) throws IOException {
    Selector selector = Selector.open();
    server.register(selector, SelectionKey.OP_ACCEPT);  // Register the server channel for accepting new connections

    while (true) {
        int numKeys = selector.selectNow();  // Wait until at least one connection is ready to be handled

        if (numKeys == 0) continue;  // If no connections are ready, go back to waiting for them

        Set<SelectionKey> keys = selector.selectedKeys();  // Get the keys corresponding to ready connections

        for (Iterator<SelectionKey> i = keys.iterator(); i.hasNext(); ) {
            SelectionKey key = i.next();

            if (key.isAcceptable()) {
                // Handle a new connection
                ServerSocketChannel server = (ServerSocketChannel) key.channel();
                SocketChannel client = server.accept();
                client.configureBlocking(false);  // Configure non-blocking mode for the client channel
                client.register(selector, SelectionKey.OP_READ | SelectionKey.OP_WRITE);  // Register the client channel for read and write operations
            } else if (key.isReadable()) {
                // Handle a read operation on an existing connection
                ...
            } else if (key.isWritable()) {
                // Handle a write operation on an existing connection
                ...
            }

            i.remove();  // Remove the key from the set to prevent it from being processed again
        }
    }
}
