public class HashService {
    private ExecutorService executor = Executors.newFixedThreadPool(10);  // Concurrency level based on system resources
    private ConcurrentHashMap<String, String> hashMap = new ConcurrentHashMap<>();  // Thread-safe map

    public void processPDU(NFAPI_CRC_INDICATION_PDU_T pdu) {
