#include <stdlib.h>
#include <pthread.h>

typedef struct node {
    int key;
    long *offsets; // Array of offsets
    struct node *left, *right;
} Node;

Node *new_node(int key) {
    Node *temp = (Node *)malloc(sizeof(Node));
    temp->key = key;
    temp->offsets = NULL; // Initialize offset array later
    temp->left = temp->right = NULL;
    return temp;
}

typedef struct sparse_matrix {
    Node *root;
    pthread_mutex_t lock;
} SparseMatrix;

SparseMatrix *new_sparse_matrix() {
    SparseMatrix *sm = (SparseMatrix *)malloc(sizeof(SparseMatrix));
    sm->root = NULL;
    pthread_mutex_init(&sm->lock, NULL);
    return sm;
}

void insert(SparseMatrix *sm, int key) {
    Node *node = new_node(key);

    if (sm->root == NULL) {
        sm->root = node;
        return;
    }

    pthread_mutex_lock(&sm->lock);  // Lock for thread safety while inserting

    Node *temp = NULL;
    Node *prev = NULL;
    Node *curr = sm->root;

    while (curr != NULL) {
        prev = curr;
        if (key < curr->key) {
            curr = curr->left;
        } else if(key > curr->key){
            curr = curr->right;
        } else {  // Key already exists, update the node here.
            return;
        }
    }

    if (key < prev->key) {
        prev->left = node;
    } else {
        prev->right = node;
    }

    pthread_mutex_unlock(&sm->lock);  // Release lock
}

void destroy(SparseMatrix *sm, Node* root) {
    if (root != NULL) {
        destroy(sm, root->left);
        destroy(sm, root->right);

        free(root->offsets);  // Free dynamic offset array
        pthread_mutex_destroy(&sm->lock);  // Destroy the mutex lock
        free(root);  // Finally, free the node itself
    }
}
```

