    pthread_mutex_lock(&mutex); // Locking for thread safety

    if (total - used < count) {
        fprintf(stderr, "Buffer overflow detected\n");
        errno = ENOMEM; // Set error number to ENOMEM in case of buffer overflow
        pthread_mutex_unlock(&mutex); 
        return;
