   public void processStructures(List<NFAPI_CRC_INDICATION_PDU_T> structures) {
      List<List<NFAPI_CRC_INDICATION_PDU_T>> batches = splitIntoBatches(structures, BATCH_SIZE);

      for (List<NFAPI_CRC_INDICATION_PDU_T> batch : batches) {
