    int DeviceID;
} NetworkDeviceConfig;

int lexicographical_compare(const void *a, const void *b) {
    return strcmp(((NetworkDeviceConfig *)a)->MAC, ((NetworkDeviceConfig *)b)->MAC);
}

void processNetworkDevices() {
    FILE* file = fopen("network_config.txt", "r"); // Replace with the actual path to your configuration file
    if (file == NULL) {
        printf("Unable to open the configuration file.\n");
        return;
    }

    NetworkDeviceConfig *devices = malloc(10000 * sizeof(NetworkDeviceConfig)); // Allocating memory for 10,000 devices
    if (devices == NULL) {
        printf("Unable to allocate memory.\n");
        return;
    }

    int deviceCount = 0;

    while (!feof(file)) {
        NetworkDeviceConfig *device = &devices[deviceCount];

        if (fscanf(file, "%s %s %s", device->IP, device->SubnetMask, device->MAC) != 3) {
            printf("Invalid entry found in the configuration file. Skipping...\n");
            continue; // If an invalid entry is encountered, skip it
        }

        for (int i = 0; i < 5; ++i) {
            if (fscanf(file, "%s", device->Interfaces[i]) != 1) {
                printf("Invalid interface description found. Skipping...\n");
                continue; // If an invalid interface is encountered, skip it
            }
        }

        if (fscanf(file, "%d", &device->DeviceID) != 1) {
            printf("Invalid device ID found. Skipping...\n");
            continue; // If an invalid device ID is encountered, skip it
        }
        ++deviceCount;
    }

    qsort(devices, deviceCount, sizeof(NetworkDeviceConfig), lexicographical_compare);

    printf("The IP address with the highest MAC address value is: %s\n", devices[deviceCount - 1].IP); // Printing the IP of the device with the highest MAC

    free(devices); // Freeing allocated memory after use
    fclose(file); // Closing the file after reading
}
