// Function to delete event from BST
bst_node* deleteNode(bst_node* root, time_t timestamp) {
    if (root == NULL)  return root;

    // If the timestamp to be deleted is smaller than the root's timestamp
    // then it lies in left subtree
    if (difftime(timestamp, root->event.timestamp) < 0)
        root->left = deleteNode(root->left, timestamp);

    // If the timestamp to be deleted is greater than the root's timestamp
