#define MAX_MESSAGES 1000
#define TIMESTAMP_RANGE 60*60 // one hour in seconds
#define LOG_LEVELS 5

typedef struct {
    time_t timestamp;
    char logLevel[32];
    int messageID;
} LogStructure;

LogStructure *logs = NULL;
int activeConfigurations = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
time_t startTime, endTime;
FILE* logFile;

char* getRandomLogLevel() {
    char *levels[LOG_LEVELS] = {"DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"};
    return levels[rand() % LOG_LEVELS];
}

time_t getTimestamp(time_t start, int range) {
    return (start + rand() / ((RAND_MAX + 1u) / range));
}

int checkDuplicate(LogStructure *logs, time_t timestamp, char* logLevel, int messageID) {
    for (int i = 0; i < activeConfigurations; ++i) {
        if (logs[i].timestamp == timestamp && 
            strcmp(logs[i].logLevel, logLevel) == 0 && 
            logs[i].messageID == messageID) {
            return 1;
        }
    }
    return 0;
}

LogStructure* initMemoryForLogging() {
    srand(time(NULL));

    time_t start = time(NULL);
    LogStructure *logs = (LogStructure *) malloc(MAX_MESSAGES * sizeof(LogStructure));
    activeConfigurations = 0;

    for (int i = 0; i < MAX_MESSAGES && activeConfigurations < MAX_MESSAGES; ++i) {
        time_t timestamp = getTimestamp(start, TIMESTAMP_RANGE);
        char *logLevel = getRandomLogLevel();

        if (!checkDuplicate(logs, timestamp, logLevel, i)) {
            logs[activeConfigurations].timestamp = timestamp;
            strcpy(logs[activeConfigurations].logLevel, logLevel);
            logs[activeConfigurations].messageID = i;
            ++activeConfigurations;
        }
    }

    return logs;
}

void cleanupMemory() {
    free(logs);
    logs = NULL;

    endTime = time(NULL);
    double seconds_taken = difftime(endTime, startTime);

    if (logFile == NULL) logFile = fopen("performance.log", "a");
    fprintf(logFile, "Memory cleanup took %f milliseconds.\n", seconds_taken * 1000);
}

int loadConfigurationsFromFile(char* filePath) {
    FILE *file = fopen(filePath, "r");

    if (file == NULL) return -1;

    logs = initMemoryForLogging();
    startTime = time(NULL);
    activeConfigurations = 0; // Reset the counter in case of file load failure.

    while (!feof(file)) {
        LogStructure log;

        if (fscanf(file, "%ld %s %d", &log.timestamp, log.logLevel, &log.messageID) != 3) 
            break;

        if (!checkDuplicate(logs, log.timestamp, log.logLevel, log.messageID)) {
            logs[activeConfigurations].timestamp = log.timestamp;
            strcpy(logs[activeConfigurations].logLevel, log.logLevel);
            logs[activeConfigurations].messageID = log.messageID;
            ++activeConfigurations;
        }
    }

    fclose(file);

    return activeConfigurations;
}
```
