['This task requires knowledge in C programming, multi-threading, memory management, serialization, and error handling. Here is an example of how you could start implementing this function:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_PAYLOAD 4*1024 // Max payload size is 4KB
#define MAX_SIZE 1024*1024 // Max cumulative data payload size is 1MB
#define CONNID_MIN 1
#define CONNID_MAX 65535
#define INITIAL_CAPACITY 1000

typedef struct NICPMessageHeader {
    int connectionId;
    struct timespec timestamp;
    char *dataPayload;
    size_t dataSize;
} NICPMessageHeader;

static NICPMessageHeader* nicpHeaders = NULL; // Array of NICP message headers
static size_t capacity = 0; // Current capacity of the array
static size_t size = 0; // Current number of elements in the array
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically allocate memory for NICP message headers
int initializeNicpHeaders() {
    if (capacity == 0) {
        nicpHeaders = malloc(sizeof(NICPMessageHeader) * INITIAL_CAPACITY);
        if (nicpHeaders == NULL) {
            fprintf(stderr, "Failed to allocate memory for NICP message headers\n");
            return -1;
        }
        capacity = INITIAL_CAPACITY;
    }
    return 0;
}

// Function to add a new NICP message header
int addNicpMessage(int connectionId, const char *dataPayload, size_t dataSize) {
    if (connectionId < CONNID_MIN || connectionId > CONNID_MAX) {
        fprintf(stderr, "Invalid connection ID: %d\n", connectionId);
        return -1;
    }

    if (dataSize > MAX_PAYLOAD) {
        fprintf(stderr, "Payload size exceeds maximum limit: %zu bytes\n", dataSize);
        return -1;
    }

    pthread_mutex_lock(&lock); // Start of critical section

    if (size + dataSize > MAX_SIZE) {
        fprintf(stderr, "Maximum size limit exceeded by new payload: %zu bytes\n", dataSize);
        return -1;
    }

    if (size >= capacity) { // Array is full, reallocate more memory
        capacity *= 2;
        nicpHeaders = realloc(nicpHeaders, sizeof(NICPMessageHeader) * capacity);
        if (nicpHeaders == NULL) {
            fprintf(stderr, "Failed to re-allocate memory for NICP message headers\n");
            return -1;
        }
    }

    nicpHeaders[size].connectionId = connectionId;
    clock_gettime(CLOCK_REALTIME, &nicpHeaders[size].timestamp); // Record timestamp
    nicpHeaders[size].dataPayload = malloc(dataSize);
    if (nicpHeaders[size].dataPayload == NULL) {
        fprintf(stderr, "Failed to allocate memory for data payload\n");
        return -1;
    }
    memcpy(nicpHeaders[size].dataPayload, dataPayload, dataSize); // Copy data payload
    nicpHeaders[size].dataSize = dataSize;
    ++size;

    pthread_mutex_unlock(&lock); // End of critical section

    return 0;
}
```
This is a simplistic example and does not include error handling for serialization, the `free` function to clean up all allocated resources, or integration with other system components. It also does not take into account performance constraints such as high-load conditions, optimization of speed, or scalability. For a more complete solution, consider using libraries or frameworks that provide higher level abstractions for these tasks.
