```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU {
    // Structure members here
} NFAPI_CRC_INDICATION_PDU_T;

// Array of structures, each with a mutex for synchronization
typedef struct DynamicArray {
    pthread_mutex_t lock;
    int count;
    NFAPI_CRC_INDICATION_PDU_T* array;
} DynamicArray;

enum ErrorCode {
    E_SUCCESS,
    E_INVALID_RNTI,
    E_ALLOCATION_FAILURE,
    // Other error codes here
};

// Initialization function
DynamicArray* initialize(int initialSize) {
    DynamicArray* da = malloc(sizeof(DynamicArray));
    if (da == NULL) return NULL;

    da->array = calloc(initialSize, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (da->array == NULL) {
        free(da);
        return NULL;
    }

    da->count = 0;
    pthread_mutex_init(&da->lock, NULL);

    return da;
}

// Insert function
ErrorCode insert(DynamicArray* da, NFAPI_CRC_INDICATION_PDU_T value) {
    pthread_mutex_lock(&da->lock);

    // Check RNTI validity
    if (!checkRNTI(value.RNTI)) {
        pthread_mutex_unlock(&da->lock);
        return E_INVALID_RNTI;
    }

    // Reallocate if necessary
    if (da->count == sizeof(da->array) / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        NFAPI_CRC_INDICATION_PDU_T* newArray = realloc(da->array, 2 * da->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newArray == NULL) {
            pthread_mutex_unlock(&da->lock);
            return E_ALLOCATION_FAILURE;
        } else {
            da->array = newArray;
        }
    }

    // Insert value
    da->array[da->count++] = value;

    pthread_mutex_unlock(&da->lock);

    return E_SUCCESS;
}

// Removal function
ErrorCode remove(DynamicArray* da, int index) {
    pthread_mutex_lock(&da->lock);

    // Shift values to fill the gap
    for (int i = index; i < da->count - 1; ++i) {
        da->array[i] = da->array[i + 1];
    }

    // Decrement count and check if realloc is necessary
    --da->count;
    if (da->count <= sizeof(da->array) / (2 * sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
        NFAPI_CRC_INDICATION_PDU_T* newArray = realloc(da->array, sizeof(da->array) / 2);
        if (newArray == NULL && da->count != 0) { // If realloc failed and count isn't already 0
            pthread_mutex_unlock(&da->lock);
            return E_ALLOCATION_FAILURE;
        } else {
            da->array = newArray;
        }
    }

    pthread_mutex_unlock(&da->lock);

    return E_SUCCESS;
}
```
Note that the `checkRNTI` function is not included. You would need to implement this based on your specific requirements, for instance checking if it's within a valid range or meeting application-specific criteria. 

