        list->capacity *= 2;
        NFAPI_RRC_UE_CONTEXT* newList = (NFAPI_RRC_UE_CONTEXT*)realloc(list->contextList, sizeof(NFAPI_RRC_UE_CONTEXT) * list->capacity);
        if (!newList) {
            pthread_mutex_unlock(&(list->lock));
            return;
        }

        list->contextList = newList;
    }

    // Add the element 
    list->contextList[list->size] = newContext;
    (list->size)++;
    pthread_mutex_unlock(&(list->lock));
}

void removeElement(DynamicList* list, size_t index) {
    if (index >= list->size) return;

    pthread_mutex_lock(&(list->lock));
    for (size_t i = index; i < list->size - 1; ++i)
        list->contextList[i] = list->contextList[i + 1];

    (list->size)--;

    // Shrink the array if it is less than half full to save space
    if (list->capacity > list->size * 2 && list->capacity > 1024) {
        list->capacity /= 2;
        NFAPI_RRC_UE_CONTEXT* newList = (NFAPI_RRC_UE_CONTEXT*)realloc(list->contextList, sizeof(NFAPI_RRC_UE_CONTEXT) * list->capacity);
         if (!newList) {
             pthread_mutex_unlock(&(list->lock));
            return;
        }

        list->contextList = newList;
    }

    pthread_mutex_unlock(&(list->lock));
}

void updateElement(DynamicList* list, size_t index, NFAPI_RRC_UE_CONTEXT newContext) {
    if (index >= list->size) return;

    pthread_mutex_lock(&(list->lock));
    list->contextList[index] = newContext;
    pthread_mutex_unlock(&(list->lock));
}

void serializeListToFile(DynamicList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    // Write the number of elements and then all the contexts 
    fwrite(&(list->size), sizeof(size_t), 1, file);
    fwrite(list->contextList, sizeof(NFAPI_RRC_UE_CONTEXT), list->size, file);

    fclose(file);
}

DynamicList* deserializeListFromFile(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    DynamicList* list = createList();
    if (!list) return NULL;

    // Read the number of elements 
    size_t count = 0;
    fread(&count, sizeof(size_t), 1, file);

    while (count > 0) {
        NFAPI_RRC_UE_CONTEXT newContext = {0};
        int readSize = fread(&newContext, sizeof(NFAPI_RRC_UE_CONTEXT), 1, file);

        if (readSize < 1) break; // Error reading the context 

        addElement(list, newContext);

        count--;
    }

    fclose(file);
    return list;
}
```
