#define MIN_KEY 0
#define MAX_KEY 1000
#define MAX_LIST_SIZE 1024

static pthread_mutex_t key_lock = PTHREAD_MUTEX_INITIALIZER;
static int *used_keys = NULL;
static size_t used_key_count = 0;

int generate_unique_key(void) {
    if (used_key_count == MAX_KEY - MIN_KEY + 1) {
        fprintf(stderr, "Error: All keys have been used.\n");
        return -1; // or handle error as needed
    }

    int key;
    while (1) {
        pthread_mutex_lock(&key_lock);
        if ((key = rand() % MAX_KEY + MIN_KEY) && !used_keys[key - MIN_KEY]) break;
        pthread_mutex_unlock(&key_lock);
    }
    used_keys[key - MIN_KEY] = 1;
    pthread_mutex_unlock(&key_lock);
    return key;
}

record_t *create_records(size_t N, int seed) {
    srand(seed); // for rand() function

    used_keys = calloc(MAX_KEY - MIN_KEY + 1, sizeof(*used_keys));
    if (!used_keys) return NULL; // memory allocation failure

    record_t *records = malloc(N * sizeof(*records));
    if (!records) {
        free(used_keys);
        return NULL; // memory allocation failure
    }

    for (size_t i = 0; i < N; ++i) {
        records[i].key = generate_unique_key();
        if (records[i].key == -1) {
            fprintf(stderr, "Error: Failed to generate a unique key.\n");
            // handle error as needed
        }
        pthread_mutex_init(&records[i].lock, NULL);
    }

    return records;
}
