    config* cfg = malloc(sizeof(*cfg));
    if(!cfg) return NULL;  // Handle memory allocation error

    cfg->config_string = strdup(str);
    cfg->integer_value = value;
    sem_init(&cfg->ref_count, 0, 1);

    pthread_mutex_lock(&configs_lock);
    if(configs_count >= configs_capacity) {
        // Resize the array dynamically
        size_t new_capacity = configs_capacity ? configs_capacity * 2 : 1;
        config** new_array = realloc(configs, sizeof(*new_array) * new_capacity);

        if(!new_array) {
            pthread_mutex_unlock(&configs_lock);
            free(cfg->config_string);
            free(cfg);
            return NULL;  // Handle memory allocation error
        }

        configs = new_array;
        configs_capacity = new_capacity;
    }

    log_change(configs_count, "Config created");
    configs[configs_count++] = cfg;
    pthread_mutex_unlock(&configs_lock);

    return cfg;
}

session* create_session(int config_index) {
    if(config_index >= configs_count) { /*...*/ }  // Handle out-of-bounds error

    session* sess = malloc(sizeof(*sess));
    if(!sess) return NULL;  // Handle memory allocation error

    sem_wait(&configs[config_index]->ref_count);  // Increment the reference count
    sess->cfg = configs[config_index];
    sess->timestamp = generate_timestamp();
    sess->session_id = generate_session_id(sess->cfg->config_string);

    pthread_mutex_lock(&sessions_lock);
    sess->next = sessions;  // Add the new session to the head of the list
    sessions = sess;
    pthread_mutex_unlock(&sessions_lock);

