#include <stdlib.h>
#include <pthread.h>
#define MAX_BUFFERS 256 // Maximum number of buffers in the list

typedef struct {
    uint32_t rf_channel;
    uint8_t frame_type;
    int8_t rssi;
} NFAPI_RX_BUFFER_PDU_T;

// List for storing dynamically allocated buffers
NFAPI_RX_BUFFER_PDU_T* buffer_list[MAX_BUFFERS] = {0};
int current_index = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // For thread-safe access to the list

void *allocate_buffer(size_t size) {
    void* buffer = NULL;
    if (posix_memalign(&buffer, 64, size)) {
        // Handle allocation failure
        return NULL;
    }
    memset(buffer, 0, size);
    return buffer;
}

int initialize_buffers(size_t N) {
    if (N > MAX_BUFFERS) {
        // Input parameter exceeds the maximum number of buffers
        return -1;
    }

    for (size_t i = 0; i < N; ++i) {
        pthread_mutex_lock(&lock);

        buffer_list[current_index] = allocate_buffer(sizeof(NFAPI_RX_BUFFER_PDU_T));
        if (!buffer_list[current_index]) {
            // Handle allocation failure
            return -2;
        }
        ++current_index;

        pthread_mutex_unlock(&lock);
    }

    return 0;
}
```
