['Here is a C implementation that meets your requirements. This code creates a dynamic list which stores records. Each record contains an integer key and a long offset value.

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct Record {
    int key;
    long offset;
} Record;

typedef struct List {
    Record *data;
    size_t size;
    size_t capacity;
} List;

void initList(List *list) {
    list->size = 0;
    list->capacity = sizeof(Record);
    list->data = malloc(list->capacity * sizeof(Record));
}

void insertItem(List *list, Record item) {
    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->data = realloc(list->data, list->capacity * sizeof(Record));
    }
    list->data[list->size++] = item;
}

void deleteItem(List *list, int key) {
    for (int i = 0; i < list->size; ++i) {
        if (list->data[i].key == key) {
            list->data[i] = list->data[--list->size];
            return;
        }
    }
}

void printList(const List *list) {
    printf("Total records: %zu\n", list->size);
    for (int i = 0; i < list->size; ++i) {
        printf("Key: %d, Offset: %ld\n", list->data[i].key, list->data[i].offset);
    }
}

void serializeList(const List *list, FILE *file) {
    fwrite(&list->size, sizeof(size_t), 1, file);
    for (int i = 0; i < list->size; ++i) {
        fwrite(&list->data[i], sizeof(Record), 1, file);
    }
}

void deserializeList(List *list, FILE *file) {
    initList(list);
    size_t size;
    while (fread(&size, sizeof(size_t), 1, file)) {
        Record record;
        fread(&record, sizeof(Record), 1, file);
        insertItem(list, record);
    }
}

int main() {
    srand((unsigned int) time(NULL));

    List list;
    initList(&list);

    for (int i = 0; i < 20; ++i) {
        Record record = {.key = rand(), .offset = 0};
        insertItem(&list, record);
    }

    printList(&list);

    FILE *file = fopen("data.bin", "wb");
    if (file != NULL) {
        serializeList(&list, file);
        fclose(file);
    }

    deleteItem(&list, list.data[0].key);  // Delete a record

    printList(&list);

    List new_list;
    file = fopen("data.bin", "rb");
    if (file != NULL) {
        deserializeList(&new_list, file);
        fclose(file);
    }

    printList(&new_list);  // Print the list from the serialized data

    free(list.data);
    free(new_list.data);
    return 0;
}
```
In this code, a dynamic array is used to store the records. The `initList` function initializes an empty list with initial capacity. The `insertItem` and `deleteItem` functions handle inserting new items into the list and deleting existing ones respectively. Serialization and deserialization of the data structure are performed using binary files. 

The code also includes a simple test to demonstrate how you can use it, including writing the list to a file, reading it back in, printing both lists, then cleaning up by freeing memory. You may need to adjust this example to fit your specific needs and constraints. For instance, if the maximum number of records is fixed but not known until runtime, the `initList` function could be adjusted accordingly.
