        data->offsets[data->offsetsSize] = (long)(data->records + data->recordsSize);
        ++data->recordsSize;
        ++data->offsetsSize;
        pthread_mutex_unlock(&data->lock);
    }
    return NULL;
}

int main() {
    DataStore data = {PTHREAD_MUTEX_INITIALIZER, NULL, 0, NULL, 0};

    // Start a thread to handle input
    pthread_t thread;
    if (pthread_create(&thread, NULL, handleInput, &data) != 0) {
        fprintf(stderr, "Error: Unable to create thread.\n");
        exit(1);
    }

    // Wait for input handling to finish
    pthread_join(thread, NULL);

    // Free memory when done
    for (size_t i = 0; i < data.recordsSize; ++i) {
        free(data.records[i]);
    }
    free(data.offsets);
    free(data.records);
}
```
