typedef struct {
    char sourceIP[16];
    char destIP[16];
} SourceDestPair;

typedef struct {
    int timestamp;
    char sourceIP[16];
    char destIP[16];
    int packetSize;
    int latency;
} NetworkLogEntry;

typedef struct {
    SourceDestPair pair;
    double avgPacketSize;
    int medianLatency;
} PerformanceIndicator;

double computeAverage(int* data, size_t n) {
    long sum = 0;
    for (size_t i = 0; i < n; ++i) {
        sum += data[i];
    }
    return ((double)sum) / n;
}

int computeMedian(int* data, size_t n) {
    qsort(data, n, sizeof(int), [](const void *a, const void *b){return *(int*)a - *(int*)b;});
    if (n % 2 == 0)
        return (data[n/2] + data[(n/2)-1]) / 2;
    else
        return data[n/2];
}

int simulateRandomness() {
    return rand() % 101; // generates a random number between 0 and 100
}

PerformanceIndicator* processNetworkLogsAndGeneratePerformanceIndicators(FILE *logFile, size_t n) {
    NetworkLogEntry *entries = malloc(n * sizeof(NetworkLogEntry));
    if (entries == NULL) {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < n; ++i) {
        int res = fscanf(logFile, "%d %15s %15s %d %d", &entries[i].timestamp, entries[i].sourceIP, entries[i].destIP, 
            &entries[i].packetSize, &entries[i].latency);
        if (res == EOF) {
            printf("Unexpected end of file\n");
            exit(EXIT_FAILURE);
        } else if (res != 5) {
            printf("Corrupted log entry at line %zu\n", i + 1);
            exit(EXIT_FAILURE);
        }
    }

    PerformanceIndicator *indicators = malloc(n * sizeof(PerformanceIndicator)); // assuming each unique pair produces an indicator
    if (indicators == NULL) {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    size_t k = 0;
    for (size_t i = 0; i < n; ++i) {
        int found = 0;
        for (size_t j = 0; j < k; ++j) {
            if (strcmp(indicators[j].pair.sourceIP, entries[i].sourceIP) == 0 && 
                strcmp(indicators[j].pair.destIP, entries[i].destIP) == 0) {

                found = 1;
                indicators[j].avgPacketSize = computeAverage(&entries[i].packetSize, n);
                int *latencies = malloc(n * sizeof(int)); // assuming every entry has latency value
                for (size_t l = 0; l < n; ++l) {
                    latencies[l] = entries[l].latency;
                }
                indicators[j].medianLatency = computeMedian(latencies, n);
                free(latencies);
            }
        }

        if (!found) {
            strcpy(indicators[k].pair.sourceIP, entries[i].sourceIP);
            strcpy(indicators[k].pair.destIP, entries[i].destIP);
            indicators[k].avgPacketSize = computeAverage(&entries[i].packetSize, n);
            int *latencies = malloc(n * sizeof(int)); // assuming every entry has latency value
            for (size_t l = 0; l < n; ++l) {
                latencies[l] = entries[l].latency;
            }
            indicators[k].medianLatency = computeMedian(latencies, n);
            free(latencies);
            ++k;
        }
    }

    for (size_t i = 0; i < k; ++i) {
        indicators[i].score = simulateRandomness();
    }

    free(entries);
    return indicators;
}
``` 
