#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char *str;
    int val;
} Config;

typedef struct SessionStruct {
    time_t timestamp;
    Config* config;
    unsigned long sessionId;
    struct SessionStruct* prev;
    struct SessionStruct* next;
} Session;

Session* sessionsHead = NULL;
int numSessions = 0;
unsigned long lastUsedSessionID = 0L;

Config* new_config(char* str, int val){
    Config* config = (Config*)malloc(sizeof(Config));
    if(config == NULL) exit(-1); // Handle memory allocation error.

    config->str = malloc(sizeof(char) * (strlen(str) + 1));
    if(config->str == NULL) exit(-1); // Handle memory allocation error.

    strcpy(config->str, str);
    config->val = val;
    return config;
}

Session* new_session(){
    Session* session = (Session*)malloc(sizeof(Session));
    if(session == NULL) exit(-1); // Handle memory allocation error.

    time(&(session->timestamp));
    session->config = new_config("", 0);
    session->sessionId = ++lastUsedSessionID;
    session->prev = sessionsHead ? sessionsHead->prev : NULL;
    session->next = sessionsHead;

    if(sessionsHead){
        sessionsHead->prev = session;
        session->prev->next = session;
    } else {
        session->prev = session;
    }
    sessionsHead = session; // Update head of the list.
    numSessions++;

    return session;
}

void cleanup_sessions(int retentionTimeInSeconds){
    if(!sessionsHead) return;

    time_t currentTime;
    time(&currentTime);

    Session* current = sessionsHead;
    for(int i = 0; i < numSessions; ++i){
        double differenceInSeconds = difftime(currentTime, current->timestamp);

        if(differenceInSeconds >= retentionTimeInSeconds){
            Session* prevNode = current->prev;
            Session* nextNode = current->next;

            // Remove session from list.
            if(prevNode) prevNode->next = nextNode;
            if(nextNode) nextNode->prev = prevNode;

            if(current == sessionsHead){
                sessionsHead = nextNode;
            }
            numSessions--;
        }

        current = current->next;
    }
}
```

