void* manage_structures() {
    /* Acquire a lock before checking active threads count */
    pthread_mutex_lock(&active_threads_lock);
    if (atomic_fetch_add(&max_active_threads, -1) < 0) {
        log_error("Too many active threads");
        atomic_fetch_add(&max_active_threads, 1); /* Return the count */
        pthread_mutex_unlock(&active_threads_lock);
        return NULL;
    }

