    pthread_mutex_lock(&mutexHead);
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&mutexHead);
}

void cleanup() {
    Node * prev = NULL;
    while (head != NULL) {
        prev = head;
        head = head->next;
        free(prev);
    }
}
