#define MAX_CONNECTIONS 10000

typedef struct Connection{
    char* ip;
    int port;
}Connection;

typedef struct NetworkConfig{
    pthread_mutex_t lock;
    Connection connections[MAX_CONNECTIONS];
    size_t conn_count;
}NetworkConfig;

void init(NetworkConfig *config){
    pthread_mutex_init(&(config->lock), NULL);
    config->conn_count = 0;
}

int addConnection(NetworkConfig *config, const char* ip, int port){
    if (config->conn_count >= MAX_CONNECTIONS) return -1;  // out of space

    pthread_mutex_lock(&(config->lock));
    config->connections[config->conn_count].ip = strdup(ip);
    config->connections[config->conn_count].port = port;
    config->conn_count++;
    pthread_mutex_unlock(&(config->lock));

    return 0;
}

int removeConnection(NetworkConfig *config, const char* ip, int port){
    pthread_mutex_lock(&(config->lock));
    for (size_t i = 0; i < config->conn_count; ++i) {
        if (!strcmp(config->connections[i].ip, ip) && config->connections[i].port == port){
            free(config->connections[i].ip);

            // replace with the last element and decrease count
            config->connections[i] = config->connections[--config->conn_count];
            pthread_mutex_unlock(&(config->lock));

            return 0;  // successfully removed
        }
    }

    pthread_mutex_unlock(&(config->lock));
    return -1;  // connection not found
}
