typedef struct {
    const EVP_MD *type;
    int size;
} HashFunction;

HashFunction* getAvailableHashFunctions() {
    OpenSSL_add_all_digests();

    // Allocate memory to hold all hash functions
    const EVP_DigestMethod *methods = EVP_get_digests();
    int count = 0;
    for (; methods[count].name != NULL; ++count) {}
    HashFunction* availableHashFunctions = malloc(sizeof(HashFunction) * count);

    // Fill the array with available hash functions and their sizes
    int index = 0;
    for (int i = 0; i < count; ++i) {
        const EVP_MD *md = EVP_get_digestbyname(methods[i].name);
        if (md != NULL) {
            availableHashFunctions[index].type = md;
            availableHashFunctions[index].size = EVP_MD_size(md);
            ++index;
        }
    }

    return availableHashFunctions;
}
