['Here is a simple implementation in C language to manage a list of `LTE_RRC_CUCCH_SCH_CONFIGURATION_T` structures. It includes functions for initialization (`init()`), configuration population (`populate()`), cleanup (`cleanup()`), and dynamic scaling (`resize()`). 

This solution uses locks to provide thread-safety, using `pthread_mutex_t` for mutual exclusion. This ensures that only one thread can access the list at a time, preventing potential data corruption or race conditions.

```C
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int CUCCH_FORMAT_TYPE;
    int CUCCH_RESOURCE_INDEX;
    int CUCCH_TRANSMISSION_BANDWIDTH;
} LTE_RRC_CUCCH_SCH_CONFIGURATION_T;

typedef struct {
    pthread_mutex_t lock;
    LTE_RRC_CUCCH_SCH_CONFIGURATION_T* array;
    int size;
    int capacity;
} ConfigList;

ConfigList configList;

void init() {
    if (pthread_mutex_init(&configList.lock, NULL) != 0) {
        printf("\n mutex init failed\n");
        return ;
    }

    configList.size = 0;
    configList.capacity = 1;  // Start with a small size to avoid frequent resizes
    configList.array = malloc(configList.capacity * sizeof(LTE_RRC_CUCCH_SCH_CONFIGURATION_T));
}

void resize() {
    pthread_mutex_lock(&configList.lock);  // Ensure only one thread can resize at a time

    configList.capacity *= 2;  // Double the capacity each time we need to resize
    if (configList.array == NULL) {
        printf("Memory not allocated.\n");
        return ;
    } else {
        LTE_RRC_CUCCH_SCH_CONFIGURATION_T* temp = realloc(configList.array, configList.capacity * sizeof(LTE_RRC_CUCCH_SCH_CONFIGURATION_T));

        if (temp == NULL) {  // Reallocation failed
            free(configList.array);
            printf("Memory not allocated.\n");
            return ;
        } else {
            configList.array = temp;
        }
    }

    pthread_mutex_unlock(&configList.lock);  // Allow other threads to access the list again
}

void populate(LTE_RRC_CUCCH_SCH_CONFIGURATION_T config) {
    pthread_mutex_lock(&configList.lock);  // Lock before accessing and modifying data

    if (configList.size == configList.capacity) {
        resize();  // If there's not enough space, double the capacity
    }

    configList.array[configList.size++] = config;  // Add new configuration to the list

