```c
#include <stdatomic.h>
#include "uthash/src/uthash.h"

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    atomic_uint_fast8_t CRCFLAG;
    UT_hash_handle hh; /* makes this structure hashable */
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct HashTable {
    _Atomic(NFAPI_CRC_INDICATION_PDU_T*) head;
    atomic_flag lock = ATOMIC_FLAG_INIT;
} HashTable;

void insert(HashTable *ht, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI, atomic_uint_fast8_t CRCFLAG) {
    while (atomic_flag_test_and_set(&ht->lock)); // spin until lock is acquired

    NFAPI_CRC_INDICATION_PDU_T* tmp;
    HASH_FIND(hh, ht->head, &RNTI, sizeof(RNTI), tmp); // check if RNTI already exists in the hash table

    if (tmp == NULL) {  // If not found, add a new entry with given values.
        NFAPI_CRC_INDICATION_PDU_T* n = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        n->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        n->RNTI = RNTI;
        atomic_store(&n->CRCFLAG, CRCFLAG);

        HASH_ADD(hh, ht->head, RNTI, sizeof(RNTI), n);  // add to hash table.
    }

    atomic_flag_clear(&ht->lock);  // release lock
}
