    int cell_rnti;
    float mcs;
} NFAPI_RRC_MESSAGE_T;

// Maximum number of messages
#define MAX_MSG 1024

typedef struct MessageContainer {
    pthread_mutex_t mutex;
    NFAPI_RRC_MESSAGE_T* messages[MAX_MSG];
    int size;
} MessageContainer;

void init(MessageContainer *container) {
    pthread_mutex_init(&container->mutex, NULL);
    container->size = 0;
}

int insert(MessageContainer *container, NFAPI_RRC_MESSAGE_T* msg) {
    if (pthread_mutex_lock(&container->mutex)) return -1;

    // Check for overflow
    if (container->size >= MAX_MSG) {
        pthread_mutex_unlock(&container->mutex);
        return -2;
    }

    container->messages[container->size++] = msg;

    pthread_mutex_unlock(&container->mutex);
    return 0;
}

void clear(MessageContainer *container) {
    if (pthread_mutex_lock(&container->mutex)) return;

    for (int i = 0; i < container->size; i++) {
        free(container->messages[i]);
    }

    pthread_mutex_unlock(&container->mutex);
}
```
