public class HashService {
    private ConcurrentMap<NFAPI_CRC_INDICATION_PDU_T, String> cache = new ConcurrentHashMap<>();
    private ExecutorService executor = Executors.newFixedThreadPool(10); // adjust according to your needs

    public Future<String> computeHashAsync(NFAPI_CRC_INDICATION_PDU_T structure) {
        return executor.submit(() -> computeHash(structure));
    }

    private String computeHash(NFAPI_CRC_INDICATION_PDU_T structure) {
        if (cache.containsKey(structure)) {
            return cache.get(structure);
        } else {
            MessageDigest md5 = MessageDigest.getInstance("MD5");
            MessageDigest sha256 = MessageDigest.getInstance("SHA-256");

            String hashValue = md5.digest(structure.toByteArray()) + ":" + sha256.digest(structure.toByteArray());
            cache.putIfAbsent(structure, hashValue);
            return hashValue;
        }
    }
}
