import java.util.*;
import java.security.*;
import javax.xml.bind.DatatypeConverter;
import java.util.concurrent.*;

public class NFAPICRCHandler {
    private static final Logger logger = LoggerFactory.getLogger(NFAPICRCHandler.class);

    private ExecutorService executor;
    private Map<String, String> hashMap;
    private List<Future<String>> futures = new ArrayList<>();

    public NFAPICRCHandler() {
        // Create a thread pool with an optimal number of threads
        this.executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        // Initialize the hashMap as ConcurrentHashMap for thread safety
        this.hashMap = new ConcurrentHashMap<>();
    }

    public void computeHashesAndStore(List<NFAPI_CRC_INDICATION_PDU_T> pdus) {
        // Submit each PDU to the executor service and add returned Future to futures list
        for (NFAPI_CRC_INDICATION_PDU_T pdu : pdus) {
            futures.add(executor.submit(() -> computeAndStoreHash(pdu)));
        }

        // Wait for all Futures to complete, logging any exceptions thrown
        for (Future<String> future : futures) {
            try {
                logger.info("Got hash: " + future.get());
            } catch (InterruptedException | ExecutionException e) {
                logger.error("Error computing or storing hash", e);
            }
        }
    }

    private String computeAndStoreHash(NFAPI_CRC_INDICATION_PDU_T pdu) throws NoSuchAlgorithmException {
        MessageDigest md5 = MessageDigest.getInstance("MD5");
        MessageDigest sha256 = MessageDigest.getInstance("SHA-256");

        // Compute MD5 and SHA-256 hashes
        byte[] md5Bytes = md5.digest(pdu.toByteArray());
        byte[] sha256Bytes = sha256.digest(pdu.toByteArray());

        String hexMd5 = DatatypeConverter.printHexBinary(md5Bytes);
        String hexSha256 = DatatypeConverter.printHexBinary(sha256Bytes);

        // Store hashes in map
        hashMap.put("MD5" + pdu.getRNTI(), hexMd5);
        hashMap.put("SHA-256" + pdu.getRNTI(), hexSha256);

        return "Hash for PDU with RNTI: " + pdu.getRNTI() + "\nMD5 Hash: " + hexMd5 + "\nSHA-256 Hash: " + hexSha256;
    }
}
```

