napi_value readFileSyncWrapper(napi_env env, napi_callback_info info) {
    size_t argc = 1;
    napi_value args[1];
    napi_get_cb_info(env, info, &argc, args, NULL, NULL);

    char path[256];
    napi_get_value_string_utf8(env, args[0], path, 256, NULL);

    FILE* file = fopen(path, "r");
    if (file == NULL) return NULL;

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    rewind(file);

    char* buffer = malloc((size + 1) * sizeof(*buffer));
    if (buffer == NULL) return NULL;

    fread(buffer, 1, size, file);
    fclose(file);

    napi_value result;
    napi_create_string_utf8(env, buffer, size, &result);

    free(buffer);

    return result;
}

