```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char *key;
    long offset;
    double timestamp;
} entry_t;

// Simple cache implementation with LRU eviction strategy
#define CACHE_SIZE 1024
entry_t cache[CACHE_SIZE];
int cache_index = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_to_cache(entry_t entry) {
    pthread_mutex_lock(&lock);

    // Check if the key is already in the cache
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (strcmp(cache[i].key, entry.key) == 0) {
            cache[i] = entry;  // Update existing entry
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    // Add new entry to the cache
    cache[cache_index++ % CACHE_SIZE] = entry;

    pthread_mutex_unlock(&lock);
}

entry_t *get_from_cache(char *key) {
    pthread_mutex_lock(&lock);

    // Search for the key in the cache
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (strcmp(cache[i].key, key) == 0) {
            pthread_mutex_unlock(&lock);
            return &cache[i];  // Return pointer to the entry
        }
    }

    pthread_mutex_unlock(&lock);
    return NULL;  // Key not found in cache
}

entry_t *initialize_array(int size) {
    srand(time(NULL));   // Seed random number generator

    entry_t *entries = (entry_t*) malloc(sizeof(entry_t) * size);
    for (int i = 0; i < size; ++i) {
        entries[i].key = "random_string";  // For simplicity, all keys are the same
        entries[i].offset = rand() % 1000;   // Generate random offset
        entries[i].timestamp = (double) time(NULL);  // Set current timestamp

        add_to_cache(entries[i]);  // Add entry to the cache
    }

    return entries;
}
```

