struct NetworkSession 
{
    std::mutex mtx;
    SessionID id;
    ConnectionState state;
    std::vector<std::unique_ptr<DataPacket>> packets;
    size_t maxSize;

    NetworkSession(size_t max) : maxSize(max), state(DISCONNECTED) {}
};

class SessionManager 
{
private:
    std::mutex mtx; // for thread-safe access to sessions map
    std::unordered_map<SessionID, NetworkSession> sessions;
    size_t totalSessions = 0;
    size_t failedInitializations = 0;
public:
    SessionID initializeNewSession(size_t maxSize) 
    {
        static SessionID idGen = 1; // generator for unique session IDs
        std::lock_guard<std::mutex> lock(mtx);
        if (totalSessions < INT32_MAX) // to prevent overflow of SessionID
        {
            NetworkSession s(maxSize);
            s.id = idGen++;

            try 
            {
                sessions[s.id] = std::move(s);
                ++totalSessions;
                return s.id;
            } 
            catch (const std::bad_alloc&)  // handle memory allocation failure
            {
                ++failedInitializations;
                std::cerr << "Failed to initialize session due to insufficient resources\n";
                throw; // re-throw the exception
            }
        }
        ++failedInitializations;
        return -1;  // Return an invalid SessionID on failure
    }
};
```
This solution uses `std::unique_ptr` for automatic memory management, a mutex per session to ensure thread safety, and unordered_map as the storage container to allow O(1) access time. Error handling mechanism such as exceptions is used in case of insufficient resources during initialization of new sessions. The garbage collection strategy is not implemented here but it could be based on reference counting or LRU (Least Recently Used) algorithms for better efficiency and adaptability to the requirements of different scenarios.
']

['```c
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

typedef struct BearerContext {
    // Add necessary fields here
} BearerContext;

typedef struct UeSessionInfo {
    int RrcConnectionStatus;
    unsigned int Rnti;
    BearerContext* BearerCtx;
    time_t LastActivityTime;
} UeSessionInfo;

typedef struct SessionNode {
    UeSessionInfo* sessionData;
    struct SessionNode* next;
} SessionNode;

SessionNode* Head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

UeSessionInfo* CreateSession(int RrcConnectionStatus, unsigned int Rnti) {
    UeSessionInfo* newSession = (UeSessionInfo*) malloc(sizeof(UeSessionInfo));
    if(newSession == NULL) {
        exit(1);  // Memory allocation failure
    }
    newSession->RrcConnectionStatus = RrcConnectionStatus;
    newSession->Rnti = Rnti;
    newSession->BearerCtx = (BearerContext*) malloc(sizeof(BearerContext));
    if(newSession->BearerCtx == NULL) {
        free(newSession);
        exit(1);  // Memory allocation failure
    }
    time(&newSession->LastActivityTime);

    return newSession;
}

void AddSession(UeSessionInfo* sessionData) {
    SessionNode* newNode = (SessionNode*) malloc(sizeof(SessionNode));
    if(newNode == NULL) {
        exit(1);  // Memory allocation failure
    }
    newNode->sessionData = sessionData;

    pthread_mutex_lock(&lock);
    newNode->next = Head;
    Head = newNode;
    pthread_mutex_unlock(&lock);
}

void RemoveSession(unsigned int Rnti) {
    if(Head == NULL) return;  // Empty list

    pthread_mutex_lock(&lock);
    if(Head->sessionData->Rnti == Rnti) {
        SessionNode* temp = Head;
        Head = Head->next;
        free(temp->sessionData->BearerCtx);
        free(temp->sessionData);
        free(temp);
    } else {
        SessionNode* prev = Head;
        SessionNode* curr = Head->next;
        while(curr != NULL && curr->sessionData->Rnti != Rnti) {
            prev = curr;
            curr = curr->next;
        }
        if(curr != NULL) {
            prev->next = curr->next;
            free(curr->sessionData->BearerCtx);
            free(curr->sessionData);
            free(curr);
        }
    }
    pthread_mutex_unlock(&lock);
}

void CleanupInactiveSessions() {
    time_t currentTime = time(NULL);

    pthread_mutex_lock(&lock);
    SessionNode* curr = Head;
    while(curr != NULL) {
        if(difftime(currentTime, curr->sessionData->LastActivityTime) > 60) {  // Consider sessions inactive after 60 seconds
            RemoveSession(curr->sessionData->Rnti);
        } else {
            curr = curr->next;
        }
    }
    pthread_mutex_unlock(&lock);
}
```

This code provides a basic example of how to manage the linked list with `UeSessionInfo`. It assumes that each session has a unique Rnti, and it uses a simple strategy for cleaning up inactive sessions: all sessions that have not been active for over 60 seconds are considered inactive and removed.

This is a simple example and does not include error handling or logging that might be required in a more robust system. For a production-grade solution, you would want to add comprehensive error checking and possibly integrate with a proper logging framework. Remember, this code only shows the linked list data structure management and thread safety but does not cover the logic of actual session operations such as connection status update or bearer context manipulation etc., which should be implemented according to your specific requirements.
']

