int populate_nfaapi_rx_frames(NFAPI_RX_FRAME_INFO **frames, size_t *size, size_t num_frames, size_t max_frame_bytes, size_t max_total_bytes) {
    if (num_frames == 0 || max_frame_bytes == 0 || max_total_bytes < max_frame_bytes) {
