    size_t total_size = *size * sizeof(NFAPI_RX_FRAME_INFO*);
    if (total_size + num_frames * max_frame_bytes > max_total_bytes) {
        pthread_mutex_unlock(&mutex);
        return -2;  // Memory overflow error code
    }

    NFAPI_RX_FRAME_INFO **new_frames = realloc(*frames, (*size + num_frames) * sizeof(NFAPI_RX_FRAME_INFO*));
    if (new_frames == NULL) {
        pthread_mutex_unlock(&mutex);
        return -3;  // Memory allocation error code
    }

    *frames = new_frames;
    memset(*frames + *size, 0, num_frames * sizeof(NFAPI_RX_FRAME_INFO*));

    for (size_t i = 0; i < num_frames; ++i) {
        (*frames)[*size + i] = malloc(max_frame_bytes);
