int populateRecords(size_t numOffsets, size_t numKeys, const int minKeyVal, const int maxKeyVal, Record** records) {
    if (numOffsets == 0 || numKeys == 0) return -1;  // Empty arrays are invalid
    if ((maxKeyVal-minKeyVal+1) < numKeys) return -2;  // Not enough keys for all possible values

    size_t totalSize = sizeof(long)*numOffsets + sizeof(int)*numKeys + sizeof(Record)*numOffsets;
    if (totalSize > MAX_MEMORY_USAGE) return -3;  // Total memory usage exceeds limit

    long* offsets = malloc(sizeof(long)*numOffsets);
    if (!offsets) return -4;  // Memory allocation failed for offset array

    int* keys = calloc(numKeys, sizeof(int));
    if (!keys) return -5;  // Memory allocation failed for key array

    *records = malloc(sizeof(Record)*numOffsets);
    if (!*records) return -6;  // Memory allocation failed for record array

    int usedKeys[maxKeyVal-minKeyVal+1] = {0};  // Keep track of used keys

    srand(time(0));  // Seed the random number generator

    for (size_t i = 0; i < numOffsets; ++i) {
        offsets[i] = rand();  // Initialize offset values with random numbers

        int keyVal;
        do {
            keyVal = minKeyVal + rand() % ((maxKeyVal+1)-minKeyVal);  // Generate a key value within the specified range
        } while (usedKeys[keyVal-minKeyVal] != 0);  // Ensure key is not already in use

        usedKeys[keyVal-minKeyVal] = 1;  // Mark key as used
        keys[i] = keyVal;  // Initialize key values with unique random numbers

        (*records)[i].value = NULL;  // Initialize value to NULL for each record
        (*records)[i].offset = offsets[i];  // Assign reference to offset value from first array
        (*records)[i].key = keys[i];  // Assign reference to key value from second array
    }

    return 0;  // Success
}
```
