        printf("Mutex initialization failed\n");
        return 1;
    }

    pool.head = pool.tail = NULL;
    atomic_init(&pool.metrics.successful_allocations, 0);
    atomic_init(&pool.metrics.failed_allocations, 0);
    return 0;
}

int allocate(NFAPI_CRC_INDICATION_PDU_T **out, clock_t max_time){
    Node *node = NULL;
    int ret = 1; // assume allocation fails

    clock_t start_time = clock();

    while((clock() - start_time) < max_time){
        if(pthread_mutex_trylock(&pool.lock) == 0){ 
            // try to lock in a non-blocking way

            if (pool.head != NULL){
                node = pool.head;
                pool.head = node->next;

                *out = node->data;
                free(node);

                ret = 0; // allocation succeeded
                atomic_fetch_add(&pool.metrics.successful_allocations, 1);
            } else {
                atomic_fetch_add(&pool.metrics.failed_allocations, 1);
            }

            pthread_mutex_unlock(&pool.lock); // unlock the mutex
            break;
        }
    }

    if(ret == 0){
        return 0;
    } else {
        *out = NULL;
        return -1; // allocation failed due to timeout
    }
}

void deallocate(NFAPI_CRC_INDICATION_PDU_T *data) {
    Node *node = malloc(sizeof(Node));

    if (node == NULL){
        atomic_fetch_add(&pool.metrics.failed_allocations, 1);
        return; // allocation failed
    }

    node->data = data;
    node->next = NULL;

    pthread_mutex_lock(&pool.lock);

    if (pool.tail == NULL){
        pool.head = pool.tail = node;
    } else {
        pool.tail->next = node;
        pool.tail = node;
    }

    pthread_mutex_unlock(&pool.lock);
}
