struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRCFLAG;
};

class PduManager {
public:
    enum class StatusCode { OK, ERR_MEMORY };

    PduManager(uint16_t maxN) : maxCount(maxN), nextRnti(0) {}

    std::pair<StatusCode, uint16_t> getNewPdu() {
        std::lock_guard<std::mutex> lock(poolMutex);

        if (pduPool.size() >= maxCount) {
            return { StatusCode::ERR_MEMORY, 0 }; // Error: pool is full
        }

        NFAPI_CRC_INDICATION_PDU_T newPdu;
        do {
            if (nextRnti == UINT16_MAX) {
                nextRnti = 0;
            } else {
                ++nextRnti;
            }

            newPdu.RX_UE_INFORMATION_TAG = nextRnti; // For simplification, we assume this is also unique and does not interfere with RNTI
        } while (rntiToIndexMap.find(nextRnti) != rntiToIndexMap.end());

        newPdu.RNTI = nextRnti;
        std::bernoulli_distribution dist; // For simplicity, we randomly assign CRCFLAG as true/false 50% of the time
        newPdu.CRCFLAG = dist(randomEngine);

        pduPool.push_back(newPdu);
        rntiToIndexMap[nextRnti] = pduPool.size() - 1;

        std::cout << "Logging: New PDU created with RNTI=" << newPdu.RNTI << ", CRCFLAG=" << newPdu.CRCFLAG << "\n";

        return { StatusCode::OK, nextRnti };
    }

private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> pduPool;
    std::unordered_map<uint16_t, size_t> rntiToIndexMap; // Maps RNTI to index in the pduPool vector
    uint16_t maxCount;
    uint16_t nextRnti;
    std::mutex poolMutex;

    std::default_random_engine randomEngine;
};
