typedef struct {
    time_t timestamp;
    char eventType[32];
    void* data;
} NetworkEventRecord;

typedef struct {
    NetworkEventRecord** events;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* initArray(size_t initialSize) {
    DynamicArray* arr = malloc(sizeof(DynamicArray));
    if (arr == NULL) exit(1);  // Handle error.

    arr->events = calloc(initialSize, sizeof(NetworkEventRecord*));
    if (arr->events == NULL) {
        free(arr);
        exit(2);  // Handle error.
    }

    arr->count = 0;
    arr->capacity = initialSize;

    pthread_mutex_init(&arr->lock, NULL);

    return arr;
}

void addRecord(DynamicArray* arr, NetworkEventRecord* record) {
    pthread_mutex_lock(&arr->lock);

    if (arr->count == arr->capacity) {
        arr->events = realloc(arr->events, sizeof(NetworkEventRecord*) * arr->capacity * 2);
        if (arr->events == NULL) exit(3);  // Handle error.

        memset(&arr->events[arr->count], 0, sizeof(NetworkEventRecord*) * arr->capacity);
        arr->capacity *= 2;
    }

    arr->events[arr->count++] = record;

    pthread_mutex_unlock(&arr->lock);
}

// Note: This function only returns the first occurrence of an event with the specified type. 
NetworkEventRecord* getByType(DynamicArray* arr, const char* type) {
    for (size_t i = 0; i < arr->count; ++i) {
        if (strcmp(arr->events[i]->eventType, type) == 0) return arr->events[i];
    }

    return NULL;  // Return null if no event with the specified type was found.
}

void updateRecordByType(DynamicArray* arr, const char* type, NetworkEventRecord* newRecord) {
    for (size_t i = 0; i < arr->count; ++i) {
        if (strcmp(arr->events[i]->eventType, type) == 0) {
            memcpy(arr->events[i], newRecord, sizeof(NetworkEventRecord));
            break;
        }
    }
}

void freeArray(DynamicArray* arr) {
    for (size_t i = 0; i < arr->count; ++i) {
        if (arr->events[i]) {
            free(arr->events[i]->data);  // Free any data allocated.
            free(arr->events[i]);  // Free the event itself.
        }
    }

    free(arr->events);
    pthread_mutex_destroy(&arr->lock);
    free(arr);
}
```

