} Event;

typedef struct EventList {
    pthread_mutex_t lock;
    Event** events;
    int size;
    int capacity;
} EventList;

EventList* createEventList() {
    EventList* list = malloc(sizeof(EventList));
    list->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    list->capacity = 10;
    list->events = malloc(list->capacity * sizeof(Event*));
    list->size = 0;
    return list;
}

void addEvent(EventList* list, Event* event) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->events = realloc(list->events, list->capacity * sizeof(Event*));
    }

    list->events[list->size++] = event;

    pthread_mutex_unlock(&list->lock);
}

void removeExpiredEvents(EventList* list, time_t threshold) {
    pthread_mutex_lock(&list->lock);

    for (int i = 0; i < list->size; ++i) {
        if (difftime(time(NULL), list->events[i]->timestamp) > threshold) {
            free(list->events[i]);

            // Shift subsequent events to fill gap
            for (int j = i; j < list->size - 1; ++j) {
                list->events[j] = list->events[j + 1];
            }

            --list->size;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

Event* findEventsByType(EventList* list, int type) {
    Event** events = malloc(list->size * sizeof(Event*));
    int count = 0;

    for (int i = 0; i < list->size; ++i) {
        if (list->events[i]->type == type) {
            events[count++] = list->events[i];
        }
    }

    return count ? events : NULL;  // Return NULL if no events found, else the array of events
}
