void add(LTE_MME_ksi_t* data) {
    pthread_mutex_lock(&list_lock);

    Node* new_node = malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = head;
    new_node->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;

    head = new_node;

    pthread_mutex_unlock(&list_lock);
