void remove(LTE_MME_ksi_t* data) {
    if (head == NULL) return;

    pthread_mutex_lock(&list_lock);
    pthread_mutex_lock(&head->lock);

    Node** pp = &head;
    while (*pp != NULL) {
        if ((*pp)->data == data) {
            Node* old_node = *pp;
            *pp = (*pp)->next;

            pthread_mutex_unlock(&old_node->lock);
            pthread_mutex_destroy(&old_node->lock);
            free(old_node->data);
            free(old_node);
        } else {
            pthread_mutex_unlock(&(*pp)->lock);
