fn create_directory_and_manage_resources(name: String, N: usize, MAX_MEMORY_MB: usize, USE_DEFAULT_PATH: bool) -> Result<()> {
    // Check if MEMORY_DIR_PATH is set and valid
    let mut path = env::var("MEMORY_DIR_PATH")?;
    let default_path = format!["/default/", name];

    if fs::metadata(&path)?.is_dir() {
        // If MEMORY_DIR_PATH is not writable, suggest a different path or create a new directory
        match fs::create_dir(format![path, "/", name]) {
            Err(_) => return Err(anyhow::Error::msg("Invalid directory path. Please use a different one or create a new directory")),
            Ok(_) => (),
        }
    } else if USE_DEFAULT_PATH {
        // If MEMORY_DIR_PATH is not set, try to create the directory in a default location
        match fs::create_dir(default_path) {
            Err(_) => return Err(anyhow::Error::msg("Invalid directory path. Please use a different one or create a new directory")),
            Ok(_) => path = default_path,
        }
    } else {
        // If MEMORY_DIR_PATH is not set and USE_DEFAULT_PATH is false, return an error
        return Err(anyhow::Error::msg("Directory path must be specified"));
    }

    let dir = fs::DirBuilder::new().from_iter(&path);

    // Create the structures within the chosen directory
    (0..N).for_each(|_| {
        let mut file = io::BufWriter::new(fs::File::create([dir, "/", rand::random()].to_string()).unwrap());
        serde_json::to_writer(&mut file, NFAPI_CRC_INDICATION_PDU_T::default()).unwrap();
    });

    // Allocate and initialize the arrays
    let offsets = Arc::new(Mutex::new(vec![0; MAX_MEMORY_MB * 1024 * 1024 / std::mem::size_of::<usize>()]));
    let keys = Arc::new(Mutex::new(vec![0; MAX_MEMORY_MB * 1024 * 1024 / std::mem::size_of::<u32>()]));

    // Generate the records
    let (tx, rx) = unbounded();
    thread::spawn(move || {
        let start = Instant::now();

        for offset in &offsets.lock().unwrap()[..MAX_MEMORY_MB * 1024 * 1024 / std::mem::size_of::<usize>()] {
            let key = &keys.lock().unwrap()[*offset as usize];

            if rx.is_empty() || rx.len() < 50 {
                tx.send(key).unwrap();
            } else {
                info[start, "Generated {} keys", key];
            }
        }
    });

    Ok(())
}
```
