```C
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRC_INDICATION_REL8_TAG;  // True or False flag
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_STRUCTURES 10000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    int count;
    pthread_mutex_t mutex;
} ManagedArray;

ManagedArray managedArray;

void init() {
    managedArray.array = malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    managedArray.count = 0;
    pthread_mutex_init(&managedArray.mutex, NULL);
}

void addStructure(int RX_UE_INFORMATION_TAG, int RNTI, bool CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&managedArray.mutex);

    if (managedArray.count >= MAX_STRUCTURES) {
        // Error handling for array full
        return;
    }

    managedArray.array[managedArray.count].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    managedArray.array[managedArray.count].RNTI = RNTI;
    managedArray.array[managedArray.count].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    managedArray.count++;

    pthread_mutex_unlock(&managedArray.mutex);
