Here is a simplified example demonstrating the concept but keep in mind that actual implementation may require significant effort, rigorous testing and debugging. 

```C
#include <stdatomic.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct QueueNode {
    NFAPI_CRC_INDICATION_PDU_T value;
    struct QueueNode *next;
} QueueNode;

typedef struct Queue {
    atomic_int count;
    QueueNode *head;
    QueueNode *tail;
    pthread_mutex_t lock;
} Queue;

QueueNode* newNode(NFAPI_CRC_INDICATION_PDU_T value) {
    QueueNode *temp = malloc(sizeof(QueueNode));
    temp->value = value;
    temp->next = NULL;
    return temp;
}

void enqueue(_Atomic(Queue*) *self, NFAPI_CRC_INDICATION_PDU_T item) {
    Queue old_head, new_head;

    do {
        old_head = atomic_load(self);
        new_head = old_head;

        pthread_mutex_lock(&new_head.lock);

        QueueNode *node = newNode(item);
        if (atomic_load(&old_head.count) == 0) {
            new_head.tail = node;
        } else {
            old_head.tail->next = node;
        }
        new_head.head = node;
        ++new_head.count;
    } while (!atomic_compare_exchange_weak(self, &old_head, new_head));

    pthread_mutex_unlock(&new_head.lock);
}

NFAPI_CRC_INDICATION_PDU_T dequeue(_Atomic(Queue*) *self) {
    Queue old_tail, new_tail;
    do {
        old_tail = atomic_load(self);
        new_tail = old_tail;

        pthread_mutex_lock(&new_tail.lock);
        if (atomic_load(&old_tail.count) == 0) {
            return NULL; // Queue is empty
        } else {
            NFAPI_CRC_INDICATION_PDU_T result = new_tail.head->value;
            --new_tail.count;

            pthread_mutex_unlock(&new_tail.lock);

            free(old_tail.head);
            return result;
        }
    } while (!atomic_compare_exchange_weak(self, &old_tail, new_tail));
}
```

