["Here's a simplified implementation of the above problem in C language. It uses a simple hashmap for storing PCI -> PHY Layer Frame Configuration mapping. For concurrency control it uses a mutex lock on each frame configuration when modifying them. When retrieving measurements results, it copies these into user provided buffer and returns actual number of available measurement result entries.

```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    uint64_t timestamp;
    int32_t signalStrength;
    uint8_t CQI;
} MeasurementResult;

typedef struct {
    uint16_t PCI;
    uint16_t configurationIndex;
    MeasurementResult* measurementResults;
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
} PHYLayerFrameConfiguration;

typedef struct {
    PHYLayerFrameConfiguration** configurations;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ConfigurationCollection;

PHYLayerFrameConfiguration* createConfig(uint16_t PCI, uint16_t configurationIndex) {
    PHYLayerFrameConfiguration* config = malloc(sizeof(PHYLayerFrameConfiguration));
    if (config == NULL) return NULL;

    config->PCI = PCI;
    config->configurationIndex = configurationIndex;
    config->capacity = 10; // initial capacity
    config->measurementResults = malloc(sizeof(MeasurementResult) * config->capacity);
    if (config->measurementResults == NULL) {
        free(config);
        return NULL;
    }

    pthread_mutex_init(&config->lock, NULL);
    config->size = 0;

    return config;
}

void addMeasurementResult(PHYLayerFrameConfiguration* config, MeasurementResult result) {
    pthread_mutex_lock(&config->lock);

    if (config->size == config->capacity) { // reallocate more space when needed
        config->capacity *= 2;
        config->measurementResults = realloc(config->measurementResults, sizeof(MeasurementResult) * config->capacity);
    }

    config->measurementResults[config->size++] = result;

    pthread_mutex_unlock(&config->lock);
}

size_t getMeasurementsForPCI(ConfigurationCollection* collection, uint16_t PCI, MeasurementResult* buffer, size_t bufferSize) {
    PHYLayerFrameConfiguration* config;

    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->size; ++i) { // find the PCI in configurations
        if (collection->configurations[i]->PCI == PCI) {
            config = collection->configurations[i];
            break;
        }
    }
    pthread_mutex_unlock(&collection->lock);

    if (config != NULL) {
        pthread_mutex_lock(&config->lock); // lock config when reading/writing to it

        size_t numToCopy = config->size < bufferSize ? config->size : bufferSize; 
        memcpy(buffer, config->measurementResults, sizeof(MeasurementResult) * numToCopy);

        pthread_mutex_unlock(&config->lock);

        return numToCopy; // returns number of copied measurements
    }

    return 0;
}
```

Please note that this code is a simplified version and does not handle synchronization issues with external data source, error handling or memory management for the entire collection. It also doesn't implement garbage collection mechanism to free up memory when entries are removed, which can be implemented using a hash map data structure like c++ unordered_map in combination with custom allocator and deleter functions.
