NFAPI_CRC_INDICATION_PDU_T getByRNTI(int rnti) {
    // Assuming the list is sorted by RNTI, we can do a binary search for efficiency. 
    Node* low = head;
    Node* high = NULL;
    while (high != low) {
        if (low->data.RNTI == rnti) return low->data;
        if (high && high->data.RNTI == rnti) return high->data;

