```c
#include <stdlib.h>
#include <time.h>

typedef struct {
    time_t timestamp;  // using the system's time representation for simplicity
    int deviceId;      // assuming that a unique identifier can be an integer
    int logLevel;      // assuming a simple numeric level for simplicity
    char* messageContent;  // assuming messages are strings
} DeviceLogEntry;

typedef struct {
    size_t count;   // number of valid entries in the array
    size_t capacity;// total space available, may be greater than count due to resizing
    DeviceLogEntry* data; // pointer to dynamically allocated memory for log entries
} DynamicList;

DynamicList createList(size_t initialCapacity) {
    DynamicList list = {0};
    list.capacity = initialCapacity;
    list.data = malloc(initialCapacity * sizeof(DeviceLogEntry));
    return list;
}

void destroyList(DynamicList* list) {
    free(list->data);
    list->count = 0;
    list->capacity = 0;
}

// Resize the array to newCapacity and copy existing data.
void resizeArray(DeviceLogEntry** array, size_t newCapacity) {
    *array = realloc(*array, newCapacity * sizeof(DeviceLogEntry));
}

void appendToList(DynamicList* list, DeviceLogEntry entry) {
    if (list->count >= list->capacity) {
        size_t newCapacity = list->capacity ? 2 * list->capacity : 1;
        resizeArray(&list->data, newCapacity);
        list->capacity = newCapacity;
    }
    list->data[list->count++] = entry;
}
```
This code does not manage the memory for the `messageContent` field in each DeviceLogEntry. You may need to add allocation and deallocation logic as necessary depending on your exact requirements. For example, if you are storing string data, remember that strings in C must be null-terminated (i.e., they end with a character '\0').
