KeysAndRecordsStruct* allocateMemory(int num_offsets, int num_records, int min_value, int max_value) {
    assert(num_offsets <= MAX_OFFSETS && num_records <= MAX_RECORDS); // Ensure constraints are not exceeded
    OffsetsStruct *offsetsStruct = malloc(sizeof(OffsetsStruct)); 
    KeysAndRecordsStruct *keysAndRecordsStruct = malloc(sizeof(KeysAndRecordsStruct)); 

