    keysAndRecordsStruct->num_records = num_records;

    if (num_offsets == 0 || num_records == 0) return NULL; // Edge case: no memory allocation needed

    offsetsStruct->offsets = calloc(sizeof(long int), num_offsets); 

    keysAndRecordsStruct->keys = malloc(sizeof(int)*num_records);
