    assert(num > 0);
    srand((unsigned int)time(NULL));

    // Allocate memory for the array of items
    item *items = malloc(num * sizeof(item));
    assert(items != NULL);

    for (int i = 0; i < num; i++) {
        double randVal = minVal + ((double)rand() / RAND_MAX) * (maxVal - minVal);

