void insert(long offset, int key, Record record){
    if (number_of_nodes >= 10000) {
        printf("Linked list is at maximum capacity. Insertion not possible.\n");
        return;
    }

    Node *newNode = malloc(sizeof(Node));
    if (!newNode){
        printf("Memory allocation failed.\n");
        exit(EXIT_FAILURE); //Cleanup all allocated resources before exiting
    }
    newNode->offset = offset;
    newNode->key = key;
    newNode->record = record;

