static inline tcp_connection *initializeConnection(int id) {
    if (id < 0) return NULL; // invalid clientID

    tcp_connection *conn = malloc(sizeof(*conn));
    if (!conn) return NULL; 

    conn->clientID = id;
    time(&conn->lastActivityTimestamp); 

    pthread_mutex_init(&conn->lock, NULL); // initialize the lock

    // Initialize message queue with null values (empty)
    for(int i = 0; i < MAX_QUEUE; i++) {
        conn->messageQueue[i] = NULL;
    }
    return conn;
}

static inline void releaseConnection(tcp_connection *conn){
