    }

    return NULL;
}

// Function to manage multiple threads.
void manageThreads(int timePeriod, int numThreads) {
    pthread_t threadId[numThreads];

    for (int i = 0; i < numThreads; ++i) {
        if (pthread_create(&threadId[i], NULL, &collectData, &timePeriod)) {
            logError("Failed to create thread");
            return;
        }
